window.SEARCH_INDEX=[{"t": "Dùng AI an toàn & tỉnh táo", "h": "Dùng AI an toàn & tỉnh táo", "u": "an-toan.html", "x": "Người bạn AI giỏi thật. Nhưng bạn thân đến mấy thì cũng có chuyện mình không kể, và có lúc mình phải hỏi lại \"căn cứ đâu?\". Trang này gom những điều mình mong bạn nắm trước khi đưa công việc thật vào AI: dữ liệu nào được kể, che thông tin thế nào, cài đặt gì cho tài khoản, vì sao bạn ấy bịa và cách bắt lỗi. Hai nỗi lo lớn nhất của dân văn phòng khi dùng AI là lộ dữ liệu và AI bịa . Tin vui là cả hai đều có cách xử lý", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Đèn giao thông dữ liệu", "u": "an-toan.html#den-giao-thong-du-lieu", "x": "Trước khi dán bất cứ thứ gì vào khung chat, dừng lại 3 giây và tự hỏi: thông tin này thuộc đèn nào? Đèn Loại thông tin Cách làm 🟢 Xanh Thông tin công khai: văn bản pháp luật đã ban hành, tin tức, kiến thức chung, mẫu biểu trống, nội dung bạn tự viết mà không nhắc tên ai Kể thoải mái 🟡 Vàng Tài liệu nội bộ: hợp đồng, báo cáo, email, biên bản họp, số liệu kinh doanh Che trước rồi mới đưa : tên người, tên công ty, số ti", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Ví dụ theo ngành", "u": "an-toan.html#vi-du-theo-nganh", "x": "Ngành 🟢 Thoải mái 🟡 Che rồi mới đưa 🔴 Không đưa ⚖️ Pháp lý Luật, nghị định, thông tư đã công bố · bản án đã công khai · mẫu hợp đồng trống · câu hỏi chung như \"điều khoản bất khả kháng thường gồm gì?\" Hợp đồng đang đàm phán · công văn nội bộ · biên bản làm việc · thư tư vấn đã bỏ tên khách Hồ sơ vụ việc kèm tên đương sự · chiến lược tranh tụng · thông tin khách hàng mà bạn có nghĩa vụ bảo mật · tài liệu đóng dấu \"Mật", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Ẩn danh hoá: che trước, dán sau", "u": "an-toan.html#an-danh-hoa-che-truoc-dan-sau", "x": "Ẩn danh hoá là thay thông tin nhận diện bằng mã giả, để AI vẫn hiểu nội dung mà không biết đó là ai. Điều quan trọng nhất: che ngay trên máy của bạn, trước khi dán . Đừng làm Đừng dán bản gốc vào rồi gõ \"che giúp mình tên khách hàng nhé\". Lúc bạn bấm gửi, dữ liệu thật đã rời khỏi máy rồi.", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Bước 1 · Tìm những thứ cần che", "u": "an-toan.html#buoc-1-tim-nhung-thu-can-che", "x": "Đọc lướt tài liệu và đánh dấu: Tên người, kể cả chức danh đi kèm (\"ông A, Giám đốc\") Tên công ty, tên dự án, tên thương hiệu riêng Số hợp đồng, số hoá đơn, mã khách hàng, mã số thuế Số điện thoại, email, địa chỉ cụ thể Số tài khoản, số CCCD, biển số xe Số tiền, đơn giá, khi con số tự nó đã tiết lộ điều gì đó Ngày tháng cụ thể khiến người khác đoán ra vụ việc Logo, chữ ký, con dấu trong ảnh chụp hoặc file PDF", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Bước 2 · Lập bảng thay thế, giữ trên máy bạn", "u": "an-toan.html#buoc-2-lap-bang-thay-the-giu-tren-may-ban", "x": "Mở một file ghi chú riêng, ghi lại \"thật → mã\". File này chỉ bạn giữ , không bao giờ dán vào AI. Ví dụ với dữ liệu hư cấu của trang này: Thông tin thật (chỉ bạn giữ) Thay bằng Công ty TNHH Kệ kho Phú An [BÊN BÁN] Công ty CP Phân phối Thiết bị Văn phòng Sao Mai [BÊN MUA] Trần Thu Hà [NGƯỜI 1] 27/2026/HĐMB/PA-SM [SỐ HĐ] 1.164.240.000đ [TỔNG GIÁ TRỊ] Giữ mã nhất quán : cùng một người thì luôn là [NGƯỜI 1], để bạn ấy hiể", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Bước 3 · Thay hàng loạt bằng Tìm và Thay thế", "u": "an-toan.html#buoc-3-thay-hang-loat-bang-tim-va-thay-the", "x": "Lưu một bản sao tài liệu, thêm chữ \"AN-DANH\" vào tên file. Làm trên bản sao, không đụng bản gốc. Bấm Ctrl + H (Word, Excel, Google Docs đều có). Trên Mac, vào menu Edit (Sửa) > Find (Tìm) > Replace (Thay thế). Ô \"Tìm\": thông tin thật. Ô \"Thay bằng\": mã. Bấm Thay thế tất cả (Replace All). Lặp lại cho từng dòng trong bảng. Nhớ các cách viết khác nhau: \"Công ty Phú An\", \"Cty Phú An\", \"Phú An\", \"PA\". Với Excel, chọn phạm", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Bước 4 · Rà lần cuối", "u": "an-toan.html#buoc-4-ra-lan-cuoi", "x": "Dùng Ctrl + F tìm nhanh vài từ hay lọt lưới: dấu \"@\" (email), \"Công ty\", \"Ông\", \"Bà\", \"STK\", \"Số:\", các đầu số điện thoại. Đọc kỹ phần đầu và phần cuối văn bản, nơi hay có tên, chữ ký, địa chỉ. Đừng quên đầu trang, chân trang, chú thích và tên file.", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Bước 5 · Nhận kết quả, đổi ngược lại", "u": "an-toan.html#buoc-5-nhan-ket-qua-doi-nguoc-lai", "x": "Bạn ấy trả kết quả có [BÊN BÁN], [NGƯỜI 1]… Dán vào Word, dùng bảng thay thế đổi ngược lại thành tên thật. Đọc lại một lượt trước khi gửi đi. Bạn có thể nhờ bạn ấy làm sẵn bảng mẫu mà không cần đưa bất kỳ dữ liệu thật nào:", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Cài đặt quyền riêng tư cho tài khoản cá nhân", "u": "an-toan.html#cai-dat-quyen-rieng-tu-cho-tai-khoan-ca-nhan", "x": "Nếu bạn dùng tài khoản cá nhân (không phải tài khoản do công ty cấp), dành 5 phút làm những việc sau: Tắt tuỳ chọn cho phép dùng dữ liệu của bạn để cải thiện mô hình. Thường nằm trong phần Cài đặt (Settings), ở mục kiểu \"Kiểm soát dữ liệu\" (Data controls) hoặc \"Quyền riêng tư\" (Privacy). Biết chỗ bật trò chuyện tạm thời. Nhiều công cụ có chế độ trò chuyện không lưu vào lịch sử, hợp cho những câu hỏi bạn không muốn gi", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Hỏi công ty trước khi dùng", "u": "an-toan.html#hoi-cong-ty-truoc-khi-dung", "x": "Trong khảo sát của nhóm mình, nhiều bạn trả lời \"không rõ\" công ty có cho dùng AI hay không. Hỏi trước là cách bảo vệ chính bạn. Những câu nên hỏi IT hoặc quản lý: Công ty có cho dùng AI trong công việc không? Có văn bản quy định không? Được dùng công cụ nào? Công ty có cấp tài khoản doanh nghiệp không (ví dụ Copilot trong Microsoft 365, hoặc ChatGPT, Claude bản dành cho tổ chức)? Loại dữ liệu nào tuyệt đối không đượ", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Vì sao AI \"bịa\"?", "u": "an-toan.html#vi-sao-ai-bia", "x": "Người bạn AI không tra cứu sự thật như tra từ điển. Bạn ấy đã \"đọc\" một lượng chữ khổng lồ và học cách dự đoán chữ tiếp theo hợp lý nhất. Giống tính năng gợi ý từ trên bàn phím điện thoại, nhưng giỏi hơn rất, rất nhiều. Vì thế bạn ấy luôn trả lời trôi chảy, kể cả khi không có thông tin. Khi tài liệu không nói, hoặc bạn ấy không biết, bạn ấy có thể đoán ra một câu nghe rất hợp lý. Giới công nghệ gọi đó là \"ảo giác\" (h", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "5 bước kiểm chứng", "u": "an-toan.html#5-buoc-kiem-chung", "x": "Không phải việc gì cũng cần đủ 5 bước. Lời chúc sinh nhật thì không cần. Nhưng thứ gì sẽ ký, nộp, gửi khách hay trình sếp thì nên đi hết. Hỏi căn cứ. Nhờ bạn ấy trích nguyên văn câu trong tài liệu, kèm số Điều hoặc số trang, và nói rõ chỗ nào là suy luận. Tự kiểm 1–2 điểm. Mở bản gốc, dùng Ctrl + F tìm đúng câu được trích. Ưu tiên điểm quan trọng nhất, hoặc điểm nghe \"tiện\" quá. Hỏi \"điểm nào bạn không chắc?\". Bạn ấy", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Vùng rủi ro cao: kiểm kỹ gấp đôi", "u": "an-toan.html#vung-rui-ro-cao-kiem-ky-gap-doi", "x": "Loại thông tin Vì sao dễ sai Kiểm thế nào Trích dẫn pháp luật: số hiệu văn bản, số điều, khoản Dễ nhớ nhầm số, ghép điều của luật này với luật kia, thậm chí \"tạo ra\" một văn bản nghe rất thật Tra văn bản gốc trên nguồn chính thức, đọc đúng điều khoản được dẫn Văn bản đã sửa đổi, thay thế, hết hiệu lực Kiến thức của bạn ấy có mốc thời gian, có thể vẫn dùng bản cũ Hỏi \"văn bản này còn hiệu lực không, căn cứ đâu?\" rồi t", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Bản quyền & bảo mật: những điều cơ bản", "u": "an-toan.html#ban-quyen-bao-mat-nhung-dieu-co-ban", "x": "Nghĩa vụ bảo mật vẫn còn nguyên. Thoả thuận bảo mật, hợp đồng lao động, quy tắc nghề nghiệp của luật sư, kế toán, kiểm toán vẫn áp dụng khi bạn dùng AI. Dán tài liệu của khách vào một dịch vụ bên ngoài có thể là vi phạm, dù không ai biết. Tài liệu của người khác. Nhờ tóm tắt một cuốn sách để tự học khác hẳn việc chép lại nội dung đó để phát hành. Khi viết bài đăng công khai, đừng để AI chép nguyên văn của người khác.", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Bộ câu \"Dám hỏi lại\"", "u": "an-toan.html#bo-cau-dam-hoi-lai", "x": "Copy, dán, dùng cho mọi việc quan trọng.", "k": "page"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Tự kiểm tra", "u": "an-toan.html#tu-kiem-tra", "x": "Mình phân biệt được 3 đèn và kể được 2 ví dụ 🔴 trong ngành của mình Mình đã tắt tuỳ chọn dùng dữ liệu để cải thiện mô hình trên tài khoản cá nhân Mình đã thử ẩn danh một tài liệu bằng bảng thay thế và Ctrl + H Mình biết chính sách AI của công ty, hoặc đã gửi câu hỏi cho người phụ trách Mình giải thích được cho đồng nghiệp vì sao AI \"bịa\" Mình đã dùng ít nhất 2 câu trong bộ \"Dám hỏi lại\" cho một việc thật", "k": "page"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "u": "anh-chup.html", "x": "Thứ gì bạn nhìn thấy, bạn ấy thường cũng đọc được: hoá đơn, bảng trắng, màn hình báo lỗi, tờ khai chi chít ô. Chụp một tấm còn nhanh hơn gõ lại một dòng.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Khi nào dùng", "u": "anh-chup.html#khi-nao-dung", "x": "Thông tin nằm trên giấy, trên màn hình , gõ lại thì mất công. Khó tả bằng lời , như một thông báo lỗi lạ. Giấy tờ khó hiểu , cần người giải thích. Bảng trắng, ghi chú viết tay cần thành văn bản gọn. Ảnh có thông tin đèn đỏ mà không che được thì đừng gửi.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Cách nhờ", "u": "anh-chup.html#cach-nho", "x": "Trong khung chat, bấm dấu cộng, kẹp giấy hoặc biểu tượng ảnh để chụp hay chọn ảnh. Trên Windows, nhấn Windows + Shift + S để chụp một vùng màn hình, rồi thường dán thẳng vào khung chat bằng Ctrl + V . Số ảnh mỗi lần gửi có thể bị giới hạn; kiểm tra trang chính thức vì gói và giới hạn thay đổi thường xuyên. Mẹo chụp: đủ sáng, thẳng góc, mỗi ảnh một tờ. Ảnh không thay được lời kể. Vẫn nói đủ 3 điều như khi giao việc ch", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Làm thật", "u": "anh-chup.html#lam-that", "x": "", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Tình huống 1 · Mười tờ hoá đơn thành bảng chi phí", "u": "anh-chup.html#tinh-huong-1-muoi-to-hoa-don-thanh-bang-chi-phi", "x": "Xấp hoá đơn sau chuyến công tác: trải ra, chụp từng tờ. Bạn sẽ thấy Bảng gọn, copy sang Excel được, vài dòng được đánh dấu \"Cần kiểm tra lại\" vì chữ nhoè, giấy gấp. Soi đúng những dòng đó với giấy gốc, rồi tự cộng lại bằng hàm SUM thay vì tin ngay dòng tổng.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Tình huống 2 · Bảng trắng, ghi chú viết tay thành biên bản", "u": "anh-chup.html#tinh-huong-2-bang-trang-ghi-chu-viet-tay-thanh-bien-ban", "x": "Chụp bảng trắng ngay khi họp xong, trước khi ai đó lau. Ghi chú viết tay trong sổ cũng làm y vậy. Bạn sẽ thấy Phần lớn chữ viết tay được đọc ra, trừ chỗ quá xấu hay bị lau dở. Câu hỏi kiểu \"chữ này là 'Hà' hay 'Hải'?\" là dấu hiệu tốt: hỏi thay vì đoán.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Tình huống 3 · Màn hình báo lỗi thành cách sửa từng bước", "u": "anh-chup.html#tinh-huong-3-man-hinh-bao-loi-thanh-cach-sua-tung-buoc", "x": "Lỗi khó tả bằng lời, chụp lại thì rõ ngay. Nhớ cắt bớt phần màn hình có email, tên khách. Bạn sẽ thấy Bạn ấy đọc lỗi, giải thích bằng lời thường, rồi chỉ bước đầu tiên. Bạn ấy nhắc tới nút bạn không thấy? Chụp tiếp: \"Mình đang thấy thế này, bấm vào đâu?\"", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Tình huống 4 · Tờ khai khó hiểu, giải thích từng ô", "u": "anh-chup.html#tinh-huong-4-to-khai-kho-hieu-giai-thich-tung-o", "x": "Chụp mẫu còn trống . Đừng gửi bản đã điền số CCCD, số tài khoản, và đừng nhờ bạn ấy điền hộ những thông tin đó. Bạn sẽ thấy Danh sách từng ô, dễ hiểu như có người ngồi cạnh chỉ. Mẫu và quy định có thể đã đổi, nên chỗ nào bạn ấy đánh dấu, hỏi lại nơi tiếp nhận.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Tình huống 5 · Biểu đồ trong báo cáo thành nhận xét và câu hỏi", "u": "anh-chup.html#tinh-huong-5-bieu-do-trong-bao-cao-thanh-nhan-xet-va-cau-hoi", "x": "Sắp nghe trình bày? Đọc trước biểu đồ cùng bạn ấy. Bạn sẽ thấy Ba câu tóm tắt, vài điểm đáng ngờ, ba câu hỏi sắc. Số ước lượng từ hình chỉ để hình dung; cần số thật thì xin file gốc.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Dám hỏi lại", "u": "anh-chup.html#dam-hoi-lai", "x": "Ảnh mờ, giấy gấp: bạn ấy có thể đọc 3 thành 8, 1 thành 7, bỏ sót một dòng, nhầm dấu phân cách hàng nghìn. Đọc sai mà vẫn rất tự tin. Soát trước khi dùng số đọc từ ảnh Số dòng trong bảng có bằng số tờ, số mục trong ảnh không? Tổng bạn ấy tính có khớp tổng bạn tự cộng trong Excel không? Các ô \"cần kiểm tra lại\": đã nhìn tận mắt ảnh gốc chưa? Tên riêng, mã số, số hoá đơn: đã so từng ký tự chưa?", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Biến thể theo ngành", "u": "anh-chup.html#bien-the-theo-nganh", "x": "", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "⚖️ Pháp lý", "u": "anh-chup.html#phap-ly", "x": "Công văn giấy vừa nhận: che tên, chụp, nhờ tóm tắt yêu cầu và thời hạn.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "💰 Kế toán – Tài chính", "u": "anh-chup.html#ke-toan-tai-chinh", "x": "Biên bản đối chiếu công nợ bản giấy: chụp, chuyển thành bảng để so với sổ.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "🤝 Kinh doanh – CSKH", "u": "anh-chup.html#kinh-doanh-cskh", "x": "Khách gửi ảnh hàng lỗi: nhờ mô tả và soạn phản hồi, không để bạn ấy kết luận thay bộ phận kỹ thuật.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "🏗️ Vận hành – Xây dựng", "u": "anh-chup.html#van-hanh-xay-dung", "x": "Ảnh hiện trường thành mô tả cho báo cáo sự cố, tách rõ điều thấy và điều đoán.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Còn việc gì giống vậy?", "u": "anh-chup.html#con-viec-gi-giong-vay", "x": "💼 Công việc Slide chụp ở hội thảo thành bản tóm tắt Phiếu nhập kho viết tay thành bảng Sơ đồ vẽ tay thành quy trình từng bước Bảng giá ở hội chợ thành bảng so sánh 🏡 Đời sống Tủ lạnh thành thực đơn 3 ngày Sách hướng dẫn tiếng nước ngoài thành tiếng Việt Bài tập của con: nhờ giải thích cách làm, không giải hộ Hoá đơn điện nước: so với tháng trước Thứ gì nhìn thấy mà ngại gõ lại, cứ chụp và nhờ. Riêng con số đọc từ ảnh", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Tự kiểm tra", "u": "anh-chup.html#tu-kiem-tra", "x": "Đã gửi thử một ảnh giấy tờ và một ảnh chụp màn hình. Đã nhờ bạn ấy liệt kê chỗ đọc không chắc, và soi lại với ảnh gốc. Đã tự cộng lại tổng thay vì tin ngay dòng tổng. Đã cắt hoặc che thông tin cá nhân trước khi gửi.", "k": "topic"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Đi xa hơn", "u": "anh-chup.html#di-xa-hon", "x": "Dọn tiếp. Bảng chi phí từ hoá đơn có thể làm sạch tiếp như ở Bậc 3 . Dạy bạn ấy một lần. Ngày nào cũng chụp hiện trường, bảng trắng? Tạo trợ lý biết sẵn mẫu báo cáo như ở Bậc 5 . Chụp rồi nói. Gửi ảnh, rồi kể bối cảnh bằng giọng như ở Nói thay vì gõ . Ảnh nhạy cảm? Xem lại An toàn .", "k": "topic"}, {"t": "Làm quen người bạn AI", "h": "Làm quen người bạn AI", "u": "bat-dau.html", "x": "Chào bạn. Nếu bạn đang đọc trang này một mình, ở nhà, sau một ngày làm việc, thì trang web này được viết cho đúng bạn. Không cần người hướng dẫn, không cần biết kỹ thuật, không cần cài đặt gì. Bạn chỉ cần một trình duyệt, khoảng 30 phút mỗi lần ngồi, và một chút tò mò. Mình gọi AI là người bạn , vì cách làm việc hiệu quả nhất với AI hoá ra rất giống cách làm việc với một con người: kể cho bạn ấy nghe chuyện, nhờ bạn ", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Ba câu để nhớ", "u": "bat-dau.html#ba-cau-de-nho", "x": "Ba câu để nhớ AI là người bạn siêu nhiên: đa nhiệm, ngày càng giỏi. Dám nhờ mọi thứ, và dám hỏi lại mọi thứ. Không biết nhờ thế nào? Hỏi thẳng bạn ấy.", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "1. AI là người bạn siêu nhiên: đa nhiệm, ngày càng giỏi", "u": "bat-dau.html#1-ai-la-nguoi-ban-sieu-nhien-da-nhiem-ngay-cang-gioi", "x": "Bạn ấy viết, đọc, tóm tắt, tính toán, vẽ biểu đồ, thậm chí làm được cả ứng dụng nhỏ, giúp cả việc công ty lẫn việc nhà. Và bạn ấy giỏi lên rất nhanh: việc tháng trước làm chưa tốt, tháng này có thể đã làm được. Đừng coi bạn ấy là ô tìm kiếm, đừng gõ từ khoá. Hãy nói chuyện như với một đồng nghiệp rất giỏi vừa vào công ty sáng nay.", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "2. Dám nhờ mọi thứ, và dám hỏi lại mọi thứ", "u": "bat-dau.html#2-dam-nho-moi-thu-va-dam-hoi-lai-moi-thu", "x": "Vế đầu: việc gì muốn, cứ mạnh dạn nhờ, kể cả việc bạn nghĩ \"chắc AI không làm được đâu\". Một lần nhờ thử chỉ tốn 30 giây. Vế sau: việc gì quan trọng, cứ hỏi lại \"căn cứ đâu?\". AI đôi khi đoán, và đoán rất tự tin. Mình tin bạn ấy vì mình biết cách kiểm tra bạn ấy, chứ không tin mù quáng. Bậc 2 dành riêng cho chuyện này.", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "3. Không biết nhờ thế nào? Hỏi thẳng bạn ấy", "u": "bat-dau.html#3-khong-biet-nho-the-nao-hoi-thang-ban-ay", "x": "Bạn không cần học \"kỹ thuật viết prompt\". Khi bí, cứ nói thật: \"mình muốn làm việc này mà không biết nhờ sao, bạn cần biết gì thì hỏi mình\". Bạn ấy sẽ hỏi lại từng câu, như một đồng nghiệp tận tâm.", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Và khi giao việc: nói rõ ba điều", "u": "bat-dau.html#va-khi-giao-viec-noi-ro-ba-dieu", "x": "Tháng 10/2026, Boris Cherny, người tạo ra Claude Code, nói đúng tinh thần này: \"Hãy nói chuyện với Claude như nói với một đồng nghiệp. Prompt chẳng có bí mật gì cả.\" Khi giao việc, chỉ cần nói rõ muốn gì , bỏ bao nhiêu công sức , và kiểm tra thế nào . Đọc kỹ ở trang Giao việc như giao cho đồng nghiệp .", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Vì sao nên bắt đầu ngay hôm nay", "u": "bat-dau.html#vi-sao-nen-bat-dau-ngay-hom-nay", "x": "Andrej Karpathy, đồng sáng lập OpenAI, ước lượng: khoảng 6 tỷ người gần như chưa chạm vào AI, 1–2 tỷ người dùng thỉnh thoảng, và chỉ khoảng 20 triệu người dùng bản mạnh nhất cho việc chuyên môn. Khoảng cách giữa các tầng đang nới rộng. Không phải AI tạo ra khoảng cách, cách mình dùng AI tạo ra khoảng cách. Mỗi bậc trên trang này là một bước đi xuống phễu. Xem bạn đang ở đâu và kế hoạch 30 ngày ở trang Khoảng cách AI ", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Trang web này được sắp xếp thế nào", "u": "bat-dau.html#trang-web-nay-duoc-sap-xep-the-nao", "x": "Trang có bốn phần, đọc theo thứ tự nào cũng được: Nền tảng (3 trang, đọc trước): trang này, Khoảng cách AI , Giao việc như giao cho đồng nghiệp . 7 bậc , tương ứng 7 cách nhờ, đi theo đúng cách một tình bạn lớn dần: làm quen, tin tưởng, giao việc nhỏ, dạy bạn ấy, cùng sáng tạo, rồi giao cả đầu việc. 7 chuyên đề thực chiến , đọc theo nhu cầu: giọng nói, ảnh chụp, tra cứu có nguồn, họp hành, học nhanh, giọng văn, một n", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Học thế nào khi chỉ có một mình", "u": "bat-dau.html#hoc-the-nao-khi-chi-co-mot-minh", "x": "Lộ trình mình gợi ý: Mỗi ngày một bậc , hoặc mỗi lần ngồi một bậc, khoảng 20–40 phút. Đừng làm dồn 7 bậc trong một tối: cách nhờ cần thời gian để ngấm. Xem trước 3–5 phút : mở phần trình chiếu của bậc đó (nút \"Xem phần trình chiếu\" ở đầu mỗi bài) để thấy cả câu chuyện, rồi mới vào bài đọc. Mở hai cửa sổ cạnh nhau : bài học một bên, ChatGPT hoặc Claude một bên. Trên Windows, nhấn Windows + ← để ghim cửa sổ sang nửa tr", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Chuẩn bị tài khoản", "u": "bat-dau.html#chuan-bi-tai-khoan", "x": "Khoảng 15 phút, làm một lần là xong.", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Tạo tài khoản miễn phí", "u": "bat-dau.html#tao-tai-khoan-mien-phi", "x": "ChatGPT (của OpenAI): vào chatgpt.com và đăng ký. Claude (của Anthropic): vào claude.ai và đăng ký. NotebookLM (của Google): vào notebooklm.google.com , đăng nhập bằng tài khoản Google. Bạn sẽ dùng nó ở bậc 2 để đọc tài liệu dài. Bản miễn phí đủ cho phần lớn bài tập. Gói và giới hạn thay đổi thường xuyên, nên hãy xem trang chính thức của từng công cụ, hoặc trang Công cụ .", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Tắt tuỳ chọn dùng dữ liệu để huấn luyện mô hình", "u": "bat-dau.html#tat-tuy-chon-dung-du-lieu-de-huan-luyen-mo-hinh", "x": "Với tài khoản cá nhân, nội dung bạn trò chuyện có thể được dùng để cải thiện mô hình AI, tuỳ theo cài đặt. Bạn nên tắt tuỳ chọn này: ChatGPT: vào Settings (Cài đặt) → Data controls , tìm tuỳ chọn về việc dùng nội dung của bạn để cải thiện mô hình, và tắt nó. Claude: vào Settings → Privacy , tìm tuỳ chọn cho phép dùng cuộc trò chuyện để cải thiện Claude, và tắt nó. Công cụ khác (Gemini, NotebookLM, Copilot…): tìm tron", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Đèn giao thông dữ liệu", "u": "bat-dau.html#den-giao-thong-du-lieu", "x": "Bạn thân đến mấy cũng có chuyện mình không kể. Với AI cũng vậy. Loại dữ liệu Có kể cho bạn ấy không? 🟢 Thông tin công khai: văn bản pháp luật, tin tức, kiến thức chung Thoải mái 🟡 Tài liệu nội bộ: hợp đồng, báo cáo, email công việc Che trước : tên người, tên công ty, số tiền, mã số 🔴 Thông tin khách hàng, số tài khoản, mật khẩu, dữ liệu chưa công bố Không kể Cách che nhanh và các tình huống hay gặp có ở trang An toàn", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Chiêu tối thượng: \"Hỏi thẳng bạn ấy\"", "u": "bat-dau.html#chieu-toi-thuong-hoi-thang-ban-ay", "x": "Khi không biết bắt đầu từ đâu, chọn một câu bên dưới, thay phần trong [ngoặc vuông], rồi gửi. Vì sao hiệu quả: người bạn AI biết rất rõ mình cần thông tin gì để làm tốt, chỉ là sẽ không hỏi nếu bạn không mời. Khi bạn mời, cuộc trò chuyện đổi chiều. Bạn không phải nghĩ ra câu nhờ hoàn hảo nữa, chỉ việc trả lời, như được một đồng nghiệp giỏi phỏng vấn. Thử ngay Dùng câu 0c với nghề của bạn. Trong 10 việc bạn ấy gợi ý, ", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Bạn đang ở đâu?", "u": "bat-dau.html#ban-dang-o-dau", "x": "Không ai bắt bạn phải đi từ bậc 1. Tìm dòng giống bạn nhất: Nếu bạn… Bắt đầu từ Tập trung vào Chưa dùng AI bao giờ, hoặc mới thử vài lần Bậc 1 Đi lần lượt, mỗi ngày một bậc Thỉnh thoảng hỏi ChatGPT, nhưng thấy kết quả chung chung Bậc 1 Bậc 1–2: cách kể bối cảnh và cách hỏi lại Dùng ChatGPT hằng ngày để viết và hỏi đáp Lướt bậc 1–2, nhưng vẫn làm bẫy ở bậc 2 Bậc 3–5: làm việc với file, nhiều thành phẩm trong một cuộc ", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Tài nguyên đi kèm", "u": "bat-dau.html#tai-nguyen-di-kem", "x": "Thư viện prompt : toàn bộ câu mở lời của 7 bậc ở một chỗ, lọc được theo ngành. Công cụ : mỗi công cụ AI hợp với việc gì. Từ điển : những từ như prompt, Project, agent, giải thích dễ hiểu. Hỏi đáp : những câu hay gặp khi mới làm bạn với AI. An toàn : đèn giao thông dữ liệu và cách che thông tin. Thử thách 7 ngày : 7 ngày, 7 lần nhờ.", "k": "page"}, {"t": "Làm quen người bạn AI", "h": "Tự kiểm tra", "u": "bat-dau.html#tu-kiem-tra", "x": "Nhớ được ba câu, và hiểu vì sao có vế \"dám hỏi lại\". Đã tạo tài khoản ChatGPT và Claude. Đã mở thử NotebookLM bằng tài khoản Google. Đã tắt tuỳ chọn dùng dữ liệu để huấn luyện mô hình ở tài khoản cá nhân (hoặc đã hỏi IT nếu là tài khoản công ty). Biết dữ liệu nào xanh, vàng, đỏ. Đã thử chiêu \"Hỏi thẳng bạn ấy\" ít nhất một lần. Đã chọn được cấp để bắt đầu. Xong hết các ô rồi? Sang Bậc 1 thôi. Hẹn gặp bạn ở đó.", "k": "page"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Bạn sẽ làm được gì", "u": "cap-1.html#ban-se-lam-duoc-gi", "x": "Thấy tận mắt vì sao nhờ một câu cụt lủn thì nhận về một email sáo rỗng. Kể bối cảnh như kể cho một đồng nghiệp mới, mà không cần thuộc công thức nào. Để bạn ấy hỏi bạn từng câu, thay vì ngồi nghĩ ra một \"prompt hoàn hảo\". Nhờ bạn ấy đóng vai người nhận khó tính để chê thẳng, rồi viết lại. Mang cách nhờ này sang mọi việc cần chọn lời: tin nhắn khó nói, thư xin nghỉ, lời chúc, bài phát biểu.", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Vì sao cách nhờ này hiệu quả", "u": "cap-1.html#vi-sao-cach-nho-nay-hieu-qua", "x": "Hãy tưởng tượng bạn có một đồng nghiệp mới, viết rất giỏi, nhưng vừa vào công ty sáng nay. Bạn chỉ nói đúng một câu: \"Viết giúp email trả lời khách về vụ giao hàng chậm.\" Người đó phải đoán gần hết: khách là ai, chậm bao lâu, lỗi tại ai, bù đắp gì. Khi phải đoán, người ta chọn cách an toàn nhất, tức là những câu sáo rỗng ai cũng viết được. Người bạn AI cũng vậy. Email chung chung không phải lỗi của bạn ấy, mà do mình", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Chuẩn bị", "u": "cap-1.html#chuan-bi", "x": "Công cụ: ChatGPT ( chatgpt.com ) hoặc Claude ( claude.ai ). Bản miễn phí là đủ. File: bài này không cần file mẫu. Thời gian: khoảng 20 phút. Tình huống: dùng tình huống mẫu bên dưới, hoặc một email thật bạn đang phải viết. Nếu dùng chuyện thật, nhớ che tên khách, tên công ty và số tiền trước khi kể (xem đèn giao thông dữ liệu ). Tình huống mẫu (hư cấu) Bạn là chuyên viên chăm sóc khách hàng của Công ty CP Phân phối T", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Làm thật: từng bước", "u": "cap-1.html#lam-that-tung-buoc", "x": "", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Bước 1 · Nhờ kiểu \"người lạ\" để thấy khác biệt", "u": "cap-1.html#buoc-1-nho-kieu-nguoi-la-de-thay-khac-biet", "x": "Mở một cuộc trò chuyện mới và cố tình nhờ thật cụt lủn, đúng kiểu mình hay làm khi vội: Đừng bỏ qua bước này. Bạn cần tận mắt nhìn \"bản chung chung\" một lần để thấy rõ các bước sau khác ở đâu. Bạn sẽ thấy Một email đúng ngữ pháp, lịch sự, nhưng ai đọc cũng biết là thư mẫu: \"Kính gửi Quý khách\", \"Chúng tôi vô cùng lấy làm tiếc…\", vài chỗ trống kiểu [Tên khách hàng]. Không lý do cụ thể, không ngày giao mới. Gửi email n", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Bước 2 · Hỏi thẳng bạn ấy: để bạn ấy hỏi bạn từng câu", "u": "cap-1.html#buoc-2-hoi-thang-ban-ay-de-ban-ay-hoi-ban-tung-cau", "x": "Lần này kể ngắn gọn tình huống, rồi mời bạn ấy hỏi: Trả lời ngắn, tự nhiên như nhắn tin, dựa vào tờ ghi chú tình huống: \"khách quen 3 năm, chị Lan, trưởng phòng HC\" là đủ. Khi thấy đã đủ, nói \"Đủ rồi, bạn viết đi.\" Vì sao hiệu quả: bạn không phải tự nghĩ xem cần kể gì. Bạn ấy biết một email xin lỗi tốt cần gì, nên sẽ hỏi đúng chỗ. Bạn chỉ việc trả lời. Bạn sẽ thấy Những câu hỏi rất \"nghề\": khách là ai, chậm bao lâu v", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Bước 3 · Nhờ góp ý thẳng: bạn ấy đóng vai người nhận", "u": "cap-1.html#buoc-3-nho-gop-y-thang-ban-ay-dong-vai-nguoi-nhan", "x": "Email đã khá. Nhưng \"khá\" chưa chắc đủ để gửi cho một khách đang giận. Mời bạn ấy đổi vai: Vì sao hiệu quả: khi đóng vai người nhận, bạn ấy đọc bằng cảm xúc của người nhận chứ không bằng con mắt của người viết. Những câu bạn thấy \"lịch sự\" có khi lại nghe như đang né trách nhiệm. Bạn sẽ thấy Ba lời chê cụ thể, có khi hơi \"đau\": xin lỗi còn chung chung, \"trong 2 ngày tới\" chưa rõ ngày nào, ưu đãi đặt đầu thư nghe như ", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Bước 4 · Chốt bản cuối và soi chỗ bạn ấy tự thêm", "u": "cap-1.html#buoc-4-chot-ban-cuoi-va-soi-cho-ban-ay-tu-them", "x": "Vế cuối rất quan trọng. Để email trôi chảy, bạn ấy hay \"điền cho đủ\": thêm số hotline, lời hứa \"giao trước 10 giờ sáng\", một ưu đãi công ty bạn không hề có. Bắt bạn ấy tự khai ra thì bạn soát nhanh hơn nhiều. Bạn sẽ thấy Hai email hoàn chỉnh để bạn chọn, kèm danh sách những chỗ bạn ấy tự thêm (giờ giao cụ thể, tên người phụ trách, số điện thoại…). Sửa hoặc xoá những chỗ đó là có thể gửi.", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Bước 5 · Khi đã quen: nhờ một lần cho trọn", "u": "cap-1.html#buoc-5-khi-da-quen-nho-mot-lan-cho-tron", "x": "Sau vài lần để bạn ấy hỏi, bạn sẽ tự biết cần kể gì. Lúc đó có thể giao một lần cho trọn, như giao cho một đồng nghiệp: muốn gì, bối cảnh, công sức, kiểm tra thế nào. Câu cuối là \"lưới an toàn\": dù bạn kể kỹ đến đâu, bạn ấy vẫn được phép hỏi lại. Câu áp chót là phần \"kiểm tra\": bạn ấy tự soát trước khi đưa cho bạn. Bạn sẽ thấy Một email tốt ngay từ lần đầu, hoặc bạn ấy hỏi thêm 1–2 câu trước khi viết. Với email quan ", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Dám hỏi lại", "u": "cap-1.html#dam-hoi-lai", "x": "Với email, \"AI bịa\" không phải là bịa số liệu như ở bậc 2, mà là hứa thay bạn hoặc nói thay bạn . Một email trôi chảy nhưng cam kết điều công ty không làm được còn tệ hơn một email vụng. Trước khi bấm gửi, hỏi lại bạn ấy: Soát 1 phút trước khi gửi Tên, chức danh của người nhận có đúng không? Ngày giờ, con số có khớp với thực tế không? Cam kết có nằm trong quyền của bạn không? Ví dụ bạn chỉ được duyệt giảm 5%, email l", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Biến thể theo ngành", "u": "cap-1.html#bien-the-theo-nganh", "x": "", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "⚖️ Pháp lý", "u": "cap-1.html#phap-ly", "x": "Công văn trả lời cơ quan nhà nước cần chặt chẽ, đúng thể thức và không thừa nhận quá mức. Để bạn ấy hỏi trước về căn cứ và thời hạn.", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "💰 Kế toán – Tài chính", "u": "cap-1.html#ke-toan-tai-chinh", "x": "Nhắc nợ lần hai là kiểu email khó viết nhất: phải cương quyết mà vẫn giữ được khách.", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "🤝 Kinh doanh – CSKH", "u": "cap-1.html#kinh-doanh-cskh", "x": "Từ chối mà không mất khách: kể rõ giới hạn của bạn để bạn ấy tìm cách \"đổi\" thay vì chỉ nói \"không\".", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "🏗️ Vận hành – Xây dựng", "u": "cap-1.html#van-hanh-xay-dung", "x": "Thông báo gửi nhiều người cần ngắn, rõ, và trả lời trước những câu mọi người sẽ hỏi.", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Còn việc gì giống vậy?", "u": "cap-1.html#con-viec-gi-giong-vay", "x": "💼 Công việc Tin nhắn báo sếp rằng dự án sẽ trễ hạn Email từ chối một đề nghị hợp tác mà vẫn giữ cửa Trả lời đánh giá 1 sao của khách trên mạng Thư xin nghỉ phép dài ngày đúng mùa cao điểm Lời chúc Tết gửi từng đối tác, mỗi người một kiểu Góp ý cho nhân viên mà không làm họ nản 🏡 Đời sống Bài phát biểu ở đám cưới bạn thân Tin nhắn làm hoà sau một lần cãi nhau Nhắc khéo người quen trả khoản tiền đã mượn Thư gửi cô giáo", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Khi kết quả chưa như ý", "u": "cap-1.html#khi-ket-qua-chua-nhu-y", "x": "Bạn gặp Vì sao Nói với bạn ấy thế này Email vẫn sáo rỗng, giống thư mẫu Bạn ấy thiếu chi tiết riêng nên phải đoán \"Bỏ hết câu sáo. Dùng đúng những chi tiết mình đã kể, viết như một người thật đang nói chuyện với chị Lan.\" Email dài quá, khách khó đọc hết Bạn chưa nói độ dài mong muốn \"Rút còn dưới 120 chữ, 3 đoạn ngắn. Hai dòng đầu phải nói được: xin lỗi, và bao giờ có hàng.\" Giọng quá khúm núm, hoặc quá cứng Bạn ấy ", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Tự kiểm tra", "u": "cap-1.html#tu-kiem-tra", "x": "Đã thử nhờ cụt lủn và thấy kết quả chung chung ra sao. Đã để bạn ấy hỏi mình ít nhất 3 câu trước khi viết. Đã nhờ bạn ấy đóng vai người nhận và nhận được 3 lời chê cụ thể. Đã hỏi \"chỗ nào bạn tự thêm?\" và sửa lại trước khi gửi. Đã nghĩ ra một việc của riêng mình, công việc hoặc đời sống, sẽ nhờ theo cách này trong tuần.", "k": "lesson"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Đi xa hơn", "u": "cap-1.html#di-xa-hon", "x": "Dạy bạn ấy giọng văn của bạn. Dán 2–3 email cũ (đã che tên và số) rồi nói: \"Học giọng văn của mình qua mấy email này, từ giờ viết theo giọng đó.\" Viết sẵn đoạn giới thiệu bản thân 3–4 câu: bạn là ai, làm ở đâu, thường viết cho ai. Dán vào đầu mỗi cuộc trò chuyện. Ở Bậc 5 , bạn sẽ dạy bạn ấy nhớ luôn. Kể bằng giọng nói. Trên điện thoại, bật chế độ giọng nói, kể tình huống như kể cho đồng nghiệp, rồi nhờ bạn ấy soạn em", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Bạn sẽ làm được gì", "u": "cap-2.html#ban-se-lam-duoc-gi", "x": "Biết dữ liệu nào kể thoải mái, dữ liệu nào phải che, dữ liệu nào không đưa cho AI. Tóm tắt một hợp đồng 10 điều kèm phụ lục theo góc nhìn bên mua: ai làm gì, hạn khi nào, chỗ nào bất lợi. Tự tay đặt bẫy để thấy AI \"đoán\" như thế nào, và vì sao. Nhờ chính bạn ấy chỉ cách kiểm tra bạn ấy, rồi đòi trích nguyên văn kèm số Điều. Đối chiếu trích dẫn với tài liệu gốc trong 2 phút, kể cả khi bạn không phải dân luật.", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Vì sao cách nhờ này hiệu quả", "u": "cap-2.html#vi-sao-cach-nho-nay-hieu-qua", "x": "Đọc kỹ một hợp đồng 6–7 trang kèm phụ lục và tìm hết chỗ bất lợi thường mất cả buổi. Người bạn AI đọc xong trong vài giây. Câu hỏi là: có tin được không? Câu trả lời của mình: AI không nói dối, nó đoán. Khi bạn hỏi điều tài liệu không nói, bạn ấy hiếm khi đáp \"không có\". Bạn ấy muốn giúp, nên tìm thứ gần giống nhất trong tài liệu hoặc lấy từ kiến thức chung, rồi trả lời rất tự tin. Càng trôi chảy, mình càng dễ tin. A", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Chuẩn bị", "u": "cap-2.html#chuan-bi", "x": "", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Đèn giao thông dữ liệu", "u": "cap-2.html#den-giao-thong-du-lieu", "x": "Bạn thân đến mấy cũng có chuyện mình không kể. Với AI cũng vậy. Trước khi upload bất kỳ tài liệu nào, hãy nhìn đèn: Loại dữ liệu Có đưa cho bạn ấy không? 🟢 Công khai: văn bản pháp luật, tin tức, kiến thức chung, tài liệu đã công bố Thoải mái 🟡 Nội bộ: hợp đồng, báo cáo, email công việc Che trước: tên người, tên công ty, số tiền, mã số (số hợp đồng, mã số thuế) 🔴 Bí mật: thông tin khách hàng, số tài khoản, mật khẩu, d", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Công cụ và file", "u": "cap-2.html#cong-cu-va-file", "x": "Công cụ: Claude ( claude.ai ) hoặc ChatGPT ( chatgpt.com ), cả hai đều nhận file Word. Thêm NotebookLM ( notebooklm.google.com ) nếu muốn thử Bước 6. Bản miễn phí có thể giới hạn số file hoặc số lượt upload; giới hạn thay đổi thường xuyên, hãy xem trang chính thức. Thời gian: khoảng 30 phút. Vai của bạn: người phụ trách pháp chế của bên mua . File: hợp đồng mẫu bên dưới. Tải hợp đồng mẫu (.docx) Hợp đồng mua bán kệ k", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Làm thật: từng bước", "u": "cap-2.html#lam-that-tung-buoc", "x": "", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Bước 1 · Upload hợp đồng và nhờ tóm tắt như nói chuyện", "u": "cap-2.html#buoc-1-upload-hop-dong-va-nho-tom-tat-nhu-noi-chuyen", "x": "Mở cuộc trò chuyện mới, bấm biểu tượng đính kèm (hình ghim hoặc dấu +), chọn file, rồi gõ: Câu \"Mình là bên mua\" là chìa khoá. Cùng một điều khoản, bên bán thấy \"chặt chẽ\", bên mua thấy \"thiệt\". Nói rõ bạn đứng ở đâu thì bạn ấy mới biết soi theo hướng nào. Bạn sẽ thấy Một bản tóm tắt gọn: các bên, giá trị, thanh toán, giao hàng, bảo hành, phạt vi phạm, tranh chấp. Cuối cùng là danh sách điểm bất lợi hoặc mơ hồ cho bê", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Bước 2 · Đặt bẫy: một câu hỏi nghe rất bình thường", "u": "cap-2.html#buoc-2-dat-bay-mot-cau-hoi-nghe-rat-binh-thuong", "x": "Để bẫy dễ \"ăn\", hãy mở một cuộc trò chuyện mới , upload lại file, rồi hỏi luôn câu dưới đây, không nói gì thêm: Câu này ai mua hàng cũng muốn biết, nhưng nó là một cái bẫy. Cứ hỏi và ghi lại câu trả lời. Trước khi đọc, thử tự đoán: hợp đồng có ghi mức phạt cụ thể không? Bạn sẽ thấy Thường là một trong hai kiểu: Một con số rất tự tin , ví dụ một tỷ lệ phần trăm hoặc một mức phạt theo ngày, kèm số Điều nghe rất có lý. ", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Bước 3 · Hỏi thẳng bạn ấy: \"Làm sao để mình biết bạn không bịa?\"", "u": "cap-2.html#buoc-3-hoi-thang-ban-ay-lam-sao-de-minh-biet-ban-khong-bia", "x": "Đây là khoảnh khắc chính của bậc này. Ngay trong cuộc trò chuyện có câu bẫy, hỏi: Vì sao hiệu quả: bạn không cần học kỹ thuật kiểm chứng nào. Bạn ấy biết mình hay sai ở đâu, nên sẽ tự chỉ cách bắt lỗi chính mình. Bạn sẽ thấy Những gợi ý rất thực tế: trích nguyên văn kèm số Điều hoặc số trang, tách phần \"tài liệu nói\" với phần \"suy luận\", nói thẳng \"không tìm thấy\" khi tài liệu không có. Nhiều khi bạn ấy còn tự nhận r", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Bước 4 · Làm theo chính gợi ý của bạn ấy", "u": "cap-2.html#buoc-4-lam-theo-chinh-goi-y-cua-ban-ay", "x": "Rồi hỏi lại câu bẫy, lần này với \"luật chơi\" mới: Bạn sẽ thấy Câu trả lời đổi hẳn chất: mỗi ý đi kèm một câu trong ngoặc kép và số Điều. Với câu bẫy, bạn ấy trích một điều khoản cụ thể, và nếu lần trước đoán sai thì thường tự đính chính. Giờ bạn đã có thứ để đối chiếu.", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Bước 5 · Tự mở hợp đồng ra đối chiếu", "u": "cap-2.html#buoc-5-tu-mo-hop-dong-ra-doi-chieu", "x": "Bước nhiều người bỏ qua, nhưng quan trọng nhất. Mở hợp đồng bằng Word, nhấn Ctrl + F , gõ \"7.2\", rồi \"5.2\". So từng chữ câu bạn ấy trích với câu trong file. Không cần kiểm mọi câu. Chọn 1–2 câu quan trọng nhất (ảnh hưởng đến quyết định ký hay không) hoặc chọn ngẫu nhiên. Câu trích không khớp từng chữ là tín hiệu đỏ: bạn ấy đang diễn đạt lại hoặc nhớ nhầm. Khi đó, nói thẳng: Bạn sẽ thấy Điều 7.2 chỉ nói hai bên sẽ \"cù", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Bước 6 · (Tuỳ chọn) NotebookLM: trích dẫn bấm được", "u": "cap-2.html#buoc-6-tuy-chon-notebooklm-trich-dan-bam-duoc", "x": "Với tài liệu dài hoặc nhiều tài liệu cùng lúc, NotebookLM của Google rất đáng thử: mỗi câu trả lời có số trích dẫn nhỏ, bấm vào là nhảy thẳng tới đoạn gốc . Việc đối chiếu ở Bước 5 nhanh hơn hẳn. Vào notebooklm.google.com, tạo notebook mới, thêm hợp đồng làm nguồn. Nếu không tải lên được file .docx, mở bằng Word, lưu thành PDF (File → Save As → PDF) rồi tải lên. Sau đó hỏi: Bạn sẽ thấy Các số nhỏ cạnh từng ý. Rê chuộ", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Dám hỏi lại", "u": "cap-2.html#dam-hoi-lai", "x": "Ở bậc này, \"dám hỏi lại\" là cả bài học. Gói lại thành ba câu nên hỏi với mọi tài liệu quan trọng: \"Căn cứ đâu? Trích nguyên văn kèm số Điều.\" \"Chỗ nào là bạn suy luận, chỗ nào tài liệu nói thẳng?\" \"Có điều khoản nào dẫn chiếu đến một tài liệu khác mà mình chưa đưa cho bạn không?\" Câu thứ ba hay bị bỏ quên. Hợp đồng thật thường nhắc đến phụ lục, quy chế, báo giá… Thiếu tài liệu nào, bạn ấy chỉ phân tích được phần mình", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Biến thể theo ngành", "u": "cap-2.html#bien-the-theo-nganh", "x": "", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "⚖️ Pháp lý", "u": "cap-2.html#phap-ly", "x": "So sánh hai phiên bản văn bản là việc bạn ấy làm rất nhanh, nhưng càng phải đòi trích dẫn vì sai một chữ là sai nghĩa.", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "💰 Kế toán – Tài chính", "u": "cap-2.html#ke-toan-tai-chinh", "x": "Với báo cáo tài chính, đòi bạn ấy chỉ ra con số gốc nằm ở đâu trước khi tin bất kỳ phần trăm thay đổi nào.", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "🤝 Kinh doanh – CSKH", "u": "cap-2.html#kinh-doanh-cskh", "x": "Hồ sơ mời thầu thường dài và có những điều kiện \"không đáp ứng là loại ngay\". Nhờ bạn ấy tách riêng những điều kiện đó.", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "🏗️ Vận hành – Xây dựng", "u": "cap-2.html#van-hanh-xay-dung", "x": "Hợp đồng thi công có nhiều nghĩa vụ và mốc thời gian dễ bị bỏ sót, nhất là khi nằm rải rác trong phụ lục.", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Còn việc gì giống vậy?", "u": "cap-2.html#con-viec-gi-giong-vay", "x": "💼 Công việc Quy chế công ty mới ban hành: điều gì ảnh hưởng đến phòng mình? Thông tư, nghị định mới: thay đổi gì so với văn bản cũ? Biên bản họp dài 10 trang: ai nhận việc gì, hạn khi nào? Hồ sơ năng lực của đối tác: điểm mạnh, điểm cần hỏi thêm Hướng dẫn sử dụng phần mềm mới: 5 thao tác mình cần dùng hằng ngày 🏡 Đời sống Hợp đồng thuê nhà trước khi ký: điều gì bất lợi cho người thuê? Điều khoản bảo hiểm: trường hợp ", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Khi kết quả chưa như ý", "u": "cap-2.html#khi-ket-qua-chua-nhu-y", "x": "Bạn gặp Vì sao Nói với bạn ấy thế này Câu \"trích nguyên văn\" không khớp với file Bạn ấy diễn đạt lại thay vì chép đúng \"Câu này không khớp với file. Chép đúng từng chữ, kể cả dấu câu. Không tìm thấy thì nói không tìm thấy.\" Tóm tắt chung chung, không chỉ ra điểm bất lợi Bạn ấy chưa biết bạn đứng ở phía nào \"Mình là bên mua. Đọc lại với con mắt luật sư của bên mua, liệt kê từng điểm bất lợi kèm số Điều.\" Bạn ấy báo kh", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Tự kiểm tra", "u": "cap-2.html#tu-kiem-tra", "x": "Phân biệt được dữ liệu 🟢 🟡 🔴 và biết che gì trước khi upload tài liệu thật. Đã nhờ tóm tắt hợp đồng theo góc nhìn bên mua và so với đáp án. Đã thử câu bẫy và hiểu vì sao AI hay đoán 8% hoặc 0,1%/ngày. Đã hỏi \"làm sao để mình biết bạn không bịa?\" và làm theo gợi ý của bạn ấy. Đã tự mở hợp đồng, đối chiếu ít nhất một câu trích dẫn. (Tuỳ chọn) Đã thử NotebookLM và bấm vào một trích dẫn.", "k": "lesson"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Đi xa hơn", "u": "cap-2.html#di-xa-hon", "x": "Nhờ soạn luôn đề xuất sửa đổi. \"Dựa trên 3 điểm bất lợi, soạn giúp mình đề xuất sửa đổi gửi bên bán, lời lẽ hợp tác.\" Rồi dùng chiêu của Bậc 1 : nhờ bạn ấy đóng vai pháp chế bên bán để phản biện trước. Hỏi chéo hai công cụ. Đưa cùng tài liệu, cùng câu hỏi cho cả Claude và ChatGPT. Chỗ nào hai bên trả lời khác nhau, đó là chỗ bạn cần tự đọc kỹ. Gom cả bộ hồ sơ vào NotebookLM : hợp đồng, phụ lục, email trao đổi, rồi hỏ", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Bạn sẽ làm được gì", "u": "cap-3.html#ban-se-lam-duoc-gi", "x": "Dùng chiêu \"mình chưa biết nhờ gì, bạn gợi ý đi\" với một file lộn xộn. Dọn một file chi phí 300 dòng: bỏ dòng trùng, thống nhất ngày tháng, tên nhà cung cấp, số tiền. Phân chi phí vào 5 nhóm, tổng hợp theo nhóm và theo tuần, vẽ biểu đồ, tải về file sạch. Bắt bạn ấy giải thích 3 dòng bất kỳ và cách tính, để tự kiểm tra con số. Nhờ bạn ấy viết công thức Excel và giải thích bằng tiếng Việt dễ hiểu.", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Vì sao cách nhờ này hiệu quả", "u": "cap-3.html#vi-sao-cach-nho-nay-hieu-qua", "x": "Ai làm văn phòng cũng từng nhận một file như thế này: mỗi người nhập một kiểu, ngày tháng đủ định dạng, một nhà cung cấp viết năm sáu cách, có dòng trùng, có ô trống. Dọn tay mất cả buổi. Muốn dùng hàm thì phải biết mình cần hàm gì. Cách nhờ ở bậc này đi ngược thói quen: bạn không cần biết mình cần gì . Cứ đưa nguyên đống bừa bộn và hỏi \"bạn thấy làm được gì với cái này?\". Người bạn AI nhìn ra quy luật rất nhanh: \"Gr", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Chuẩn bị", "u": "cap-3.html#chuan-bi", "x": "Công cụ: ChatGPT ( chatgpt.com ) hoặc Claude ( claude.ai ). Bản miễn phí có thể bị giới hạn số file upload, lượt phân tích hoặc khả năng tạo file tải về. Giới hạn thay đổi thường xuyên, hãy xem trang chính thức. Thời gian: khoảng 40 phút (30 phút cho file chi phí, 10 phút cho file công nợ). File: hai file mẫu bên dưới, đều hư cấu. Tải file chi phí tháng 9 (.xlsx) Tải file công nợ mẫu (.xlsx) chi-phi-thang-9.xlsx : 30", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Làm thật: từng bước", "u": "cap-3.html#lam-that-tung-buoc", "x": "", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Bước 1 · Hỏi thẳng bạn ấy: \"Nên làm gì với file này?\"", "u": "cap-3.html#buoc-1-hoi-thang-ban-ay-nen-lam-gi-voi-file-nay", "x": "Mở cuộc trò chuyện mới, upload chi-phi-thang-9.xlsx , rồi gõ đúng tâm trạng của bạn: Vì sao hiệu quả: bạn không phải biết trước tên các thao tác như \"chuẩn hoá\", \"loại trùng\", \"pivot\". Bạn ấy xem file, tự gọi tên vấn đề, rồi đề xuất. Bạn chỉ cần gật hoặc lắc. Bạn sẽ thấy Bạn ấy mô tả nhanh file rồi đề xuất khoảng 5 việc, đại loại: thống nhất định dạng ngày, chuẩn hoá tên nhà cung cấp, đổi số tiền dạng chữ thành số, x", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Bước 2 · Nhờ làm, và nói rõ thành phẩm bạn muốn", "u": "cap-3.html#buoc-2-nho-lam-va-noi-ro-thanh-pham-ban-muon", "x": "Giờ đã biết có thể nhờ gì, hãy nói rõ bạn muốn nhận về cái gì: Mỗi dòng trong câu nhờ đều có lý do: \"Tất cả đều là tháng 9/2026\" để bạn ấy không đọc nhầm 03/09 thành ngày 9 tháng 3 theo kiểu Mỹ. \"Đừng tự điền\" ngăn bạn ấy \"đoán cho đẹp\" những ô đang trống. \"Tuần từ thứ Hai đến Chủ nhật\" để cách chia tuần khớp với đáp án. \"Mỗi loại bao nhiêu dòng\" cho bạn con số để kiểm tra ở bước sau. Bạn sẽ thấy Bảng tổng hợp theo 5", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Bước 3 · Dám hỏi lại ngay: giải thích 3 dòng bất kỳ", "u": "cap-3.html#buoc-3-dam-hoi-lai-ngay-giai-thich-3-dong-bat-ky", "x": "Khoan tải file về. Hỏi trước đã: Mở file gốc, tìm đúng 3 dòng đó và so. Thêm một dòng do chính bạn chọn : dòng \"lạ\" nhất bạn thấy khi lướt file (số tiền có chữ \"đ\", ngày kiểu \"05 tháng 9\", ô trống…), rồi hỏi: \"Dòng [số] bạn xử lý thế nào?\" Vì sao hiệu quả: kiểm 3–4 dòng, nhất là dòng khó, là cách nhanh nhất để biết bạn ấy làm cẩn thận hay làm ẩu. Giống kế toán trưởng kiểm xác suất chứng từ. Bạn sẽ thấy Với mỗi dòng: ", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Bước 4 · Tải file về và tự kiểm bằng Excel", "u": "cap-3.html#buoc-4-tai-file-ve-va-tu-kiem-bang-excel", "x": "Giờ mới tải file về. Chưa quen tự kiểm trong Excel thì nhờ bạn ấy chỉ: Thường là: chọn cột Số tiền rồi nhìn tổng (Sum) ở thanh trạng thái góc dưới bên phải; bật bộ lọc (Filter) ở cột Nhà cung cấp để xem danh sách tên; nhìn số dòng cuối bảng. Bạn sẽ thấy Một file gọn gàng: ngày cùng một định dạng, mỗi nhà cung cấp chỉ còn một tên trong bộ lọc, có cột Nhóm chi phí, có thể có thêm sheet tổng hợp và biểu đồ. Tổng ở thanh", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Bước 5 · Nhờ viết công thức Excel, giải thích bằng tiếng Việt", "u": "cap-3.html#buoc-5-nho-viet-cong-thuc-excel-giai-thich-bang-tieng-viet", "x": "Nhiều khi bạn không cần bạn ấy làm hộ, mà cần một công thức để tự dùng mãi. Mở cong-no-mau.xlsx xem cấu trúc. Không cần upload, chỉ cần mô tả bảng bằng lời: Vì sao phải nói \"dấu ;\": Excel trên nhiều máy cài định dạng Việt Nam dùng dấu chấm phẩy để ngăn các phần trong công thức, vì dấu phẩy đã dùng làm dấu thập phân. Công thức viết bằng dấu phẩy dán vào sẽ báo lỗi. Để bạn hình dung: ý tưởng cho cột E là \"nếu ô D trống", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Dám hỏi lại", "u": "cap-3.html#dam-hoi-lai", "x": "Với số liệu, câu hỏi lại này nên thành phản xạ. Quay lại cuộc trò chuyện về file chi phí và hỏi: So câu trả lời với đáp án bên dưới. Nếu lệch, đọc phần \"Vì sao hay lệch\" trong đáp án. Tự kiểm bằng chính Excel, không cần tin ai Trên một bản sao của file gốc, chọn toàn bảng, vào Data → Remove Duplicates (Excel tiếng Việt: thẻ Dữ liệu, nút loại bỏ trùng lặp). Excel sẽ báo đã xoá bao nhiêu dòng trùng. Chọn cột Số tiền, n", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Biến thể theo ngành", "u": "cap-3.html#bien-the-theo-nganh", "x": "", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "⚖️ Pháp lý", "u": "cap-3.html#phap-ly", "x": "Danh sách hồ sơ vụ việc do nhiều người nhập cũng lộn xộn không kém file chi phí, mà trễ hạn thì hậu quả lớn hơn nhiều.", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "💰 Kế toán – Tài chính", "u": "cap-3.html#ke-toan-tai-chinh", "x": "Sao kê tải từ ngân hàng thường rất khó đọc: diễn giải dài, viết tắt, không phân loại. Nhớ xoá số tài khoản trước khi upload.", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "🤝 Kinh doanh – CSKH", "u": "cap-3.html#kinh-doanh-cskh", "x": "Danh sách đơn hàng là mỏ vàng nếu được dọn sạch: biết ai là khách quan trọng, ai đang rời đi.", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "🏗️ Vận hành – Xây dựng", "u": "cap-3.html#van-hanh-xay-dung", "x": "Nhật ký sự cố ghi tay mỗi người một kiểu, nhưng chứa câu trả lời cho câu hỏi \"nên ưu tiên bảo trì cái gì trước\".", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Còn việc gì giống vậy?", "u": "cap-3.html#con-viec-gi-giong-vay", "x": "💼 Công việc Danh sách khách hàng gom từ nhiều nguồn, vừa trùng vừa sai chính tả Ghi chú họp viết vội → biên bản có người phụ trách và hạn chót Ảnh chụp bảng trắng sau buổi brainstorm → danh sách ý tưởng đã nhóm Kết quả đăng ký sự kiện từ Google Form, mỗi người điền một kiểu Ảnh chụp chồng hoá đơn công tác phí → bảng kê để quyết toán 🏡 Đời sống Chụp ảnh 20 hoá đơn đi chợ → tổng hợp chi tiêu theo nhóm Danh sách khách m", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Khi kết quả chưa như ý", "u": "cap-3.html#khi-ket-qua-chua-nhu-y", "x": "Bạn gặp Vì sao Nói với bạn ấy thế này Không upload được file, hoặc báo hết lượt Giới hạn của bản miễn phí Dán khoảng 30 dòng vào chat: \"Đây là 30 dòng mẫu. Làm mẫu cách dọn, rồi chỉ mình công thức hoặc thao tác để tự làm phần còn lại.\" Tổng tiền lệch so với đáp án Thường do quên đổi số tiền dạng chữ, hoặc bỏ trùng sai \"Liệt kê các dòng có số tiền không phải dạng số và cách bạn xử lý. Bạn coi thế nào là trùng? Tính lạ", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Tự kiểm tra", "u": "cap-3.html#tu-kiem-tra", "x": "Đã để bạn ấy xem file và gợi ý những việc nên làm. Đã có file sạch: có cột Nhóm chi phí, tổng hợp theo nhóm và theo tuần, có biểu đồ. Đã nhờ bạn ấy giải thích 3 dòng bất kỳ và tự đối chiếu với file gốc. Đã hỏi số dòng trùng và tổng tiền, rồi so với đáp án. Đã có công thức cho cột E, F của file công nợ và chạy được trong Excel.", "k": "lesson"}, {"t": "Excel lộn xộn thành sạch", "h": "Đi xa hơn", "u": "cap-3.html#di-xa-hon", "x": "Ghi lại \"công thức nấu ăn\". \"Viết lại các bước bạn vừa dọn thành hướng dẫn, để tháng sau mình đưa file mới là làm y hệt.\" Hoặc dạy bạn ấy nhớ luôn ở Bậc 5 . Chữa tận gốc. Hỏi: \"Làm sao để tháng sau file nhập liệu không lộn xộn nữa?\" Bạn ấy có thể gợi ý danh sách thả xuống (Data Validation) cho tên nhà cung cấp và chỉ bạn làm từng bước. Tự động hoá bằng Power Query. Tháng nào cũng dọn một kiểu file? Nhờ bạn ấy hướng d", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Bạn sẽ làm được gì", "u": "cap-4.html#ban-se-lam-duoc-gi", "x": "Đi từ bảng số liệu đến báo cáo một trang và bộ slide 6 trang mà không phải giải thích lại từ đầu . Để bạn ấy hỏi bạn 3 câu về sếp và cuộc họp, nhờ vậy báo cáo viết đúng \"gu\" người đọc. Nhờ bạn ấy đóng vai một Giám đốc tài chính khó tính, vặn bạn 3 câu hóc búa, rồi sửa báo cáo để trả lời trước. Biến báo cáo thành slide có biểu đồ, xem ngay trên màn hình hoặc mang sang PowerPoint, Google Slides. Dùng cách \"nói tiếp\" ch", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Vì sao cách nhờ này hiệu quả", "u": "cap-4.html#vi-sao-cach-nho-nay-hieu-qua", "x": "Ở Bậc 3 , bạn đã cùng bạn ấy dọn sạch 300 dòng chi phí tháng 9 và ra con số tổng 384.070.000đ . Trong cuộc trò chuyện đó, bạn ấy đã biết hết: file có những cột nào, nhóm chi phí nào lớn, tuần nào chi nhiều, dòng nào bị trùng. Nhiều người làm xong một việc là mở chat mới cho việc tiếp theo. Làm vậy chẳng khác gì tự xoá trí nhớ của người bạn vừa làm cùng mình cả buổi. Trong cùng một cuộc trò chuyện, bạn ấy nhớ mọi thứ ", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Chuẩn bị", "u": "cap-4.html#chuan-bi", "x": "Công cụ: ChatGPT hoặc Claude, bản miễn phí là đủ (có giới hạn lượt dùng, kiểm tra trang chính thức vì giới hạn thay đổi thường xuyên). Để có slide dạng trang web bấm chạy được, Claude (Artifacts) hoặc ChatGPT (Canvas) cho kết quả trực quan nhất. Cuộc trò chuyện ở Bậc 3: tìm lại đúng cuộc trò chuyện đó trong danh sách lịch sử bên trái và mở ra. Đừng mở chat mới. Bỏ qua Bậc 3? Không sao. Dùng bảng số liệu đã làm sạch ở", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Làm thật: từng bước", "u": "cap-4.html#lam-that-tung-buoc", "x": "", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Bước 1 · Nói tiếp, đừng mở chat mới", "u": "cap-4.html#buoc-1-noi-tiep-dung-mo-chat-moi", "x": "Mở lại cuộc trò chuyện ở Bậc 3. Trước khi làm gì mới, nhờ bạn ấy nhắc lại những gì hai bên đã có. Đây vừa là khởi động, vừa là kiểm tra trí nhớ của bạn ấy. Nếu bạn bỏ qua Bậc 3, mở một cuộc trò chuyện mới và dán nguyên khối số liệu đã làm sạch này: Bạn sẽ thấy Hai bảng nhỏ, tổng đúng 384.070.000đ . Hai nhóm lớn nhất là Dịch vụ thuê ngoài (34,9%) và Tiếp khách (31,7%), cộng lại khoảng hai phần ba tổng chi. Tuần 4 (21–", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Bước 2 · Hỏi thẳng bạn ấy: sếp là người thế nào?", "u": "cap-4.html#buoc-2-hoi-thang-ban-ay-sep-la-nguoi-the-nao", "x": "Một báo cáo tốt không chỉ đúng số mà còn đúng người đọc. Sếp thích số hay thích chữ? Đọc trên điện thoại hay in ra? Họp 5 phút hay 30 phút? Bạn ấy không biết, nên hãy để bạn ấy hỏi. Trả lời ngắn, tự nhiên như nhắn tin. Ví dụ: \"Sếp bận, hay đọc trên điện thoại giữa hai cuộc họp\" , \"Sếp thích số, ghét dài dòng, câu cửa miệng là 'vậy đề xuất gì?'\" , \"Báo cáo dùng cho họp giao ban sáng thứ Hai, mình có 5 phút\" . Bạn sẽ t", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Bước 3 · Viết báo cáo một trang", "u": "cap-4.html#buoc-3-viet-bao-cao-mot-trang", "x": "Giờ mới nhờ viết. Hãy nói rõ khung bạn muốn: một trang, tóm tắt 3 câu, 3 phát hiện có số, 2 việc đề xuất. Khung càng rõ, sếp đọc càng nhanh. Câu cuối là bài học từ Bậc 2 : khoanh vùng nguồn số liệu thì bạn ấy ít \"đoán\" hơn hẳn. Bạn sẽ thấy Một báo cáo đọc trong một phút. Phần tóm tắt nêu ngay tổng 384.070.000đ và hai nhóm chi lớn nhất. Các phát hiện thường xoay quanh: Dịch vụ thuê ngoài và Tiếp khách chiếm khoảng 2/3", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Bước 4 · Để \"sếp khó tính\" vặn trước", "u": "cap-4.html#buoc-4-de-sep-kho-tinh-van-truoc", "x": "Đây là bước nhiều người bỏ qua mà lại đáng giá nhất. Bạn nhờ bạn ấy đổi vai: từ người viết báo cáo thành người đọc khó tính nhất, một Giám đốc tài chính chuyên hỏi xoáy. Đọc 3 câu hỏi. Câu nào bạn trả lời được thì kể cho bạn ấy. Câu nào chưa có số liệu thì cũng nói thật. Sau đó: Bạn sẽ thấy Những câu hỏi rất giống sếp thật, kiểu: \"Tiếp khách 121 triệu một tháng, so với tháng 8 thế nào?\" , \"Nhóm 'Khác' gần 50 triệu là", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Bước 5 · Biến báo cáo thành 6 slide", "u": "cap-4.html#buoc-5-bien-bao-cao-thanh-6-slide", "x": "Báo cáo đã chắc tay, giờ đến slide. Vẫn trong cùng cuộc trò chuyện. Trên Claude: slide hiện ở khung bên cạnh cuộc trò chuyện (Artifact). Bấm qua từng slide để xem. Trên ChatGPT: nếu bạn ấy mở Canvas, tìm nút xem trước để chạy thử. Nếu chỉ thấy một khối code dài, nói: \"Gộp thành một file HTML duy nhất để mình lưu về và mở bằng trình duyệt.\" Quen PowerPoint hoặc Google Slides hơn? Xin dàn ý, rồi tự dán vào từng slide: ", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Bước 6 · Mang thành phẩm đi họp", "u": "cap-4.html#buoc-6-mang-thanh-pham-di-hop", "x": "Có báo cáo và slide rồi, giờ là chuyện mang đi đâu, mở bằng gì. Giao diện mỗi công cụ một khác và thay đổi liên tục, nên cách nhanh nhất vẫn là hỏi thẳng. Bạn sẽ thấy Bạn ấy chỉ cách tải file về, mở toàn màn hình, lưu PDF. Nếu bạn ấy nhắc tới một nút mà bạn không thấy trên màn hình, chụp màn hình gửi bạn ấy và hỏi: \"Mình đang thấy thế này, bấm vào đâu?\" . Chụp màn hình là cách hỏi nhanh nhất khi lạc trong giao diện. ", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Dám hỏi lại", "u": "cap-4.html#dam-hoi-lai", "x": "Báo cáo đẹp mà sai một con số là mất uy tín cả bài. Lỗi hay gặp nhất ở bậc này là lệch số khi chuyển định dạng : từ bảng sang báo cáo, từ báo cáo sang slide, bạn ấy đôi khi làm tròn, ghi nhầm nhãn biểu đồ, hoặc \"thêm\" một con số so sánh không có trong dữ liệu. Dám hỏi lại Tổng có khớp không? Tổng chi phí phải là 384.070.000đ. Năm nhóm cộng lại phải ra đúng con số đó. Bấm máy tính mất 30 giây. Slide có giống báo cáo k", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Biến thể theo ngành", "u": "cap-4.html#bien-the-theo-nganh", "x": "", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "⚖️ Pháp lý", "u": "cap-4.html#phap-ly", "x": "Rà soát xong một hợp đồng ở Bậc 2 ? Nói tiếp để có memo rủi ro gửi Ban Giám đốc, rồi vài slide cho buổi họp duyệt ký.", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "💰 Kế toán – Tài chính", "u": "cap-4.html#ke-toan-tai-chinh", "x": "Từ bảng công nợ đã có cột \"Số ngày quá hạn\" ở Bậc 3, đi tiếp thành báo cáo tuổi nợ và slide cho Kế toán trưởng.", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "🤝 Kinh doanh – CSKH", "u": "cap-4.html#kinh-doanh-cskh", "x": "Bảng doanh số tháng thành báo cáo cho trưởng phòng và màn mở đầu cho buổi họp sales đầu tuần.", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "🏗️ Vận hành – Xây dựng", "u": "cap-4.html#van-hanh-xay-dung", "x": "Nhật ký sự cố bảo trì của cả quý thành báo cáo và slide cho Ban quản lý toà nhà.", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Còn việc gì giống vậy?", "u": "cap-4.html#con-viec-gi-giong-vay", "x": "💼 Công việc Ý tưởng sản phẩm → kế hoạch → email kêu gọi góp vốn → lịch triển khai. Biên bản họp → danh sách việc → email giao việc cho từng người. Kết quả khảo sát khách hàng → báo cáo → slide họp chiến lược. Hồ sơ mời thầu → bảng yêu cầu → thư hỏi làm rõ gửi bên mời thầu. Kết quả cả năm → bản tự đánh giá → slide trình bày với sếp. 🏡 Đời sống Chuyến du lịch gia đình: lịch trình → danh sách đồ mang → tin nhắn rủ cả nh", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Khi kết quả chưa như ý", "u": "cap-4.html#khi-ket-qua-chua-nhu-y", "x": "Bạn gặp Vì sao Nói với bạn ấy thế này Bạn ấy \"quên\" số liệu ở Bậc 3, hoặc đưa ra số khác Cuộc trò chuyện quá dài, phần đầu bị trôi khỏi trí nhớ \"Nhắc lại tổng và 5 nhóm chi phí trước khi viết tiếp. Không chắc thì nói, để mình dán lại.\" Báo cáo dài 2–3 trang Bạn ấy thích đầy đủ hơn gọn gàng \"Cắt còn đúng 1 trang. Mỗi phát hiện tối đa 2 câu.\" Có con số không thấy trong bảng Bạn ấy tự suy ra hoặc đoán \"Con số [X] lấy ở ", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Tự kiểm tra", "u": "cap-4.html#tu-kiem-tra", "x": "Mình làm cả bài trong một cuộc trò chuyện, không mở chat mới giữa chừng. Bạn ấy đã hỏi mình về sếp và cuộc họp trước khi viết. Báo cáo của mình gói trong 1 trang: 3 câu tóm tắt, 3 phát hiện có số, 2 đề xuất. Mình đã để \"sếp khó tính\" vặn 3 câu và sửa báo cáo để trả lời trước. Mình có bộ slide 6 trang (hoặc dàn ý) và biết cách mang đi họp. Mình đã đối chiếu tổng 384.070.000đ trên cả báo cáo lẫn slide.", "k": "lesson"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Đi xa hơn", "u": "cap-4.html#di-xa-hon", "x": "Một nguồn, nhiều phiên bản: từ cùng báo cáo, nhờ thêm bản tin nhắn Zalo 3 dòng cho sếp và bản email cho cả phòng. Mỗi người đọc một kiểu, bạn ấy viết lại trong vài giây. Tập dượt trình bày: \"Viết lời thuyết minh cho từng slide, nói trong 5 phút.\" Sau đó bật chế độ giọng nói, trình bày thử và nhờ bạn ấy góp ý thẳng. Nối nhiều bậc thành một mạch: đọc tài liệu ( Bậc 2 ) → làm sạch số ( Bậc 3 ) → báo cáo, slide (bậc này)", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Bạn sẽ làm được gì", "u": "cap-5.html#ban-se-lam-duoc-gi", "x": "Hiểu Project và Gem là gì: một \"góc làm việc riêng\" nơi bạn ấy nhớ hướng dẫn và tài liệu của bạn. Để bạn ấy phỏng vấn bạn rồi tự viết phần hướng dẫn, không cần biết viết prompt. Dựng trợ lý \"Báo cáo tuần\" từ một file mẫu và 2 báo cáo cũ. Từ ghi chú viết vội, không dấu, có ngay báo cáo đúng mẫu, đúng giọng, có đánh dấu chỗ cần kiểm tra. Nghĩ ra trợ lý riêng cho công việc và cho gia đình bạn.", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Vì sao cách nhờ này hiệu quả", "u": "cap-5.html#vi-sao-cach-nho-nay-hieu-qua", "x": "Ở Bậc 4 , bạn ấy nhớ mọi thứ trong một cuộc trò chuyện. Nhưng tuần sau mở chat mới, bạn ấy lại là người bạn mới quen: không biết bạn là ai, mẫu báo cáo ra sao, sếp thích gì. Chẳng lẽ tuần nào cũng kể lại từ đầu? Với đồng nghiệp thật, mình dạy một lần là họ nhớ. Project (trên ChatGPT và Claude) và Gem (trên Gemini) cho bạn làm đúng điều đó: một góc làm việc riêng, ghi hướng dẫn một lần, tải lên tài liệu mẫu. Mọi cuộc ", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Chuẩn bị", "u": "cap-5.html#chuan-bi", "x": "Công cụ: một trong ba: ChatGPT (Projects), Claude (Projects), Gemini (Gems). Bộ file mẫu của phòng Kinh doanh, Chi nhánh Hà Nội, Công ty Sao Mai (hư cấu). Tải trọn bộ một lần: Tải trọn bộ bậc 5 (.zip) Hoặc tải từng file: Mẫu báo cáo tuần (.docx) Báo cáo tuần 38 (.docx) Báo cáo tuần 39 (.docx) Số liệu tuần 40 (.txt) File Là gì mau-bao-cao-tuan.docx Mẫu trống 5 mục: Tóm tắt tuần · Kết quả chính (bảng Doanh số, Số đơn, ", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Làm thật: từng bước", "u": "cap-5.html#lam-that-tung-buoc", "x": "", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Bước 1 · Tìm \"góc làm việc riêng\" trong công cụ của bạn", "u": "cap-5.html#buoc-1-tim-goc-lam-viec-rieng-trong-cong-cu-cua-ban", "x": "Trên ChatGPT và Claude, thường có mục Projects ở thanh bên trái. Trên Gemini, tìm mục Gems . Giao diện tiếng Việt có thể ghi tên khác. Không thấy? Hỏi thẳng: Bạn sẽ thấy Bạn ấy giải thích tính năng và các bước tạo. Có thể bạn ấy mô tả giao diện cũ hơn cái bạn đang thấy, vì công cụ cập nhật liên tục. Khi đó, chụp màn hình gửi bạn ấy: \"Mình đang thấy thế này, bấm vào đâu?\" .", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Bước 2 · Để bạn ấy phỏng vấn bạn", "u": "cap-5.html#buoc-2-de-ban-ay-phong-van-ban", "x": "Mở một cuộc trò chuyện thường (chưa cần vào Project). Nếu được, tải lên 3 file .docx để bạn ấy hiểu bối cảnh. Rồi nói: Chưa biết trả lời gì? Đóng vai chị Hà Với bộ file mẫu, bạn đóng vai Trần Thu Hà , Trưởng nhóm Kinh doanh, Chi nhánh Hà Nội. Vài câu trả lời gợi ý: Báo cáo gửi Giám đốc Chi nhánh mỗi sáng thứ Hai, theo đúng 5 mục trong file mẫu. Số tiền ghi bằng triệu đồng, bảng kết quả luôn có cột % kế hoạch. Văn pho", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Bước 3 · Tạo Project, dán hướng dẫn, tải 3 file mẫu", "u": "cap-5.html#buoc-3-tao-project-dan-huong-dan-tai-3-file-mau", "x": "Tạo một Project (hoặc Gem) mới, đặt tên Trợ lý báo cáo tuần . Tìm ô hướng dẫn (thường ghi là Instructions, hoặc \"Hướng dẫn\") và dán đoạn bạn ấy vừa viết. Tải lên đúng 3 file: mau-bao-cao-tuan.docx , bao-cao-tuan-38.docx , bao-cao-tuan-39.docx . Không tải file số liệu tuần 40, vì số liệu là thứ bạn đưa mỗi tuần. Lưu lại. Mở một cuộc trò chuyện mới bên trong Project và kiểm tra xem bạn ấy đã \"học bài\" chưa: Bạn sẽ thấy", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Bước 4 · Từ giờ chỉ cần: \"Số liệu tuần 40:\"", "u": "cap-5.html#buoc-4-tu-gio-chi-can-so-lieu-tuan-40", "x": "Mở cuộc trò chuyện mới trong Project. Không cần chào, không cần giải thích. Dán nguyên ghi chú vội của chị Hà: Những tuần sau, bạn chỉ cần gõ \"Số liệu tuần [số]:\" rồi dán ghi chú của tuần đó. Bạn sẽ thấy Một báo cáo tuần 40 (28/9 – 4/10/2026) đúng 5 mục của mẫu, giọng văn giống tuần 38 và 39, dù ghi chú gốc không dấu và lộn xộn: Kết quả chính: doanh số khoảng 1.290 triệu đồng, 44 đơn, 7 khách mới, thu nợ 1.020 triệu ", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Bước 5 · Dạy thêm khi chưa ưng ý", "u": "cap-5.html#buoc-5-day-them-khi-chua-ung-y", "x": "Trợ lý mới cũng như nhân viên mới, tuần đầu chưa hoàn hảo. Nếu chỉ muốn sửa lần này, cứ nói thẳng trong cuộc trò chuyện. Còn nếu muốn sửa mãi mãi , hãy đưa điều đó vào hướng dẫn. Điều bạn dặn trong một cuộc trò chuyện chưa chắc được nhớ sang cuộc sau; điều ghi trong hướng dẫn thì luôn được đọc. Bạn sẽ thấy Một bản hướng dẫn mới, đầy đủ, đã gài thêm điều bạn muốn. Dán đè lên bản cũ trong phần cài đặt của Project. Tuần", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Bước 6 · Nghĩ ra trợ lý của riêng bạn", "u": "cap-5.html#buoc-6-nghi-ra-tro-ly-cua-rieng-ban", "x": "Bạn đã thấy cách dạy một trợ lý. Giờ đến lượt việc của chính bạn. Lại hỏi thẳng: Bạn sẽ thấy Năm gợi ý sát với đời bạn, có cả công việc lẫn gia đình. Chọn một cái, quay lại Bước 2 và để bạn ấy phỏng vấn bạn. Ghi tên trợ lý đó lên thẻ 7 bậc của bạn: \"Mình sẽ dạy bạn ấy việc ___.\"", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Dám hỏi lại", "u": "cap-5.html#dam-hoi-lai", "x": "Trợ lý giỏi đến đâu thì báo cáo vẫn mang tên bạn. Trước khi gửi, soát từng chỗ [CẦN KIỂM TRA] và hỏi nguồn của các con số: Dám hỏi lại Doanh số phải là khoảng 1.290 triệu đồng và chưa gồm đơn Hoa Sen 85 triệu. Nếu thấy 1.375 triệu, bạn ấy đã cộng nhầm đơn chưa xuất hoá đơn. Phúc Lộc còn nợ 80 triệu (đã trả thêm 40 triệu), quá hạn 40 ngày. Không phải 120 triệu như tuần 39. Số kế hoạch tuần 40 không có trong ghi chú. N", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Biến thể theo ngành", "u": "cap-5.html#bien-the-theo-nganh", "x": "", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "⚖️ Pháp lý", "u": "cap-5.html#phap-ly", "x": "Trợ lý pháp chế biết mẫu hợp đồng và checklist rà soát của công ty. Mỗi lần chỉ cần tải hợp đồng mới lên và nói \"rà giúp mình\".", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "💰 Kế toán – Tài chính", "u": "cap-5.html#ke-toan-tai-chinh", "x": "Trợ lý báo cáo tháng biết mẫu báo cáo quản trị, cách gọi tên khoản mục, ngưỡng chênh lệch nào phải giải trình.", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "🤝 Kinh doanh – CSKH", "u": "cap-5.html#kinh-doanh-cskh", "x": "Trợ lý chăm sóc khách hàng trả lời đúng giọng công ty, thuộc chính sách đổi trả và bảo hành.", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "🏗️ Vận hành – Xây dựng", "u": "cap-5.html#van-hanh-xay-dung", "x": "Trợ lý biến ghi chú hiện trường, ảnh chụp bảng trắng thành báo cáo ngày hoặc biên bản đúng mẫu.", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Còn việc gì giống vậy?", "u": "cap-5.html#con-viec-gi-giong-vay", "x": "💼 Công việc Trợ lý pháp chế biết mẫu hợp đồng và checklist của công ty. Trợ lý báo cáo tháng, thuộc mẫu và các ngưỡng phải giải trình. Trợ lý chăm sóc khách hàng trả lời đúng giọng công ty. \"Bản sao của tôi\" : tải lên quy trình và câu hỏi thường gặp, để cả team hỏi khi bạn vắng. Trợ lý soạn biên bản họp theo mẫu của phòng. 🏡 Đời sống Gia sư tiếng Anh cho con, biết trình độ, sở thích và lỗi con hay mắc. Trợ lý nấu ăn ", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Khi kết quả chưa như ý", "u": "cap-5.html#khi-ket-qua-chua-nhu-y", "x": "Bạn gặp Vì sao Nói với bạn ấy thế này Báo cáo không theo mẫu Bạn đang chat ngoài Project, hoặc file chưa tải lên xong Kiểm tra cuộc trò chuyện nằm trong Project, rồi: \"Mở file mau-bao-cao-tuan trong phần tệp và viết lại đúng 5 mục của nó.\" Tự điền số kế hoạch mà không đánh dấu Hướng dẫn chưa nói rõ \"Mình chưa đưa kế hoạch tuần này. Đánh dấu [CẦN KIỂM TRA] cạnh mọi số không có trong ghi chú.\" Rồi đưa câu này vào hướng", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Tự kiểm tra", "u": "cap-5.html#tu-kiem-tra", "x": "Mình đã để bạn ấy phỏng vấn mình và tự viết phần hướng dẫn. Mình đã tạo Project hoặc Gem (hoặc lưu hướng dẫn vào ghi chú nếu bản của mình chưa có). Mình đã tải lên mẫu và 2 báo cáo cũ, rồi kiểm tra xem bạn ấy đã \"học bài\" chưa. Chỉ với \"Số liệu tuần 40:\" và ghi chú vội, mình có báo cáo đúng mẫu, đúng giọng. Mình đã soát từng chỗ [CẦN KIỂM TRA] và hỏi nguồn các con số. Mình đã ghi ra ít nhất một trợ lý sẽ tạo cho công", "k": "lesson"}, {"t": "Trợ lý biết nhớ việc", "h": "Đi xa hơn", "u": "cap-5.html#di-xa-hon", "x": "Mỗi trợ lý một việc: đừng nhồi mọi thứ vào một Project. Việc càng rõ, bạn ấy làm càng chuẩn. Thay \"sách giáo khoa\" định kỳ: mỗi tháng thay 2 báo cáo cũ bằng 2 báo cáo mới nhất mà sếp ưng. \"Bản sao của tôi\" cho cả team: một số gói cho phép chia sẻ Project, Gem, hoặc tạo Custom GPT cho người khác dùng. Kiểm tra trang chính thức vì gói và quyền chia sẻ thay đổi thường xuyên. Đừng tải lên tài liệu mà người được chia sẻ k", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Bạn sẽ làm được gì", "u": "cap-6.html#ban-se-lam-duoc-gi", "x": "Biến một nhu cầu như \"nhóm mình hay quên hạn\" thành một ứng dụng nhỏ chạy ngay trên trình duyệt, không viết dòng code nào. Sửa lỗi, thêm tính năng, đổi giao diện chỉ bằng cách nói chuyện tiếp. Lưu app thành file hoặc link, mở được trên điện thoại. Kiểm tra app có tính đúng không, thay vì chỉ nhìn thấy đẹp. Dám thử ý tưởng táo bạo nhất của mình: một công cụ, một trò chơi, cho công việc hay cho con.", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Vì sao cách nhờ này hiệu quả", "u": "cap-6.html#vi-sao-cach-nho-nay-hieu-qua", "x": "Ai đi làm cũng từng nghĩ: \"Giá mà có một công cụ nhỏ làm đúng việc này.\" Trước đây, ý nghĩ đó thường dừng lại ở đó, vì phải nhờ phòng IT, chờ ngân sách, hoặc tự mày mò Excel đến khuya. Giờ người bạn AI viết được code. Bạn không cần biết code, chỉ cần kể vấn đề như kể cho một người bạn làm IT. Claude (với Artifacts) và ChatGPT (với Canvas) có thể hiện ứng dụng ngay cạnh cuộc trò chuyện để bạn bấm thử. Bí quyết vẫn là ", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Chuẩn bị", "u": "cap-6.html#chuan-bi", "x": "Công cụ: Claude (Artifacts) hoặc ChatGPT (Canvas). Bản miễn phí làm được, nhưng có giới hạn lượt dùng; kiểm tra trang chính thức vì gói và giới hạn thay đổi thường xuyên. Máy tính thao tác dễ hơn điện thoại. App làm xong vẫn mở được trên điện thoại. Một vấn đề thật của nhóm bạn mà chưa có công cụ phù hợp. Không có cũng được, bài có sẵn ví dụ. Kết quả mẫu để so sánh. Đây là app theo dõi tiến độ mà bài này hướng tới, m", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Làm thật: từng bước", "u": "cap-6.html#lam-that-tung-buoc", "x": "", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Bước 1 · Kể vấn đề, để bạn ấy hỏi lại", "u": "cap-6.html#buoc-1-ke-van-de-de-ban-ay-hoi-lai", "x": "Đừng cố mô tả một phần mềm. Cứ kể vấn đề, như than với đồng nghiệp: Bạn sẽ thấy Bạn ấy hỏi lại 3–6 câu: nhóm mấy người, mỗi việc cần ghi thông tin gì, cảnh báo bằng màu hay bằng thông báo, có cần lọc, xuất file không, dùng trên máy tính hay điện thoại. Có lúc bạn ấy hăng hái làm luôn một bản mà chưa hỏi. Cũng không sao, sang Bước 2 bạn bổ sung sau. Chưa biết trả lời gì? Dùng các ý này Nhóm 5 người, đang triển khai ph", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Bước 2 · Trả lời, rồi để bạn ấy làm luôn", "u": "cap-6.html#buoc-2-tra-loi-roi-de-ban-ay-lam-luon", "x": "Trả lời từng câu như nhắn tin. Muốn nhanh thì gộp một lần: Bạn sẽ thấy Sau vài chục giây, app hiện ra. Trên Claude, app nằm ở khung bên cạnh (Artifact). Trên ChatGPT, app nằm trong Canvas; nếu chỉ thấy code, tìm nút xem trước. Thường có: vài ô thống kê (tổng việc, đã xong, sắp đến hạn, quá hạn), thanh tiến độ, bảng việc tô màu, ô lọc, nút xuất CSV. So với app mẫu : app của bạn sẽ không giống hệt, và không cần giống. ", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Bước 3 · Dùng thử như người dùng thật", "u": "cap-6.html#buoc-3-dung-thu-nhu-nguoi-dung-that", "x": "Đừng chỉ nhìn, hãy bấm. Đổi hạn chót một việc xuống còn 3 ngày nữa: dòng đó phải chuyển cam. Đổi trạng thái thành \"Xong\": dòng chuyển xanh, % tiến độ tăng. Thêm một việc, lọc theo một người, bấm xuất CSV rồi mở bằng Excel. Không biết thử gì? Hỏi thẳng: Bạn sẽ thấy Một danh sách thử nghiệm ngắn, rõ ràng như hướng dẫn cho người mới. Làm lần lượt. Chỗ nào không giống mô tả, ghi lại: đó là \"đơn đặt hàng\" cho Bước 4.", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Bước 4 · Nói tiếp để sửa và nâng cấp", "u": "cap-6.html#buoc-4-noi-tiep-de-sua-va-nang-cap", "x": "Đây là lúc cuộc trò chuyện trở nên thú vị. Muốn thêm gì, sửa gì, cứ nói như nói với người ngồi cạnh. Ba kiểu câu bạn sẽ dùng nhiều nhất: Khi báo lỗi, kể đủ 3 ý: bấm gì, mong thấy gì, thực tế thấy gì . Gửi kèm ảnh chụp màn hình càng tốt. Bạn ấy không nhìn thấy màn hình của bạn, nên càng tả rõ, sửa càng trúng. Bạn sẽ thấy Mỗi câu bạn nói, app có một phiên bản mới. Thường sửa 1–2 vòng là xong một lỗi. Nếu bản mới tệ hơn", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Bước 5 · Lưu, chia sẻ, mở trên điện thoại", "u": "cap-6.html#buoc-5-luu-chia-se-mo-tren-dien-thoai", "x": "Trên Claude: Artifact có thể chia sẻ thành link. Tìm nút chia sẻ hoặc Publish (tên nút có thể khác tuỳ phiên bản). Ai có link là mở được. Trên ChatGPT: tìm nút chia sẻ trong Canvas hoặc trong cuộc trò chuyện. Tính năng thay đổi theo thời gian, kiểm tra trên giao diện của bạn. Cách chắc chắn nhất, dùng được với mọi công cụ: nhờ bạn ấy gộp thành một file HTML, lưu về máy, mở bằng trình duyệt. Gửi file qua Zalo hay emai", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Bước 6 · Thử thách táo bạo", "u": "cap-6.html#buoc-6-thu-thach-tao-bao", "x": "Giờ quên ví dụ đi. Nghĩ về công cụ hoặc trò chơi táo bạo nhất bạn từng muốn có. Càng \"điên\" càng tốt: một trò chơi ôn bảng cửu chương với nhân vật khủng long con bạn mê, một trò đố vui về quy chế công ty cho nhân viên mới, một bảng tính lãi vay mua nhà so sánh 3 ngân hàng, một vòng quay chọn món ăn tối cho cả nhà. Bạn sẽ thấy Bản đầu tiên thường chạy được nhưng còn thô: luật chơi chưa chuẩn, màu chưa ưng, nút hơi nhỏ", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Dám hỏi lại", "u": "cap-6.html#dam-hoi-lai", "x": "App trông đẹp chưa chắc đã tính đúng. Với công cụ theo dõi hạn, sai một ngày là cảnh báo vô nghĩa. Hỏi bạn ấy giải thích bằng lời thường, rồi tự thử: Dám hỏi lại Thử 3 mốc: tạo một việc hạn hôm qua (phải đỏ), một việc hạn đúng 5 ngày nữa (phải cam), một việc hạn 6 ngày nữa (không tô cảnh báo). App mẫu tô cam cả việc có hạn đúng hôm nay. Thử lưu: thêm một việc, tải lại trang. Việc đó còn không? Tuỳ nơi chạy app, dữ li", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Biến thể theo ngành", "u": "cap-6.html#bien-the-theo-nganh", "x": "", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "⚖️ Pháp lý", "u": "cap-6.html#phap-ly", "x": "Checklist rà soát hợp đồng dạng app: tick từng mục, ghi chú, chấm mức rủi ro, in ra một trang tóm tắt.", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "💰 Kế toán – Tài chính", "u": "cap-6.html#ke-toan-tai-chinh", "x": "Bảng tính khấu hao tài sản cố định có biểu đồ, tự ra lịch khấu hao từng tháng.", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "🤝 Kinh doanh – CSKH", "u": "cap-6.html#kinh-doanh-cskh", "x": "Công cụ lập báo giá tự tính chiết khấu và VAT, in ra gửi khách ngay.", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "🏗️ Vận hành – Xây dựng", "u": "cap-6.html#van-hanh-xay-dung", "x": "Sổ theo dõi bảo trì: ghi sự cố, thống kê hạng mục hỏng nhiều, nhắc lịch bảo dưỡng định kỳ.", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Còn việc gì giống vậy?", "u": "cap-6.html#con-viec-gi-giong-vay", "x": "💼 Công việc Bảng theo dõi hạn hồ sơ, tô màu hồ sơ sắp đến hạn. Công cụ xếp lịch trực, chia ca cho nhóm nhỏ. Máy tính hoa hồng bán hàng theo bậc doanh số. Trò đố vui về quy chế công ty cho nhân viên mới. Dashboard xem nhanh từ một bảng Excel (đã che dữ liệu nhạy cảm). 🏡 Đời sống Bảng chi tiêu gia đình có biểu đồ theo tháng. Lịch tập gym, đánh dấu buổi đã tập. Bảng tính lãi vay mua nhà, so sánh nhiều phương án. Trò chơ", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Khi kết quả chưa như ý", "u": "cap-6.html#khi-ket-qua-chua-nhu-y", "x": "Bạn gặp Vì sao Nói với bạn ấy thế này Chỉ thấy code, không thấy app Công cụ chưa mở chế độ xem trước \"Hiển thị app để mình bấm thử.\" Hoặc dùng câu 6g để gộp thành file HTML. Bấm nút không có phản ứng Code có lỗi \"Nút [tên nút] bấm không ăn. Mình bấm thì thấy [mô tả]. Sửa giúp.\" Gửi kèm ảnh chụp màn hình. Sửa chỗ này, hỏng chỗ khác Bản sửa đụng tới phần đang chạy tốt \"Bản trước nút [X] chạy được, bản này hỏng. Giữ ngu", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Tự kiểm tra", "u": "cap-6.html#tu-kiem-tra", "x": "Mình đã kể vấn đề và để bạn ấy hỏi lại trước khi làm. Mình có một app theo dõi tiến độ chạy được, có đủ màu đỏ, cam, xanh. Mình đã nói chuyện tiếp ít nhất 2 lần để sửa lỗi hoặc thêm tính năng. Mình đã thử quy tắc màu bằng 3 mốc: hôm qua, đúng 5 ngày, 6 ngày. Mình đã lưu app thành file hoặc link và mở được trên điện thoại. Mình đã thử (hoặc ít nhất ghi lại) ý tưởng táo bạo nhất của mình.", "k": "lesson"}, {"t": "Tự tạo công cụ không cần code", "h": "Đi xa hơn", "u": "cap-6.html#di-xa-hon", "x": "Nối với Bậc 5: lưu \"phong cách công ty\" (màu, font, logo, giọng chữ) vào một Project, để mọi app bạn làm đều cùng một bộ nhận diện. Hướng dẫn nằm sẵn trong app: \"Thêm một nút Hướng dẫn, giải thích cách dùng trong 5 dòng.\" Đồng nghiệp tự dùng, không cần hỏi bạn. App từ file thật: tải lên một bảng Excel đã che dữ liệu nhạy cảm và nói \"Làm cho mình một dashboard từ file này.\" Muốn cả nhóm cùng cập nhật một bảng chung? Đ", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Bạn sẽ làm được gì", "u": "cap-7.html#ban-se-lam-duoc-gi", "x": "Hiểu AI agent khác chat thường ở đâu, và khi nào nên dùng. Giao một đầu việc thật: gom số liệu tháng 9 của 5 chi nhánh, mỗi nơi gửi một kiểu, thành báo cáo quản trị tháng gửi Giám đốc. Đọc và duyệt kế hoạch của bạn ấy trước khi để bạn ấy làm. Kiểm tra thành phẩm bằng những câu \"dám hỏi lại\" nhắm đúng chỗ dễ sai. Chưa có gói trả phí vẫn làm gần giống bằng một cuộc trò chuyện thường.", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Vì sao cách nhờ này hiệu quả", "u": "cap-7.html#vi-sao-cach-nho-nay-hieu-qua", "x": "Ở 6 bậc trước, bạn vẫn là người chạy việc: copy, dán, tải từng file lên, tải kết quả về. Với AI agent , bạn chỉ cho bạn ấy một thư mục, giao việc, và bạn ấy tự mở file, tự đọc, làm từng bước, rồi lưu thành phẩm ngay trên máy bạn . Giống hệt giao việc cho một trợ lý thật: \"Số liệu các chi nhánh ở thư mục này, em gom lại thành báo cáo cho anh.\" Trong bài này, mình dùng Claude Cowork : AI agent trong ứng dụng Claude trê", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Chuẩn bị", "u": "cap-7.html#chuan-bi", "x": "Claude Cowork: cài ứng dụng Claude cho máy tính và đăng nhập tài khoản trả phí. Kiểm tra trang chính thức của Anthropic xem gói nào có Cowork, vì gói và tính năng thay đổi thường xuyên. Chưa có gói trả phí? Vẫn làm được phần lớn bài này bằng chat thường, xem Bước 6. Số liệu tháng 9 của 5 chi nhánh (hư cấu, Công ty Sao Mai): Tải số liệu 5 chi nhánh (.zip) File Chi nhánh gửi kiểu gì CN Ha Noi.xlsx Đúng mẫu, có thêm she", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Làm thật: từng bước", "u": "cap-7.html#lam-that-tung-buoc", "x": "", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Bước 1 · Dựng thư mục làm việc, cho bạn ấy làm quen", "u": "cap-7.html#buoc-1-dung-thu-muc-lam-viec-cho-ban-ay-lam-quen", "x": "Tạo một thư mục mới, ví dụ AI-lam-viec trong thư mục Documents. Giải nén file zip vào đó (chuột phải, chọn Extract All hoặc Giải nén tất cả). Bạn sẽ có thư mục con bao-cao-thang-9 với đúng 5 file. Kiểm tra không có file nào khác. Mở ứng dụng Claude, chuyển sang Cowork và chọn thư mục bao-cao-thang-9 làm nơi làm việc. Giao diện có thể thay đổi theo phiên bản; không thấy thì xem trang hướng dẫn chính thức. Trước khi gi", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Bước 2 · Giao việc, và để bạn ấy hỏi lại", "u": "cap-7.html#buoc-2-giao-viec-va-de-ban-ay-hoi-lai", "x": "Đây là bước \"Hỏi thẳng bạn ấy\" của bậc 7. Bạn giao việc như giao cho một trợ lý giỏi: nói rõ cần gì, lưu ở đâu, thế nào là tốt, và mời bạn ấy hỏi trước khi làm. Mỗi ý trong lời giao việc có lý do, và đủ cả ba điều Boris Cherny khuyên (xem Giao việc như giao cho đồng nghiệp ): muốn gì (ba thành phẩm, lưu ở đâu), công sức (\"cứ làm kỹ\"), kiểm tra thế nào (\"chỉ ra nguồn\", \"tự đối chiếu\", \"báo đã kiểm gì\"). Thư mục output", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Bước 3 · Đọc kế hoạch trước khi duyệt", "u": "cap-7.html#buoc-3-doc-ke-hoach-truoc-khi-duyet", "x": "Bạn ấy trình kế hoạch. Đọc kỹ như duyệt kế hoạch của một nhân viên mới. Năm điều cần thấy trong kế hoạch: Đủ 5 file, không bỏ sót chi nhánh nào. Hải Phòng sẽ được đổi từ triệu đồng sang đồng . File HCM: dùng sheet nào, vì sao. Cần Thơ: hiểu các mã tài khoản ra sao, kế hoạch doanh thu lấy ở đâu. Tên và nơi lưu 3 thành phẩm. Thiếu điều gì thì hỏi thêm trước khi duyệt: Bạn sẽ thấy Bạn ấy trả lời câu bạn hỏi, cập nhật kế", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Bước 4 · Để bạn ấy làm, và quan sát", "u": "cap-7.html#buoc-4-de-ban-ay-lam-va-quan-sat", "x": "Giờ bạn ấy tự chạy: mở từng file, đọc số liệu, tính toán, tạo file mới. Bạn sẽ thấy từng bước hiện lên. Tuỳ công cụ và cài đặt, bạn ấy có thể xin phép trước một số thao tác. Đọc kỹ rồi mới đồng ý, và từ chối bất cứ việc gì bạn không giao (như xoá file, gửi email). Muốn biết bạn ấy đang ở đâu, cứ hỏi: Bạn sẽ thấy Sau vài phút, thư mục output xuất hiện với 3 file, tên có thể như Tong-hop-thang-9.xlsx , Bao-cao-quan-tri", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Bước 5 · Mở thành phẩm và đọc như Giám đốc", "u": "cap-7.html#buoc-5-mo-thanh-pham-va-doc-nhu-giam-doc", "x": "Mở từng file. Đọc file Word như thể bạn là Giám đốc: có hiểu ngay tình hình không, có biết mình cần quyết định gì không? Rồi nhờ bạn ấy tự tóm tắt: Bạn sẽ thấy File Excel có 5 dòng chi nhánh, dòng tổng toàn công ty và sheet ghi nguồn. File Word có đủ 4 mục bạn yêu cầu. Email nằm yên trong thư mục. Phần bạn ấy tự nhận \"chưa chắc chắn\" là chỗ cần soi đầu tiên, rồi đối chiếu với đáp án ở mục Dám hỏi lại .", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Bước 6 · Chưa có gói trả phí? Một cuộc trò chuyện, từng file một", "u": "cap-7.html#buoc-6-chua-co-goi-tra-phi-mot-cuoc-tro-chuyen-tung-file-mot", "x": "Không có agent, bạn vẫn làm gần giống được, bằng đúng chiêu của Bậc 4 : giữ một cuộc trò chuyện và nói tiếp . Khác biệt duy nhất: bạn là người mang từng file tới cho bạn ấy. Mở một cuộc trò chuyện mới trên ChatGPT hoặc Claude. Giữ nguyên cuộc này đến cuối. Giao việc trước bằng câu 7f bên dưới. Tải lên từng file, mỗi tin nhắn một file. Chờ bạn ấy tóm tắt xong mới gửi file tiếp theo. Công cụ không nhận một loại file? M", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Dám hỏi lại", "u": "cap-7.html#dam-hoi-lai", "x": "Đây là bước quan trọng nhất của bậc 7. Bạn ấy làm nhanh, nhưng báo cáo gửi Giám đốc mang tên bạn. Đừng hỏi chung chung \"đúng chưa?\". Hãy hỏi đúng những chỗ dễ sai nhất, và đòi xem dòng gốc. Dám hỏi lại Hải Phòng: dòng 2 của file ghi \"ĐVT: triệu đồng\" . Doanh thu 3.020 phải thành 3.020.000.000đ. Mở file ra, tự nhìn dòng đó. HCM: phải dùng sheet BC T9 (doanh thu 7,82 tỷ), bỏ qua sheet nhap cũ (7,64 tỷ). HCM, chi phí bá", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Biến thể theo ngành", "u": "cap-7.html#bien-the-theo-nganh", "x": "", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "⚖️ Pháp lý", "u": "cap-7.html#phap-ly", "x": "Gom hàng chục hồ sơ vụ việc rời rạc thành một bảng theo dõi thời hạn, có trích nguồn từng mốc.", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "💰 Kế toán – Tài chính", "u": "cap-7.html#ke-toan-tai-chinh", "x": "Đối chiếu sao kê ngân hàng với sổ sách. Đây là dữ liệu nhạy cảm: che số tài khoản, hoặc chỉ dùng công cụ được công ty cho phép.", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "🤝 Kinh doanh – CSKH", "u": "cap-7.html#kinh-doanh-cskh", "x": "Gộp báo giá của nhiều nhà cung cấp, mỗi nơi một định dạng, thành một bảng so sánh.", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "🏗️ Vận hành – Xây dựng", "u": "cap-7.html#van-hanh-xay-dung", "x": "Gom báo cáo ngày của nhiều công trường thành báo cáo tuần cho Ban chỉ huy.", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Còn việc gì giống vậy?", "u": "cap-7.html#con-viec-gi-giong-vay", "x": "💼 Công việc Gom chứng từ cuối năm từ nhiều thư mục thành bảng kê. Gộp phiếu khảo sát khách hàng từ nhiều file thành báo cáo. Đổi tên và sắp xếp 200 file hợp đồng theo một quy tắc thống nhất. Rà một thư mục hồ sơ dự thầu, lập danh sách giấy tờ còn thiếu. Gom bảng chấm công của nhiều phòng thành bảng tổng hợp lương. 🏡 Đời sống Dọn thư mục 5.000 ảnh điện thoại theo năm và theo sự kiện. Gom hoá đơn điện, nước, internet c", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Khi kết quả chưa như ý", "u": "cap-7.html#khi-ket-qua-chua-nhu-y", "x": "Bạn gặp Vì sao Nói với bạn ấy thế này Tổng doanh thu chỉ khoảng 17,6 tỷ Bạn ấy cộng thẳng số triệu đồng của Hải Phòng \"File Hải Phòng ghi ĐVT: triệu đồng ở dòng 2. Đổi sang đồng, tính lại và cập nhật cả 3 file.\" Doanh thu HCM là 7,64 tỷ Đọc nhầm sheet nháp cũ \"Dùng sheet BC T9, bỏ qua sheet nhap. Tính lại và cập nhật cả 3 file.\" Chi phí bán hàng HCM lên tới 1.224 triệu Cộng 3 dòng chi tiết thêm một lần nữa \"612 triệu", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Tự kiểm tra", "u": "cap-7.html#tu-kiem-tra", "x": "Mình làm trên bản sao, trong thư mục làm việc riêng, không có file đáp án. Mình đã để bạn ấy hỏi lại và trình kế hoạch trước khi làm. Mình có 3 thành phẩm: Excel tổng hợp, Word báo cáo, email soạn sẵn chưa gửi. Mình đã hỏi lại cách quy đổi Hải Phòng và tự nhìn dòng gốc trong file. Tổng doanh thu (20.581.000.000đ) và lợi nhuận trước thuế (2.056.200.000đ) của mình khớp đáp án. Báo cáo của mình nêu đủ 4 điểm phải phát h", "k": "lesson"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Đi xa hơn", "u": "cap-7.html#di-xa-hon", "x": "Nhìn lại cả 7 bậc, bạn sẽ thấy một điều: agent chỉ giỏi khi người giao việc rõ ràng. Bạn càng luyện bậc 1 đến 6 (kể đủ bối cảnh, hỏi \"căn cứ đâu?\", nói tiếp, dạy bạn ấy, tự làm công cụ), quy trình làm việc của bạn càng rõ: báo cáo cần gì, dữ liệu nằm đâu, chỗ nào phải kiểm tra. Quy trình càng rõ, bạn càng giao được việc lớn. Biến thành quy trình hằng tháng: lưu lời giao việc 7b cùng các câu 7h, 7i thành một file hướn", "k": "lesson"}, {"t": "Bản đồ công cụ AI", "h": "Bản đồ công cụ AI", "u": "cong-cu.html", "x": "Bạn không cần dùng hết các công cụ trên trang này. Cũng như bạn bè ngoài đời, mỗi người bạn AI có một thế mạnh riêng: người giỏi viết, người giỏi tra cứu, người giỏi đọc tài liệu dài. Trang này giúp bạn biết ai giỏi gì để mở đúng người khi cần. Trước khi đọc Tính năng, gói dịch vụ và giới hạn của các công cụ AI thay đổi gần như hằng tháng. Trang này không ghi giá tiền hay số lượt dùng . Muốn biết chính xác, hãy mở tr", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Nhìn nhanh", "u": "cong-cu.html#nhin-nhanh", "x": "Công cụ Của ai Nổi bật cho dân văn phòng Bản miễn phí ChatGPT OpenAI Đa năng, giọng nói tự nhiên, phân tích số liệu Có Claude Anthropic Đọc tài liệu dài, viết tự nhiên, tạo công cụ nhỏ (Artifact) Có Gemini Google Gắn với Gmail, Google Docs, Drive Có NotebookLM Google Hỏi đáp trên đúng tài liệu của bạn, có trích dẫn Có Microsoft Copilot Microsoft Gắn với Word, Excel, Outlook, Teams (bản cho công ty) Có, với bản cá nhâ", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Sáu người bạn để trò chuyện", "u": "cong-cu.html#sau-nguoi-ban-de-tro-chuyen", "x": "", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "ChatGPT", "u": "cong-cu.html#chatgpt", "x": "Là gì: trợ lý AI của OpenAI, dùng tại chatgpt.com hoặc qua app điện thoại, máy tính. Đây là công cụ gần như ai trong nhóm mình cũng đã dùng. Giỏi cho việc văn phòng: Viết, sửa email và văn bản, đổi giọng văn từ trang trọng sang thân thiện Đọc file Excel bạn tải lên, tính toán, vẽ biểu đồ Chế độ giọng nói rất tự nhiên, hợp để suy nghĩ thành lời hoặc tập thuyết trình Canvas: cùng sửa một văn bản hay một trang web ngay ", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Claude", "u": "cong-cu.html#claude", "x": "Là gì: trợ lý AI của Anthropic, dùng tại claude.ai , app điện thoại hoặc app máy tính. Giỏi cho việc văn phòng: Đọc tài liệu dài như hợp đồng, quy chế, hồ sơ thầu; tìm điểm bất lợi, điểm mơ hồ Viết tiếng Việt tự nhiên, ít sáo rỗng, giữ được giọng văn khi bạn đưa mẫu Artifacts: tạo trang web, công cụ nhỏ, slide, trò chơi chạy được ngay bên cạnh khung chat (xem Bậc 6 ) Projects: góc làm việc riêng nhớ hướng dẫn và tài ", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Gemini", "u": "cong-cu.html#gemini", "x": "Là gì: trợ lý AI của Google, dùng tại gemini.google.com hoặc app điện thoại, đăng nhập bằng tài khoản Google. Giỏi cho việc văn phòng: Làm việc cùng Gmail, Google Docs, Sheets, Drive (tuỳ loại tài khoản và gói) Gems: trợ lý riêng nhớ hướng dẫn của bạn, tương tự Project Deep Research: nghiên cứu một chủ đề từ nhiều nguồn trên mạng, ra báo cáo dài Trò chuyện bằng giọng nói trên điện thoại Xem hình ảnh, đọc ảnh chụp tài", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "NotebookLM", "u": "cong-cu.html#notebooklm", "x": "Là gì: \"sổ tay nghiên cứu\" của Google, dùng tại notebooklm.google.com . Bạn đưa vào các nguồn (PDF, Google Docs, trang web, video YouTube, văn bản dán vào), bạn ấy trả lời dựa trên đúng các nguồn đó , kèm trích dẫn bấm vào là nhảy tới đoạn gốc. Giỏi cho việc văn phòng: Hỏi đáp trên tài liệu dài hoặc nhiều tài liệu cùng lúc Kiểm chứng: thấy ngay câu trả lời lấy từ đâu Tạo bản tóm tắt dạng âm thanh như một chương trình", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Microsoft Copilot", "u": "cong-cu.html#microsoft-copilot", "x": "Là gì: trợ lý AI của Microsoft. Có hai \"phiên bản\" rất dễ nhầm: Copilot cho cá nhân , tại copilot.microsoft.com hoặc app, có bản miễn phí. Copilot trong Microsoft 365 cho công ty , nằm ngay trong Word, Excel, PowerPoint, Outlook, Teams. Thường do công ty mua và cấp quyền. Giỏi cho việc văn phòng: nếu công ty đã cấp, bạn nhờ ngay trong Outlook (tóm tắt chuỗi email dài), Teams (tóm tắt cuộc họp), Word, Excel mà không p", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Perplexity", "u": "cong-cu.html#perplexity", "x": "Là gì: \"công cụ tìm kiếm biết trả lời\", dùng tại perplexity.ai . Bạn ấy tìm trên mạng rồi tổng hợp thành câu trả lời, kèm link nguồn đánh số. Giỏi cho việc văn phòng: tra cứu thông tin mới, tìm hiểu thị trường, đối thủ, tin tức ngành, và kiểm tra chéo câu trả lời của AI khác. Chọn khi: bạn cần thông tin cập nhật và muốn bấm vào nguồn để tự đọc. Nhớ: có link không có nghĩa là đúng, hãy bấm vào đọc đoạn gốc. Miễn phí h", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Bốn \"agent\": giao cả đầu việc", "u": "cong-cu.html#bon-agent-giao-ca-dau-viec", "x": "Với AI thường, bạn hỏi một câu, bạn ấy trả lời một câu. Với agent , bạn giao một đầu việc, bạn ấy tự lên kế hoạch, tự mở file hoặc trang web, làm nhiều bước liền, rồi báo lại kết quả. Bạn vẫn là người duyệt kế hoạch và kiểm tra thành phẩm. Xem thêm Bậc 7 .", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Claude Cowork", "u": "cong-cu.html#claude-cowork", "x": "AI agent trong ứng dụng Claude trên máy tính , làm việc trực tiếp với file và thư mục trên máy bạn: đọc nhiều file Excel, Word cùng lúc, tổng hợp, tạo file mới. Ví dụ ở Bậc 7: gom báo cáo tháng của 5 chi nhánh, mỗi nơi một kiểu, thành một bộ báo cáo cho Giám đốc. Chọn khi: bạn có việc lặp lại trên nhiều file trong máy. Cần gói trả phí và cài app desktop. Chỉ cho bạn ấy truy cập đúng thư mục cần dùng.", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "ChatGPT Agent", "u": "cong-cu.html#chatgpt-agent", "x": "Chế độ để ChatGPT tự thao tác nhiều bước , ví dụ tự mở trang web, tìm và so sánh thông tin, tạo file, rồi báo lại. Bạn có thể theo dõi và dừng bất cứ lúc nào. Chọn khi: việc nhiều bước trên web như so sánh nhà cung cấp, gom thông tin từ nhiều trang. Thường cần gói trả phí. Kiểm tra trang chính thức.", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Claude Code", "u": "cong-cu.html#claude-code", "x": "Công cụ agent của Anthropic, chạy trong Terminal, ứng dụng desktop hoặc IDE (phần mềm viết code). Ban đầu dành cho lập trình viên, nhưng dân văn phòng cũng dùng để tự động hoá: gộp hàng trăm file Excel, đổi tên file hàng loạt, tạo công cụ chạy trên máy. Chọn khi: bạn thoải mái với máy tính và được phép cài phần mềm. Cần gói trả phí. Đây là phần hoàn toàn tự chọn, bạn không cần nó để đi hết 7 bậc.", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Codex", "u": "cong-cu.html#codex", "x": "Agent lập trình của OpenAI: viết, sửa, kiểm tra code theo yêu cầu bằng lời. Với dân văn phòng, chỉ cần biết tên để khỏi bỡ ngỡ khi nghe ai nhắc. Thường gắn với gói trả phí của ChatGPT. Kiểm tra trang chính thức.", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Việc của bạn → nên mở công cụ nào", "u": "cong-cu.html#viec-cua-ban-nen-mo-cong-cu-nao", "x": "Việc của bạn Nên mở Ghi chú Viết, sửa email, văn bản ChatGPT hoặc Claude Xem Bậc 1 Rà soát hợp đồng, quy chế dài Claude, kiểm lại bằng NotebookLM Xem Bậc 2 Hỏi đáp trên đúng bộ tài liệu, cần trích dẫn NotebookLM Bấm trích dẫn để đối chiếu Dọn file Excel, viết công thức ChatGPT hoặc Claude Xem Bậc 3 Từ số liệu ra báo cáo và slide Claude hoặc ChatGPT Xem Bậc 4 Tra thông tin mới, cần link nguồn Perplexity, hoặc chế độ t", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Các tính năng hay gặp, giải thích dễ hiểu", "u": "cong-cu.html#cac-tinh-nang-hay-gap-giai-thich-de-hieu", "x": "", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Upload file", "u": "cong-cu.html#upload-file", "x": "Bấm biểu tượng ghim giấy hoặc dấu cộng cạnh khung chat để đưa file vào: PDF, Word, Excel, ảnh. Bạn ấy đọc file rồi nói chuyện với bạn về nội dung đó. Bản miễn phí thường giới hạn số file hoặc dung lượng. Nếu bị chặn, copy một phần nội dung rồi dán thẳng vào khung chat.", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Projects và Gems", "u": "cong-cu.html#projects-va-gems", "x": "Một \"góc làm việc riêng\" nơi bạn để sẵn hướng dẫn và tài liệu. Mỗi cuộc trò chuyện mở trong góc đó, bạn ấy đã biết bạn là ai, làm việc thế nào, theo mẫu nào. ChatGPT và Claude gọi là Project , Gemini gọi là Gem . Đây là chìa khoá của Bậc 5 .", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Custom GPT", "u": "cong-cu.html#custom-gpt", "x": "Một phiên bản ChatGPT do bạn \"cài đặt\" sẵn hướng dẫn và tài liệu, đặt tên riêng, và có thể chia sẻ cho đồng nghiệp dùng chung. Ví dụ: \"Trợ lý soạn công văn phòng Pháp chế\". Việc tạo hay chia sẻ có thể tuỳ gói, kiểm tra trang chính thức.", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Artifacts và Canvas", "u": "cong-cu.html#artifacts-va-canvas", "x": "Một khung riêng bên cạnh cuộc trò chuyện, nơi kết quả hiện ra như một văn bản, một trang web hay một ứng dụng chạy được. Bạn nói tiếp để sửa, khung đó cập nhật theo. Claude gọi là Artifact , ChatGPT gọi là Canvas (Gemini cũng có tính năng tên Canvas).", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Deep Research", "u": "cong-cu.html#deep-research", "x": "Chế độ \"nghiên cứu sâu\": bạn đưa đề bài, bạn ấy tự tìm và đọc nhiều nguồn trên mạng trong vài phút, rồi viết báo cáo dài có trích nguồn. Hợp với tìm hiểu thị trường, tổng quan quy định, so sánh giải pháp. Vẫn phải bấm vào nguồn kiểm tra những ý quan trọng. Thường bị giới hạn lượt dùng, nhất là ở bản miễn phí.", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Chế độ giọng nói", "u": "cong-cu.html#che-do-giong-noi", "x": "Nói chuyện với AI như gọi điện: bạn nói, bạn ấy trả lời bằng giọng nói, bạn có thể ngắt lời. Tìm biểu tượng sóng âm hoặc micro trong app điện thoại. Rất hợp để động não, luyện tiếng Anh, tập trả lời phỏng vấn.", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Kết nối ứng dụng (Gmail, Drive, lịch…)", "u": "cong-cu.html#ket-noi-ung-dung-gmail-drive-lich", "x": "Cho phép AI đọc trực tiếp email, tài liệu, lịch của bạn để trả lời, ví dụ \"tóm tắt các email chưa đọc từ khách hàng tuần này\". Tiện, nhưng là cánh cửa vào dữ liệu thật. Chỉ bật khi công ty cho phép, và chỉ cấp quyền cho đúng thứ cần dùng. Xem Dùng AI an toàn .", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Chọn bạn như chọn bạn", "u": "cong-cu.html#chon-ban-nhu-chon-ban", "x": "Đừng cố dùng hết. Lời khuyên của mình: chơi thân với 2 bạn . Một bạn trò chuyện chính : ChatGPT hoặc Claude. Bạn này đi cùng bạn mỗi ngày. Một bạn chuyên trách : NotebookLM nếu bạn đọc nhiều tài liệu, Perplexity nếu bạn tra cứu nhiều, Gemini nếu bạn sống trong Gmail và Drive. Thỉnh thoảng đưa cùng một việc cho cả hai bạn, so sánh kết quả. Bạn sẽ nhanh chóng cảm được ai hợp với việc gì. Góc nhìn Công cụ nào cũng giỏi ", "k": "page"}, {"t": "Bản đồ công cụ AI", "h": "Tự kiểm tra", "u": "cong-cu.html#tu-kiem-tra", "x": "Mình đã có tài khoản ở ít nhất 2 công cụ trong bảng \"Nhìn nhanh\" Mình đã đưa cùng một việc cho 2 công cụ và so sánh kết quả Mình biết khi nào nên mở NotebookLM thay vì chat thường Mình biết công ty mình có cấp Copilot hoặc tài khoản AI doanh nghiệp hay không Mình giải thích được agent khác chat thường ở điểm nào", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Giao việc như giao cho đồng nghiệp", "u": "giao-viec-nhu-dong-nghiep.html", "x": "Ngày 6/10/2026, Boris Cherny, người tạo ra Claude Code ở Anthropic, đăng một dòng trên X khiến nhiều người bất ngờ: anh nhờ AI bằng những câu nghe như nhắn tin cho đồng nghiệp. Không công thức, không mẫu dài, không \"kỹ thuật viết prompt\". Với khoá này, đó không phải điều mới. Ngay từ buổi đầu, tinh thần của mình đã là mọi thứ là giao tiếp, như người với người . Trang này biến ý của Boris thành một thói quen dùng được", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Chuyện gì đã xảy ra", "u": "giao-viec-nhu-dong-nghiep.html#chuyen-gi-da-xay-ra", "x": "Nguyên văn câu mở đầu của Boris (tiếng Anh): \"Talk to Claude the way you would a coworker. There's no secret to prompting.\" Dịch: Hãy nói chuyện với Claude như nói với một đồng nghiệp. Prompt chẳng có bí mật gì cả. Anh viết tiếp, theo các báo công nghệ đưa tin: với phần lớn công việc, không cần rào trước đón sau hay chỉ dẫn từng bước. Hãy giao mục tiêu, mô hình sẽ tự tìm cách. Thời các mô hình còn yếu (anh nhắc tới t", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Ba điều cần nói rõ", "u": "giao-viec-nhu-dong-nghiep.html#ba-dieu-can-noi-ro", "x": "", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "1. Muốn gì", "u": "giao-viec-nhu-dong-nghiep.html#1-muon-gi", "x": "Không chỉ là tên việc (\"viết email\"), mà là mục tiêu : dùng vào đâu, gửi cho ai, thế nào là tốt. Một đồng nghiệp mới cần biết những điều này, AI cũng vậy. Chưa đủ: \"Viết email trả lời khách.\" Đủ: \"Mình cần trả lời chị Lan, khách quen 3 năm, đang bực vì đơn hàng giao chậm 5 ngày. Mình muốn giữ khách. Viết ngắn, thật lòng, có mốc giao mới.\"", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "2. Bỏ bao nhiêu công sức", "u": "giao-viec-nhu-dong-nghiep.html#2-bo-bao-nhieu-cong-suc", "x": "Bạn ấy không tự biết việc này là việc vặt hay việc quan trọng. Hãy nói thẳng: Bạn muốn Nói thế này Nhanh, đủ dùng \"Làm nhanh gọn thôi, không cần hoàn hảo.\" Cẩn thận \"Việc này quan trọng, cứ làm kỹ, không cần vội.\" Rất kỹ \"Dành nhiều thời gian suy nghĩ. Thử vài hướng rồi chọn hướng tốt nhất, nói mình vì sao.\" Có lựa chọn \"Làm 3 phương án khác nhau, mỗi phương án ghi hợp với tình huống nào.\" Một số công cụ có thêm nút ", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "3. Kiểm tra thế nào", "u": "giao-viec-nhu-dong-nghiep.html#3-kiem-tra-the-nao", "x": "Đây chính là vế dám hỏi lại , nhưng dặn từ trước để bạn ấy tự kiểm. Câu dặn càng cụ thể càng tốt: \"Xong thì đối chiếu tổng với từng file gốc.\" \"Đánh dấu những chỗ bạn tự thêm mà mình chưa nói.\" \"Mỗi ý trích nguyên văn kèm số Điều. Không có trong tài liệu thì nói rõ là không có.\" \"Tính lại bằng một cách khác, hai cách phải ra cùng một số.\" \"Chạy thử với 3 trường hợp: hạn hôm nay, hạn ngày mai, hạn tuần sau.\" Và câu ch", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Mẫu câu giao việc", "u": "giao-viec-nhu-dong-nghiep.html#mau-cau-giao-viec", "x": "Dòng cuối là chiêu quen thuộc của khoá: Hỏi thẳng bạn ấy . Bạn không cần kể hoàn hảo, bạn ấy sẽ hỏi phần còn thiếu. Có sẵn một câu nhờ cũ và muốn nâng cấp nó? Nhờ luôn:", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Trước và sau", "u": "giao-viec-nhu-dong-nghiep.html#truoc-va-sau", "x": "Kiểu cũ Kiểu đồng nghiệp \"Tóm tắt hợp đồng này.\" \"Mình là bên mua, sắp ký hợp đồng này. Cần biết ai làm gì, hạn khi nào, chỗ nào bất lợi cho mình. Cứ đọc kỹ. Mỗi ý trích nguyên văn kèm số Điều.\" \"Làm sạch file Excel.\" \"File chi phí tháng 9, mình cần tổng theo nhóm để báo sếp thứ Hai. Bạn tự xem nên dọn gì. Xong cho mình biết đã bỏ bao nhiêu dòng trùng và giải thích 3 dòng bất kỳ.\" \"Viết báo cáo tuần.\" \"Đây là ghi chú", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Khi nào vẫn cần nói nhiều hơn", "u": "giao-viec-nhu-dong-nghiep.html#khi-nao-van-can-noi-nhieu-hon", "x": "Boris nói \"với phần lớn công việc\". Một lưu ý trung thực: ngắn không có nghĩa là thiếu . Việc lớn, lạ, nhiều ràng buộc: vẫn cần bối cảnh, ví dụ mẫu, những điều tuyệt đối không được sai. Định dạng bắt buộc: văn bản theo thể thức, biểu mẫu của cơ quan, mẫu báo cáo công ty. Đưa mẫu cho bạn ấy xem. Việc nhạy cảm: pháp lý, tài chính, sức khoẻ. Dặn kỹ phần kiểm tra, và người quyết định cuối cùng vẫn là bạn. Khi không chắc ", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Một ví dụ thật: câu giao việc đã tạo ra phiên bản này", "u": "giao-viec-nhu-dong-nghiep.html#mot-vi-du-that-cau-giao-viec-da-tao-ra-phien-ban-nay", "x": "Phiên bản 2 của website và bài trình chiếu này được làm bằng cách trò chuyện với Claude Code. Đây là những câu chính trong câu giao việc của người chia sẻ, trích nguyên văn: Điều Câu giao việc Muốn gì \"Update để lớp học tốt hơn, hay hơn, presentation smooth và trông wow hơn… đặc biệt có thể tự thân dùng làm material để tự học.\" Công sức \"Dùng nhiều token và lặp lại cho đến khi bạn tự hào về nó. Thấy gì làm nó hay hơn", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Biến thể theo ngành", "u": "giao-viec-nhu-dong-nghiep.html#bien-the-theo-nganh", "x": "", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "⚖️ Pháp lý", "u": "giao-viec-nhu-dong-nghiep.html#phap-ly", "x": "Với văn bản pháp lý, phần \"kiểm tra\" nên đòi trích nguyên văn và phân biệt rõ điều có trong văn bản với điều suy luận.", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "💰 Kế toán – Tài chính", "u": "giao-viec-nhu-dong-nghiep.html#ke-toan-tai-chinh", "x": "Với số liệu, phần \"kiểm tra\" nên là một phép đối chiếu cụ thể.", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "🤝 Kinh doanh – CSKH", "u": "giao-viec-nhu-dong-nghiep.html#kinh-doanh-cskh", "x": "Với khách hàng, phần \"muốn gì\" nên nói rõ mối quan hệ và điều không được hứa.", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "🏗️ Vận hành – Xây dựng", "u": "giao-viec-nhu-dong-nghiep.html#van-hanh-xay-dung", "x": "Với kế hoạch, phần \"kiểm tra\" nên là soát lại ràng buộc thực tế.", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Tự kiểm tra", "u": "giao-viec-nhu-dong-nghiep.html#tu-kiem-tra", "x": "Nói được ba điều cần nói rõ khi giao việc cho AI. Đã dùng mẫu DN1 cho một việc thật trong tuần. Đã dặn \"công sức\" ít nhất một lần (nhanh gọn, hoặc làm thật kỹ). Đã dặn \"kiểm tra thế nào\" và nhận được báo cáo \"đã kiểm gì, chưa kiểm được gì\". Biết khi nào vẫn cần nói nhiều hơn một câu.", "k": "page"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Đi xa hơn", "u": "giao-viec-nhu-dong-nghiep.html#di-xa-hon", "x": "Xem phần case study trong bài trình chiếu ở chế độ tự học. Áp dụng ba điều cho email khó ở Bậc 1 , và cho việc giao cả đầu việc ở Bậc 7 . Đọc Khoảng cách AI : giao việc rõ ràng là cách nhanh nhất để đi xuống phễu. Lưu mẫu DN1 vào hướng dẫn tuỳ chỉnh hoặc một Project, để lần nào bạn ấy cũng nhớ hỏi lại và tự kiểm ( Bậc 5 ).", "k": "page"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "u": "giong-noi.html", "x": "Có những việc gõ mãi không ra, nói thì trôi. Chế độ giọng nói cho bạn một đồng nghiệp luôn rảnh, không phán xét, cuối buổi còn ghi lại giúp.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Khi nào dùng", "u": "giong-noi.html#khi-nao-dung", "x": "Ý còn rối, chưa thành câu: nói lan man dễ hơn gõ một câu mở đầu hoàn hảo. Cần tập nói thật: xin tăng lương, đòi nợ, thuyết trình. Tay bận: đang đi bộ, chờ xe, vừa họp xong. Luyện ngoại ngữ mà ngại nói sai trước người thật. Cần bảng biểu, con số chính xác thì gõ vẫn chắc hơn.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Cách nhờ", "u": "giong-noi.html#cach-nho", "x": "Trên điện thoại, mở chế độ giọng nói của app ChatGPT, Claude, hoặc Gemini Live trong app Gemini: tìm biểu tượng sóng âm hoặc micro. Micro trên bàn phím chỉ gõ hộ bạn; chế độ giọng nói mới là trò chuyện qua lại. Tiếng Việt tốt đến đâu? Hãy thử để biết, chất lượng thay đổi theo công cụ và thời điểm. Bản miễn phí có thể giới hạn thời lượng; kiểm tra trang chính thức vì gói và giới hạn thay đổi thường xuyên. Câu mở đầu v", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Làm thật", "u": "giong-noi.html#lam-that", "x": "", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Tình huống 1 · Nghĩ thành tiếng để gỡ rối việc khó", "u": "giong-noi.html#tinh-huong-1-nghi-thanh-tieng-de-go-roi-viec-kho", "x": "Hai phương án chưa chọn được, một tuần quá tải: cứ kể ra. Bạn sẽ thấy Những câu hỏi kiểu \"nếu chọn A thì điều tệ nhất là gì?\". Sau 5–10 phút, bạn thường tự nói ra điều mình đã biết mà chưa gọi tên được.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Tình huống 2 · Tập trước một cuộc nói chuyện khó", "u": "giong-noi.html#tinh-huong-2-tap-truoc-mot-cuoc-noi-chuyen-kho", "x": "Đòi nợ, xin tăng lương, báo tin xấu cho khách: ngoài đời chỉ có một lần, với bạn ấy thì tập mấy lần cũng được. Bạn sẽ thấy Vai diễn có lúc gắt, có lúc hỏi vặn. Lần đầu lúng túng chính là mục đích. Tập lại đúng chỗ vấp; đến lần thứ ba, bạn thường đã có câu mở đầu chắc chắn.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Tình huống 3 · Luyện tiếng Anh cho công việc", "u": "giong-noi.html#tinh-huong-3-luyen-tieng-anh-cho-cong-viec", "x": "Bạn ấy kiên nhẫn, không cười khi bạn sai, lại nói đúng chủ đề công việc. Bạn sẽ thấy Hội thoại chậm rãi, đúng bối cảnh, sửa lỗi bằng tiếng Việt nên không ngợp. Cuối buổi, xin thêm: \"10 câu mình nên thuộc cho tình huống này.\"", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Tình huống 4 · Ý tưởng lúc di chuyển thành việc cần làm", "u": "giong-noi.html#tinh-huong-4-y-tuong-luc-di-chuyen-thanh-viec-can-lam", "x": "Ý hay thường đến lúc đi bộ, chờ thang máy, ngồi taxi. Đọc ra luôn. An toàn trên đường Đừng cầm hay bấm điện thoại khi đang lái xe. Hãy tấp vào chỗ an toàn và dừng hẳn, hoặc chỉ dùng thiết bị rảnh tay trong phạm vi luật cho phép. Không chắc thì cứ dừng xe. Bạn sẽ thấy Danh sách ba nhóm, gọn để dán vào ghi chú. Vài chỗ [CHƯA RÕ] là dấu hiệu tốt: bạn ấy không tự bịa hạn chót hay tên người.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Tình huống 5 · Chuẩn bị bài phát biểu, nghe phản hồi", "u": "giong-noi.html#tinh-huong-5-chuan-bi-bai-phat-bieu-nghe-phan-hoi", "x": "Nói to một lần, bạn sẽ nghe ra chỗ vấp mà đọc thầm không thấy. Bạn sẽ thấy Nhận xét cụ thể về cấu trúc, độ dài, câu nên cắt. Góp ý về ngữ điệu có thể chưa chuẩn, tuỳ công cụ; tự ghi âm rồi nghe lại để chắc.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Dám hỏi lại", "u": "giong-noi.html#dam-hoi-lai", "x": "Giọng nói trôi nhanh nên dễ gật gù. Ba chỗ hay sai: bạn ấy nghe nhầm tên và số (\"mười lăm\" thành \"năm mươi\"), trả lời ngắn nên bỏ bớt điều kiện, và quá dễ tính khi đóng vai. Soát nhanh sau mỗi cuộc nói chuyện Tên, số, ngày nhắc lại có khớp điều bạn nói không? Bản tóm tắt có ý nào bạn chưa hề nói không? Lời khuyên về luật, thuế: đã đối chiếu nguồn chính thức chưa? Tập vai mà bạn ấy nhường quá? Nói \"khó hơn nữa\".", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Biến thể theo ngành", "u": "giong-noi.html#bien-the-theo-nganh", "x": "", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "⚖️ Pháp lý", "u": "giong-noi.html#phap-ly", "x": "Tập giải thích rủi ro bằng lời thường cho một khách hay hỏi dồn.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "💰 Kế toán – Tài chính", "u": "giong-noi.html#ke-toan-tai-chinh", "x": "Giải trình chênh lệch chi phí trước giám đốc: ngắn mà căng, nên tập trước.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "🤝 Kinh doanh – CSKH", "u": "giong-noi.html#kinh-doanh-cskh", "x": "Cuộc gọi chào hàng hay hỏng ở 20 giây đầu.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "🏗️ Vận hành – Xây dựng", "u": "giong-noi.html#van-hanh-xay-dung", "x": "Đi một vòng kho hay công trường, đứng ở chỗ an toàn, đọc nhanh những gì thấy.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Còn việc gì giống vậy?", "u": "giong-noi.html#con-viec-gi-giong-vay", "x": "💼 Công việc Tập trả lời phỏng vấn Xả ý sau buổi họp thành biên bản nháp Luyện cách từ chối việc ngoài phạm vi Tập báo tin xấu cho cả nhóm 🏡 Đời sống Tập nói chuyện khó với người nhà Luyện tiếng Anh trước chuyến du lịch Nghĩ thành tiếng trước một khoản chi lớn Tập lời phát biểu ở đám cưới bạn thân Cần nghĩ cho rõ hay cần tập nói, cứ mở lời trước: nói lan man cũng được, miễn cuối buổi xin bạn ấy tóm thành chữ để kiểm.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Tự kiểm tra", "u": "giong-noi.html#tu-kiem-tra", "x": "Đã tìm được nút chế độ giọng nói trên ít nhất một app. Đã nói chuyện 5 phút mà không gõ, và thử ngắt lời bạn ấy. Đã nhờ bạn ấy nhắc lại tên, số và tóm tắt thành văn bản. Đã tập trước một cuộc nói chuyện khó có thật của mình.", "k": "topic"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Đi xa hơn", "u": "giong-noi.html#di-xa-hon", "x": "Nói để xả ý, gõ để chốt. Bản tóm tắt sau khi nói là nguyên liệu tốt cho email khó ở Bậc 1 . Nghe qua tai càng phải hỏi lại. Thói quen hỏi \"căn cứ đâu?\" ở Bậc 2 càng cần ở đây. Kết hợp với ảnh. Gửi ảnh như ở Chụp ảnh là nhờ được , rồi nói thêm bối cảnh thay vì gõ.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Khi nào dùng", "u": "giong-van.html#khi-nao-dung", "x": "Bạn nhờ AI viết email. Đúng ngữ pháp, đủ ý, nhưng không phải bạn: \"Kính gửi Quý khách\", \"Trong bối cảnh thị trường ngày càng cạnh tranh\". Người nhận đọc hai câu là đoán ra máy viết. Bạn ấy chưa viết như bạn chỉ vì chưa ai dạy. Dùng khi: Bạn viết nhiều: email, báo cáo, thông báo, bài đăng. Công ty có quy ước về xưng hô, thuật ngữ, tên sản phẩm. Nhiều người cùng viết mà khách cần nghe \"một giọng\".", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Cách nhờ", "u": "giong-van.html#cach-nho", "x": "Viết đúng giọng cũng là giao việc, nên vẫn là 3 điều như khi nói với đồng nghiệp: Bạn muốn gì: viết gì, cho ai, theo giọng nào. Bỏ bao nhiêu công sức: nháp nhanh để bạn sửa, hay bản gửi thật cần soát kỹ. Kiểm tra thế nào: đối chiếu bản mô tả và bảng thuật ngữ, báo lại đã sửa gì. Và như mọi khi: thiếu gì thì hỏi mình .", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Làm thật", "u": "giong-van.html#lam-that", "x": "", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Tình huống 1 · Rút ra \"bản mô tả giọng văn\" rồi lưu lại", "u": "giong-van.html#tinh-huong-1-rut-ra-ban-mo-ta-giong-van-roi-luu-lai", "x": "Chọn 3–5 bài bạn ưng nhất, che tên người, tên công ty, số tiền , rồi dán vào: Để khỏi dán lại mỗi lần, lưu bản mô tả vào hướng dẫn tuỳ chỉnh (custom instructions) hoặc một Project/Gem riêng cho việc viết ( Bậc 5 ). Tên và vị trí các mục này thay đổi thường xuyên, nên kiểm tra trang chính thức hoặc hỏi thẳng bạn ấy. Bạn sẽ thấy Kiểu như: \"Câu ngắn, dưới 20 chữ. Xưng 'em', gọi khách là 'anh/chị'. Vào việc ngay câu đầu.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Tình huống 2 · Bảng thuật ngữ của công ty", "u": "giong-van.html#tinh-huong-2-bang-thuat-ngu-cua-cong-ty", "x": "Ba nhân viên, ba cách gọi khách, ba cách viết tên công ty. Một bảng thuật ngữ nhỏ là đủ chữa. Bạn sẽ thấy Bảng 10–20 dòng, có cả điểm bạn chưa nghĩ tới: \"hoá đơn\" hay \"hóa đơn\", \"đơn hàng\" hay \"order\". Duyệt xong, lưu cùng chỗ với bản mô tả.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Tình huống 3 · Một thông điệp, ba người đọc", "u": "giong-van.html#tinh-huong-3-mot-thong-diep-ba-nguoi-doc", "x": "Cùng một tin: sếp cần quyết, khách cần yên tâm, đồng nghiệp cần biết việc. Bạn sẽ thấy Ba bản khác hẳn độ dài và cách mở đầu, nhưng cùng một \"người viết\": bản cho sếp có số và lựa chọn, bản cho khách ấm áp, bản cho đồng nghiệp gần như toàn động từ.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Tình huống 4 · \"Khử mùi AI\"", "u": "giong-van.html#tinh-huong-4-khu-mui-ai", "x": "Văn máy dễ nhận: sáo ngữ (\"trong bối cảnh... ngày càng...\", \"đóng vai trò quan trọng\"), câu văn dịch (\"được thực hiện bởi\"), liệt kê đều tăm tắp mà rỗng, câu kết \"Tóm lại\" nhắc lại điều vừa nói. Bạn sẽ thấy Danh sách chỗ \"có mùi\" kèm lý do, rồi bản viết lại gọn hơn. Đọc vài lần, bạn sẽ tự \"ngửi\" ra chúng trong văn của chính mình.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Tình huống 5 · Chấm bài theo bản mô tả", "u": "giong-van.html#tinh-huong-5-cham-bai-theo-ban-mo-ta", "x": "Bản mô tả còn là thước đo cho bài của bạn, của đồng nghiệp, hay của AI. Bạn sẽ thấy Điểm số kèm lỗi có trích dẫn: dùng \"quý khách\", câu dài 40 chữ, mở đầu vòng vo. Câu cuối giữ bạn ấy khỏi \"sửa cho vui\".", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Dám hỏi lại", "u": "giong-van.html#dam-hoi-lai", "x": "Có hai cái bẫy. Một là bắt chước quá đà : thấy bạn hay viết \"anh chị xem giúp em\", bạn ấy nhét nó vào mọi đoạn. Hai là đúng giọng nhưng sai nội dung . Dám hỏi lại Đặt cạnh bản gốc: bản mới giống bạn ở một ngày bình thường, hay giống bạn bị phóng đại? Đọc to: chỗ nào vấp, hoặc nghĩ \"mình đâu có nói thế\", sửa chỗ đó. Soát nội dung: giọng đúng không có nghĩa số, tên, ngày đúng. Không dán bài có thông tin mật để \"học giọ", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Biến thể theo ngành", "u": "giong-van.html#bien-the-theo-nganh", "x": "", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "⚖️ Pháp lý", "u": "giong-van.html#phap-ly", "x": "Thư tư vấn của hãng luật có giọng riêng, nhất là cách dẫn chiếu và mức độ khẳng định.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "💰 Kế toán – Tài chính", "u": "giong-van.html#ke-toan-tai-chinh", "x": "Thuyết minh báo cáo cần gọi tên khoản mục nhất quán qua các tháng.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "🤝 Kinh doanh – CSKH", "u": "giong-van.html#kinh-doanh-cskh", "x": "Cả đội trả lời khách cùng một giọng, qua email hay tin nhắn.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "🏗️ Vận hành – Xây dựng", "u": "giong-van.html#van-hanh-xay-dung", "x": "Thông báo công trường cần ngắn, rõ, đọc được trên điện thoại giữa ca.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Còn việc gì giống vậy?", "u": "giong-van.html#con-viec-gi-giong-vay", "x": "💼 Công việc Câu trả lời mẫu chung một giọng cho cả đội. Bài đăng fanpage, bản tin nội bộ. Thư chúc mừng, bài phát biểu viết thay sếp. Tài liệu kỹ thuật viết lại cho khách dễ hiểu. 🏡 Đời sống Lời chúc, thiệp mời đúng giọng bạn. Bài đăng kể chuyện gia đình. Thư cảm ơn thầy cô, lời phát biểu đám cưới. Đơn gửi ban quản lý chung cư: lịch sự mà không khách sáo. Ở đâu có tên bạn ký bên dưới, ở đó cần giọng của bạn.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Tự kiểm tra", "u": "giong-van.html#tu-kiem-tra", "x": "Đã có bản mô tả giọng văn từ 3–5 bài cũ đã che thông tin. Đã lưu nó vào hướng dẫn tuỳ chỉnh, Project hoặc Gem. Đã có bảng thuật ngữ ít nhất 5 dòng. Đã viết một thông điệp cho 3 người đọc. Đã khử mùi AI một bản nháp và đọc to bản cuối.", "k": "topic"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Đi xa hơn", "u": "giong-van.html#di-xa-hon", "x": "Cập nhật mỗi quý: thay bài mẫu bằng bài mới nhất bạn ưng, rồi rút lại bản mô tả. Một giọng cho cả đội: đưa bản mô tả và bảng thuật ngữ vào một Project dùng chung ( Bậc 5 ) nếu gói cho phép chia sẻ. Kiểm tra trang chính thức vì gói, giới hạn và giao diện thay đổi thường xuyên. Từ \"nhờ viết\" sang \"dạy viết\": đó là một bước đi xuống phễu ( Khoảng cách AI ). Dạy xong, câu nhờ hằng ngày chỉ cần 3 điều ( Giao việc như giao", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Khi nào dùng", "u": "hoc-nhanh.html#khi-nao-dung", "x": "Ai cũng từng ước có một gia sư riêng: giảng lần thứ năm vẫn không thở dài, hỏi câu \"ngớ ngẩn\" cũng không cười. Giờ bạn có rồi. Hãy dùng bạn ấy để học , chứ không chỉ để làm hộ, khi: Nhận mảng việc mới, hoặc có quy định mới cần nắm trong vài ngày. Muốn lên tay một kỹ năng: hàm Excel nâng cao, đọc báo cáo tài chính. Phải hiểu thật một tài liệu dài, hoặc cần kèm con học bài. Góc nhìn Andrej Karpathy hình dung người dùng", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Cách nhờ", "u": "hoc-nhanh.html#cach-nho", "x": "Gia sư giỏi hỏi bạn biết gì, giải thích vừa tầm, rồi hỏi lại để chắc bạn hiểu. Muốn vậy, nói rõ 3 điều như khi giao việc cho đồng nghiệp: Bạn muốn gì: học cái gì, để làm gì, đến mức nào là đủ. Bỏ bao nhiêu công sức: lướt 15 phút trước cuộc họp, hay học chắc trong hai tuần. Kiểm tra thế nào: bạn ấy hỏi bạn ra sao để biết bạn hiểu thật. Và câu quen thuộc: thiếu gì thì hỏi mình .", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Làm thật", "u": "hoc-nhanh.html#lam-that", "x": "", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Tình huống 1 · Giải thích theo 3 mức", "u": "hoc-nhanh.html#tinh-huong-1-giai-thich-theo-3-muc", "x": "Cùng một chủ đề, ba mức giải thích, bạn sẽ tự thấy mình đang đứng ở đâu. Bạn sẽ thấy Ba đoạn từ dễ đến khó. Mức 1 thấy dễ, mức 3 bắt đầu hoa mắt: chỗ chuyển giữa hai cảm giác ấy là trình độ của bạn. Học tiếp từ đó.", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Tình huống 2 · Bạn ấy hỏi, bạn nghĩ", "u": "hoc-nhanh.html#tinh-huong-2-ban-ay-hoi-ban-nghi", "x": "Đọc giải thích thì thấy hiểu, gấp lại thì quên. Điều tự nghĩ ra mới nhớ lâu, nên hãy đảo vai: Đây cũng là cách kèm con học mà không làm hộ: Bạn sẽ thấy Những câu hỏi nhỏ nối nhau như bậc thang. Hơi chậm, nhưng 3 điều cuối buổi là của bạn. Với bài của con, bạn ấy dừng ở gợi ý để con tự viết ra đáp án.", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Tình huống 3 · Ra đề và chấm điểm", "u": "hoc-nhanh.html#tinh-huong-3-ra-de-va-cham-diem", "x": "Cảm giác \"hiểu rồi\" hay đánh lừa. Một bài kiểm tra nhỏ cho bạn biết thật. Bạn sẽ thấy Mỗi câu có nhận xét cụ thể, cuối bài là danh sách phần cần ôn. Chấm chưa thuyết phục? Hỏi lại: \"Vì sao câu của mình chưa đủ?\"", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Tình huống 4 · Lộ trình 2 tuần cho một kỹ năng", "u": "hoc-nhanh.html#tinh-huong-4-lo-trinh-2-tuan-cho-mot-ky-nang", "x": "Kỹ năng thật cần luyện nhiều ngày, nên chia nhỏ thành 14 buổi vừa sức. Bạn sẽ thấy Vài câu hỏi về trình độ, rồi bảng 14 ngày có bài tập và ngày ôn xen giữa. Mỗi tối mở lại cuộc trò chuyện này và nói: \"Hôm nay ngày 6.\"", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Tình huống 5 · Học từ một tài liệu dài", "u": "hoc-nhanh.html#tinh-huong-5-hoc-tu-mot-tai-lieu-dai", "x": "Nghị định, sổ tay quy trình dài vài chục trang: tóm tắt thì nhanh, hiểu thật thì cần được hỏi. Tải lên ChatGPT, Claude hoặc NotebookLM, rồi nói: Bạn sẽ thấy Dàn ý trước, rồi những vòng hỏi nhỏ sau mỗi phần. Quý nhất là trích dẫn: bạn lật đúng trang và hiểu bằng chính câu chữ gốc.", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Dám hỏi lại", "u": "hoc-nhanh.html#dam-hoi-lai", "x": "Gia sư AI có thể giải thích rất tự tin mà vẫn sai, nhất là với quy định mới, mức thuế, số liệu, thời hạn : những thứ có thể đã thay đổi sau lúc bạn ấy được huấn luyện. Dám hỏi lại Văn bản gốc là trọng tài: đối chiếu số hiệu, ngày hiệu lực, điều khoản. Điều bạn ấy trích mà bạn không tìm thấy, coi như chưa đúng. Cho bạn ấy đọc nguồn: tải chính văn bản lên, hoặc bật tìm kiếm web nếu công cụ có. Hỏi lại người có chuyên m", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Biến thể theo ngành", "u": "hoc-nhanh.html#bien-the-theo-nganh", "x": "", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "⚖️ Pháp lý", "u": "hoc-nhanh.html#phap-ly", "x": "Đặt văn bản mới cạnh văn bản cũ, rồi tự thử áp dụng.", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "💰 Kế toán – Tài chính", "u": "hoc-nhanh.html#ke-toan-tai-chinh", "x": "Học đọc báo cáo tài chính ngay trên tài liệu thật.", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "🤝 Kinh doanh – CSKH", "u": "hoc-nhanh.html#kinh-doanh-cskh", "x": "Hiểu ngành của khách trước buổi gặp, rồi tập trả lời như thật.", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "🏗️ Vận hành – Xây dựng", "u": "hoc-nhanh.html#van-hanh-xay-dung", "x": "Hiểu một quy trình, rồi biến nó thành câu hỏi kiểm tra tổ đội.", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Còn việc gì giống vậy?", "u": "hoc-nhanh.html#con-viec-gi-giong-vay", "x": "💼 Công việc Làm quen phần mềm mới. Tập phỏng vấn, bạn ấy đóng vai người hỏi. Học thuật ngữ tiếng Anh chuyên ngành. Soạn câu hỏi kiểm tra sau đào tạo. 🏡 Đời sống Kèm con học mà không làm hộ. Luyện ngoại ngữ mỗi tối. Tìm hiểu bảo hiểm, khoản vay trước khi ký. Hiểu kết quả khám để hỏi bác sĩ đúng câu. Lúc nào bạn nghĩ \"giá có ai kèm mình chuyện này\", đó là lúc mở một gia sư.", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Tự kiểm tra", "u": "hoc-nhanh.html#tu-kiem-tra", "x": "Đã nhờ giải thích theo 3 mức và biết mình ở mức nào. Đã học một buổi hỏi đáp, tự nghĩ ra câu trả lời. Đã làm bài kiểm tra 5 câu và biết phần cần ôn. Đã có lộ trình 2 tuần cho một kỹ năng thật. Đã tự đối chiếu một ý quan trọng với nguồn chính thức.", "k": "topic"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Đi xa hơn", "u": "hoc-nhanh.html#di-xa-hon", "x": "Gia sư nhớ bài: lưu lộ trình và trình độ vào Project hoặc Gem ( Bậc 5 ), mỗi buổi chỉ cần nói \"học tiếp\". Dạy lại để hiểu sâu: viết lại điều vừa học bằng lời của bạn, nhờ bạn ấy bắt lỗi. Học để giao việc lớn hơn: hiểu thêm là thêm một bước xuống phễu. Đọc Khoảng cách AI và Giao việc như giao cho đồng nghiệp .", "k": "topic"}, {"t": "Hỏi đáp thường gặp", "h": "Hỏi đáp thường gặp", "u": "hoi-dap.html", "x": "Đây là những câu mình được hỏi nhiều nhất, sau buổi chia sẻ và trong nhóm Zalo. Câu nào bạn cũng thắc mắc thì yên tâm: bạn không phải người duy nhất. Không thấy câu của mình ở đây? Hỏi thẳng bạn ấy trước, rồi hỏi mình sau.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Bắt đầu", "u": "hoi-dap.html#bat-dau", "x": "", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Không biết bắt đầu từ đâu?", "u": "hoi-dap.html#khong-biet-bat-dau-tu-dau", "x": "Bắt đầu từ chính công việc của bạn, không phải từ công cụ. Mở ChatGPT hoặc Claude, gõ câu dưới đây, rồi chọn một việc dễ nhất trong danh sách bạn ấy đưa ra để làm thử luôn. Sau đó đi lần lượt từ Bậc 1 , mỗi bậc chỉ mất khoảng 20–30 phút.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Sợ kỹ thuật, có cần học code không?", "u": "hoi-dap.html#so-ky-thuat-co-can-hoc-code-khong", "x": "Không cần. Bậc 1 đến Bậc 6 trên trang này đều làm bằng cách gõ hoặc nói tiếng Việt bình thường , kể cả Bậc 6 là nhờ bạn ấy làm cả một ứng dụng. Kỹ năng quan trọng nhất là kể rõ việc mình cần, giống như giao việc cho đồng nghiệp. Phần dùng Terminal như Claude Code là hoàn toàn tự chọn.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Tiếng Anh kém có dùng được không?", "u": "hoi-dap.html#tieng-anh-kem-co-dung-duoc-khong", "x": "Dùng tốt. Các công cụ lớn đều hiểu và viết tiếng Việt có dấu khá tốt, bạn cứ nói chuyện bằng tiếng Việt. Gõ không dấu, viết tắt, sai chính tả, bạn ấy vẫn thường hiểu. Nếu một nút bấm hay menu là tiếng Anh, chụp màn hình và hỏi bạn ấy \"nút này để làm gì?\". Thêm nữa, đây còn là một người bạn luyện tiếng Anh rất kiên nhẫn.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Dùng trên điện thoại được không?", "u": "hoi-dap.html#dung-tren-dien-thoai-duoc-khong", "x": "Được. ChatGPT, Claude, Gemini đều có app điện thoại, và nhiều việc làm trên điện thoại còn tiện hơn: chụp ảnh hoá đơn, nói chuyện bằng giọng nói khi đi đường. Riêng các bài cần mở file Excel lớn hoặc làm công cụ ở Bậc 6 , dùng máy tính sẽ dễ nhìn hơn.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Có cần học viết prompt \"chuẩn\" không?", "u": "hoi-dap.html#co-can-hoc-viet-prompt-chuan-khong", "x": "Không cần học công thức. Chính người tạo ra Claude Code, Boris Cherny, nói: \"Hãy nói chuyện với Claude như nói với một đồng nghiệp. Prompt chẳng có bí mật gì cả.\" Cứ nói rõ ba điều: muốn gì (mục tiêu, cho ai, thế nào là tốt), bỏ bao nhiêu công sức (nhanh gọn hay làm thật kỹ), và kiểm tra thế nào . Quên ý nào cũng không sao, vì bạn có thể thêm câu \"thiếu gì thì hỏi mình trước nhé\". Xem Giao việc như giao cho đồng nghi", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Công cụ & chi phí", "u": "hoi-dap.html#cong-cu-chi-phi", "x": "", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Bản miễn phí có đủ không?", "u": "hoi-dap.html#ban-mien-phi-co-du-khong", "x": "Đủ để bắt đầu và đủ cho phần lớn trang này: Bậc 1 đến Bậc 4 và Bậc 6 làm được bằng bản miễn phí, dù có thể bị giới hạn lượt dùng hoặc số file tải lên. Bậc 5 (Project, Gem) tuỳ công cụ, bản miễn phí có thể bị giới hạn; nếu chưa dùng được, bạn lưu hướng dẫn vào file ghi chú và dán vào đầu mỗi cuộc trò chuyện. Bậc 7 (agent) thường cần gói trả phí. Giới hạn thay đổi thường xuyên, nên hãy kiểm tra trang chính thức của từn", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "ChatGPT hay Claude?", "u": "hoi-dap.html#chatgpt-hay-claude", "x": "Như chọn bạn: mỗi người một thế mạnh, nên chơi với cả hai. Nhiều người thấy ChatGPT đa năng, giọng nói rất tự nhiên; Claude đọc tài liệu dài và viết tiếng Việt mượt, lại làm công cụ nhỏ rất giỏi. Cách chắc nhất là đưa cùng một việc cho cả hai và tự so. Quan trọng hơn công cụ là cách bạn nói chuyện . Xem Bản đồ công cụ AI .", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Có nên mua gói trả phí không? Mua gói nào?", "u": "hoi-dap.html#co-nen-mua-goi-tra-phi-khong-mua-goi-nao", "x": "Chỉ mua khi bạn biết rõ mình cần thêm gì: thêm lượt dùng, file lớn hơn, Project, Deep Research, hay agent. Chọn một công cụ mình dùng nhiều nhất để nâng cấp trước, đừng mua cùng lúc nhiều nơi. Nếu dùng cho công việc, hỏi công ty có tài trợ hoặc có sẵn tài khoản doanh nghiệp không. Giá và quyền lợi từng gói thay đổi liên tục, nên đọc kỹ trang chính thức trước khi trả tiền.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Sao cùng một câu hỏi mà mỗi lần trả lời khác?", "u": "hoi-dap.html#sao-cung-mot-cau-hoi-ma-moi-lan-tra-loi-khac", "x": "Vì mỗi lần bạn ấy \"viết lại từ đầu\", có một chút ngẫu nhiên trong cách chọn chữ, giống như bạn hỏi một người hai lần thì họ cũng không nói y hệt. Điều này có lợi khi bạn cần nhiều phương án để chọn. Khi cần kết quả ổn định (báo cáo định kỳ, văn bản theo mẫu), hãy đưa mẫu, tiêu chí rõ ràng, và đặt hướng dẫn trong Project . Với con số, luôn nhờ bạn ấy chỉ cách tính để kiểm tra.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Sao bạn ấy quên những gì mình nói hôm qua?", "u": "hoi-dap.html#sao-ban-ay-quen-nhung-gi-minh-noi-hom-qua", "x": "Mỗi cuộc trò chuyện mới thường là một trang giấy trắng. Muốn bạn ấy nhớ lâu, có ba cách: nói tiếp trong cuộc trò chuyện cũ (nếu chưa quá dài), bật tính năng bộ nhớ nếu công cụ có, hoặc tốt nhất là tạo Project / Gem chứa sẵn hướng dẫn và tài liệu. Đó chính là Bậc 5 : dạy bạn ấy một lần, nhờ mãi mãi.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Copilot ở công ty có giống ChatGPT không?", "u": "hoi-dap.html#copilot-o-cong-ty-co-giong-chatgpt-khong", "x": "Cùng là trợ lý AI, cách nói chuyện giống nhau, nên mọi cách nhờ trên trang này đều dùng được. Điểm khác: Copilot trong Microsoft 365 nằm ngay trong Outlook, Teams, Word, Excel và thường có điều khoản bảo vệ dữ liệu theo hợp đồng của công ty. Nếu công ty đã cấp, hỏi IT xem bạn được đưa loại dữ liệu nào vào.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "An toàn & đúng sai", "u": "hoi-dap.html#an-toan-dung-sai", "x": "", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Đưa hợp đồng công ty vào có sao không?", "u": "hoi-dap.html#dua-hop-dong-cong-ty-vao-co-sao-khong", "x": "Áp dụng đèn giao thông: hợp đồng nội bộ là đèn vàng, che tên, số hợp đồng, số tiền trước rồi mới đưa. Thông tin khách hàng định danh, số tài khoản, dữ liệu chưa công bố là đèn đỏ, không đưa. Với tài khoản cá nhân, tắt tuỳ chọn dùng dữ liệu để cải thiện mô hình. Và trên hết, làm theo quy định của công ty. Chi tiết ở Dùng AI an toàn .", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Nó làm sai thì sao?", "u": "hoi-dap.html#no-lam-sai-thi-sao", "x": "Như với người thật: nói cho bạn ấy biết sai chỗ nào, muốn thế nào . \"Đoạn hai sai số liệu, tổng đúng phải là…\", \"giọng văn cứng quá, viết như nói với khách quen\". Một lần chưa được thì nói tiếp, thường đến lần thứ hai, thứ ba là ổn. Nếu càng sửa càng rối, mở cuộc trò chuyện mới và kể lại từ đầu cho gọn.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Làm sao biết bạn ấy đang bịa?", "u": "hoi-dap.html#lam-sao-biet-ban-ay-dang-bia", "x": "Bạn không đoán được bằng cảm giác, vì câu bịa thường nghe rất tự tin. Hãy hỏi \"căn cứ đâu?\", nhờ trích nguyên văn kèm số điều, số trang, rồi tự mở bản gốc kiểm 1–2 điểm. Cẩn thận gấp đôi với con số, ngày tháng, tên riêng và trích dẫn pháp luật. Thử bài bẫy ở Bậc 2 để tận mắt thấy bạn ấy đoán.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Công ty chưa cho phép thì sao?", "u": "hoi-dap.html#cong-ty-chua-cho-phep-thi-sao", "x": "Thì đừng đưa dữ liệu công ty vào, kể cả đã che. Bạn vẫn học được rất nhiều: luyện với dữ liệu hư cấu trên trang này, dùng AI cho kiến thức chung (cách viết công thức, cấu trúc một tờ trình, kỹ năng đàm phán), và cho đời sống. Song song, hỏi IT hoặc quản lý xem công ty có kế hoạch cho phép không. Khi bạn đã thành thạo, chính bạn có thể là người đề xuất cách dùng an toàn cho cả phòng.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Tắt \"dùng dữ liệu để huấn luyện\" rồi thì đưa gì vào cũng được?", "u": "hoi-dap.html#tat-dung-du-lieu-de-huan-luyen-roi-thi-dua-gi-vao-cung-duoc", "x": "Chưa. Tắt tuỳ chọn đó giúp giảm rủi ro, nhưng nội dung vẫn được gửi lên máy chủ của nhà cung cấp, và nghĩa vụ bảo mật với khách hàng vẫn còn nguyên. Đèn đỏ vẫn là đèn đỏ.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Công việc", "u": "hoi-dap.html#cong-viec", "x": "", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "AI có thay thế mình không?", "u": "hoi-dap.html#ai-co-thay-the-minh-khong", "x": "Mình tin rằng người có bạn AI sẽ làm thay phần việc của người không có. AI làm nhanh phần nháp, phần lặp lại; còn phán đoán, quan hệ với khách, trách nhiệm ký tên vẫn là của bạn. Cách tốt nhất để không bị bỏ lại là trở thành người dùng AI giỏi nhất phòng. Andrej Karpathy ước lượng chỉ khoảng 20 triệu người trên thế giới dùng AI ở mức sâu cho việc chuyên môn, trong khi hàng tỷ người mới dùng thỉnh thoảng, và khoảng cá", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Dùng AI viết văn bản, có cần nói với sếp hay khách không?", "u": "hoi-dap.html#dung-ai-viet-van-ban-co-can-noi-voi-sep-hay-khach-khong", "x": "Tuỳ quy định công ty và loại văn bản, nên hỏi trước. Dù thế nào, người ký là người chịu trách nhiệm : đọc lại toàn bộ, kiểm con số và trích dẫn, sửa cho đúng giọng của mình. Với văn bản quan trọng, minh bạch về việc có AI hỗ trợ thường giúp bạn được tin hơn chứ không kém đi.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Kết quả chung chung, sáo rỗng thì làm sao?", "u": "hoi-dap.html#ket-qua-chung-chung-sao-rong-thi-lam-sao", "x": "Thường là do bạn ấy thiếu bối cảnh. Kể thêm: người nhận là ai, chuyện gì đã xảy ra, bạn muốn đạt điều gì. Đưa một văn bản mẫu bạn thích. Hoặc hỏi thẳng: \"Kết quả này chưa đúng ý mình nhưng mình không biết diễn tả sao. Bạn hỏi mình vài câu nhé.\" Xem thêm Bậc 1 .", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Làm sao để bạn ấy viết đúng giọng văn công ty mình?", "u": "hoi-dap.html#lam-sao-de-ban-ay-viet-dung-giong-van-cong-ty-minh", "x": "Đưa 2–3 văn bản cũ đã che thông tin và nói \"viết theo đúng phong cách, cấu trúc, cách xưng hô của các văn bản này\". Rồi nhờ bạn ấy tự tóm tắt \"đặc điểm giọng văn\" thành vài gạch đầu dòng, lưu vào hướng dẫn của Project. Từ đó, lần nào bạn ấy cũng viết đúng giọng. Xem Bậc 5 .", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Có dùng được cho Excel và số liệu không?", "u": "hoi-dap.html#co-dung-duoc-cho-excel-va-so-lieu-khong", "x": "Rất được: viết công thức bằng tiếng Việt, dọn dữ liệu lộn xộn, tìm dòng trùng, tóm tắt xu hướng. Nhưng với số liệu, luôn nhờ bạn ấy chỉ cách tính và tự kiểm 3 dòng ngẫu nhiên. Bắt đầu với file mẫu ở Bậc 3 .", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Tự học tiếp", "u": "hoi-dap.html#tu-hoc-tiep", "x": "", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Làm sao nhớ được hết prompt?", "u": "hoi-dap.html#lam-sao-nho-duoc-het-prompt", "x": "Không cần nhớ. Có ba \"túi\" để cất: Thư viện prompt trên trang này (có nút Copy và lọc theo ngành); một file ghi chú riêng chứa những câu bạn thấy hiệu quả; và với việc lặp lại, đặt hẳn hướng dẫn vào Project để chỉ cần gõ một câu ngắn. Và nhớ chiêu cuối: không biết nhờ thế nào thì hỏi thẳng bạn ấy.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Mỗi ngày nên dành bao lâu?", "u": "hoi-dap.html#moi-ngay-nen-danh-bao-lau", "x": "15 phút mỗi ngày tốt hơn 3 tiếng mỗi tháng. Mẹo dễ nhất: mỗi khi định làm một việc quen, dừng 10 giây và tự hỏi \"việc này nhờ bạn ấy được không?\". Bắt đầu với Thử thách 7 ngày để tạo thói quen.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Học xong 7 bậc rồi, đi tiếp thế nào?", "u": "hoi-dap.html#hoc-xong-7-bac-roi-di-tiep-the-nao", "x": "Chọn một việc lặp lại thật trong công việc của bạn (báo cáo tuần, đối chiếu công nợ, soạn công văn) và biến nó thành quy trình: một Project có hướng dẫn, mẫu, cách kiểm chứng. Đo thời gian trước và sau. Sau đó chia sẻ cho đồng nghiệp, vì dạy người khác là cách học nhanh nhất. Nếu tò mò hơn, tìm hiểu Deep Research, kết nối ứng dụng, rồi agent.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Có nên học thêm về agent, Claude Code không?", "u": "hoi-dap.html#co-nen-hoc-them-ve-agent-claude-code-khong", "x": "Nếu bạn hay phải xử lý nhiều file giống nhau, hoặc tò mò muốn tự động hoá, thì nên thử. Bắt đầu với agent có giao diện thân thiện như Claude Cowork trước, Claude Code sau. Cả hai cần gói trả phí, và Claude Code cần quyền cài phần mềm trên máy. Nếu không, Bậc 1 đến Bậc 6 đã đủ để bạn làm tốt hơn hẳn mỗi ngày.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Câu hỏi của bạn chưa có ở đây?", "u": "hoi-dap.html#cau-hoi-cua-ban-chua-co-o-day", "x": "Hỏi thẳng bạn ấy trước, kể rõ bối cảnh của bạn. Rồi mang câu hỏi (và câu trả lời của bạn ấy) vào nhóm để mọi người cùng bàn.", "k": "page"}, {"t": "Hỏi đáp thường gặp", "h": "Tự kiểm tra", "u": "hoi-dap.html#tu-kiem-tra", "x": "Mình đã chọn được 1–2 công cụ để dùng thường xuyên Mình biết bản miễn phí làm được gì cho việc của mình, và đã kiểm tra trang chính thức Mình biết chính sách AI của công ty mình Mình đã lưu ít nhất 3 prompt hay vào Thư viện hoặc file ghi chú riêng Mình đã chọn một việc lặp lại thật để biến thành quy trình", "k": "page"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Khi nào dùng", "u": "hop-hanh.html#khi-nao-dung", "x": "Một cuộc họp 60 phút thường kéo theo vài tiếng việc phụ: soạn chương trình, ghi biên bản, nhắc việc. Toàn việc chữ, đúng sở trường của người bạn AI: trước họp (chương trình, câu hỏi khó), sau họp (biên bản, bảng việc, email), và khi vắng mặt (cuộc họp mình lỡ, chuỗi email dài). Ghi âm: xin phép trước Đầu vào có thể là ghi chú vội, bản ghi chữ từ phần mềm họp mà công ty cho phép, hoặc bản ghi âm. Chỉ ghi âm khi mọi ng", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Cách nhờ", "u": "hop-hanh.html#cach-nho", "x": "Biên bản là việc AI làm nhanh nhưng dễ \"quá tay\": tự điền người nhận việc, tự đặt hạn, biến một ý kiến thành quyết định. Chữa bằng 3 điều mà Boris Cherny, người tạo ra Claude Code, khuyên nói rõ khi giao việc: Bạn muốn gì: biên bản cho ai đọc, dài bao nhiêu, gồm mục nào. Bỏ bao nhiêu công sức: bản nhanh gửi ngay, hay bản chỉn chu để lưu hồ sơ. Kiểm tra thế nào: chỉ ghi điều có trong ghi chú, đánh dấu chỗ không chắc. ", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Làm thật", "u": "hop-hanh.html#lam-that", "x": "Cuộc họp hư cấu Công ty CP Phân phối Thiết bị Văn phòng Sao Mai họp triển khai phần mềm kế toán mới: anh Minh (Giám đốc tài chính, chủ trì), chị Lan (Kế toán trưởng), anh Tuấn (IT), chị Ngọc (công nợ), anh Phong (kho).", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Tình huống 1 · Chương trình họp và câu hỏi khó", "u": "hop-hanh.html#tinh-huong-1-chuong-trinh-hop-va-cau-hoi-kho", "x": "Chương trình rõ thì họp ngắn hẳn. Tập trước với người khó tính nhất phòng, như ở Bậc 4 , thì vào họp bình tĩnh hơn. Bạn sẽ thấy Chương trình 4–6 mục có phút cụ thể, mỗi người một việc chuẩn bị. Rồi những câu rất \"đời\": chuyển dữ liệu giữa năm được không, số dư lệch thì ai chịu. Câu nào bạn trả lời lúng túng là câu cần chuẩn bị trước.", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Tình huống 2 · Ghi chú vội thành biên bản", "u": "hop-hanh.html#tinh-huong-2-ghi-chu-voi-thanh-bien-ban", "x": "Dưới đây là ghi chú vội của buổi họp hư cấu: không dấu, viết tắt, đúng kiểu ghi trong họp. Copy cả khối, dán vào cuộc trò chuyện mới. Bạn sẽ thấy Biên bản có dấu, chia mục rõ. Giờ soi ba điểm bẫy: Ngày chạy 1/1/2027 chưa chốt: hai dấu hỏi, chị Lan xin thêm một tuần. Chạy song song chưa chốt: anh Minh mới nói \"xem chi phí đã\". Việc map mã hàng chưa ai nhận , \"họp lại tuần sau\" chưa có ngày. Biên bản ghi \"đã thống nhất", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Tình huống 3 · Bảng việc và email sau họp", "u": "hop-hanh.html#tinh-huong-3-bang-viec-va-email-sau-hop", "x": "Nói tiếp trong cùng cuộc trò chuyện: Bạn sẽ thấy Bảng 5–7 việc, vài ô trống được đánh dấu: đó là những câu cần hỏi anh Minh trước khi gửi. Câu mời phản hồi rất đáng giữ: biên bản thành thứ cả nhóm cùng xác nhận.", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Tình huống 4 · Cuộc họp mình vắng, chuỗi email dài", "u": "hop-hanh.html#tinh-huong-4-cuoc-hop-minh-vang-chuoi-email-dai", "x": "Nghỉ phép đúng hôm họp, hay bị kéo vào chuỗi hai mươi email? Bạn chỉ cần biết phần của mình và mình phải quyết gì . Bạn sẽ thấy Nửa trang viết riêng cho bạn. Đáng đọc nhất là phần \"các bên nói khác nhau\": hay gặp là hai người hiểu khác nhau về cùng một hạn chót.", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Dám hỏi lại", "u": "hop-hanh.html#dam-hoi-lai", "x": "Biên bản sai nguy hiểm hơn không có, vì người ta sẽ làm theo. Coi chừng gán nhầm lời (ý chị Lan thành ý anh Minh), điền quyết định (câu \"xem đã\" thành \"đã thống nhất\"), và thêm chi tiết không có trong ghi chú. Kiểm chứng trước khi gửi Soát phần \"đã thống nhất\" và bảng việc với ghi chú gốc, từng dòng. Người và hạn phải do chính cuộc họp nói ra ; ô trống thì hỏi người chủ trì. Gửi bản nháp cho người chủ trì xác nhận tr", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Biến thể theo ngành", "u": "hop-hanh.html#bien-the-theo-nganh", "x": "", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "⚖️ Pháp lý", "u": "hop-hanh.html#phap-ly", "x": "Biên bản làm việc với đối tác có thể thành chứng cứ, nên tách rõ bên nào nói gì, hai bên thống nhất gì.", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "💰 Kế toán – Tài chính", "u": "hop-hanh.html#ke-toan-tai-chinh", "x": "Họp khoá sổ có nhiều việc nối nhau, việc này chờ việc kia.", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "🤝 Kinh doanh – CSKH", "u": "hop-hanh.html#kinh-doanh-cskh", "x": "Email tóm tắt gửi trong ngày giữ cho hai bên hiểu giống nhau.", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "🏗️ Vận hành – Xây dựng", "u": "hop-hanh.html#van-hanh-xay-dung", "x": "Giao ban công trường ghi theo hạng mục thì ai cũng thấy phần mình.", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Còn việc gì giống vậy?", "u": "hop-hanh.html#con-viec-gi-giong-vay", "x": "💼 Công việc Giao ban đầu tuần thành 5 việc ưu tiên Buổi phỏng vấn thành ghi nhận theo tiêu chí Buổi đào tạo thành tài liệu cho người vắng Cuộc gọi nhà cung cấp thành email xác nhận 🏡 Đời sống Họp phụ huynh: việc cần chuẩn bị Họp chung cư: biên bản ngắn gửi nhóm Họp gia đình lo đám cưới: ai lo việc gì Nhóm bạn bàn du lịch: ai lo khâu nào Nhiều người nói, việc rải rác? Đó là chỗ cho một biên bản ngắn và một bảng \"ai, v", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Tự kiểm tra", "u": "hop-hanh.html#tu-kiem-tra", "x": "Đã dùng câu mẫu HH1 với một cuộc họp thật. Đã biến ghi chú mẫu thành biên bản và soi đủ 3 điểm bẫy. Đã lập bảng việc mà không để bạn ấy tự gán người hoặc hạn. Biết phải xin phép trước khi ghi âm.", "k": "topic"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Đi xa hơn", "u": "hop-hanh.html#di-xa-hon", "x": "Dạy bạn ấy mẫu biên bản của phòng bằng Project hoặc Gem ( Bậc 5 ), rồi biến bảng việc thành công cụ theo dõi ( Bậc 6 ). Công ty đã cấp Copilot hay Gemini? Hỏi IT tính năng tóm tắt họp nào được dùng. Giao cả đầu việc: \"từ ghi chú này, làm biên bản, bảng việc và email; chưa rõ thì hỏi mình\". Đó là giao việc như giao cho đồng nghiệp , một bước đi xuống cái phễu mà Andrej Karpathy mô tả.", "k": "topic"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "u": "khoang-cach.html", "x": "Tháng 10/2026, Andrej Karpathy, một trong những người đồng sáng lập OpenAI, đăng lại một ý ông viết từ tháng 4, vì thấy nó ngày càng đúng: khoảng cách hiểu biết về AI giữa các nhóm người đang nới rộng . Ông không vẽ hai phe đối lập, mà vẽ một cái phễu . Trang này giải thích cái phễu đó bằng lời của dân văn phòng, giúp bạn tự xác định mình đang ở đâu, và đưa ra một kế hoạch 30 ngày để đi xuống một bậc. Đây là trang nề", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Cái phễu của Karpathy", "u": "khoang-cach.html#cai-pheu-cua-karpathy", "x": "Theo bài đăng trên X ngày 11/10/2026 (ông tự gọi là \"ước lượng trên giấy nháp\"): Tầng Số người (ước lượng) Họ trải nghiệm AI thế nào 1 Khoảng 6 tỷ (~75% dân số) Gần như chưa từng chạm vào AI 2 Khoảng 1–2 tỷ (~20%) Dùng thỉnh thoảng, chủ yếu bản miễn phí kiểu ChatGPT 3 Khoảng 20 triệu (0,2%) Dùng các mô hình mạnh nhất cho việc chuyên môn (chủ yếu lập trình, toán) và tận mắt thấy AI làm xong những dự án từng mất hàng t", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Ba lý do phễu ngày càng sâu", "u": "khoang-cach.html#ba-ly-do-pheu-ngay-cang-sau", "x": "Karpathy chỉ ra ba nguyên nhân. Mỗi nguyên nhân ứng với một trong ba câu để nhớ của khoá này.", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "1. Tham vọng: việc bạn giao lớn cỡ nào", "u": "khoang-cach.html#1-tham-vong-viec-ban-giao-lon-co-nao", "x": "Hỏi AI một câu và giao cho AI cả một dự án là hai trải nghiệm hoàn toàn khác. AI càng mạnh, người dám giao việc lớn càng bứt xa người chỉ hỏi vặt. Với dân văn phòng: đừng dừng ở \"viết lại email này\". Thử giao \"gom 5 file báo cáo thành báo cáo quản trị tháng\" ( Bậc 7 ). Đây là vế Dám nhờ mọi thứ .", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "2. Năng lực không đều, như răng cưa", "u": "khoang-cach.html#2-nang-luc-khong-deu-nhu-rang-cua", "x": "AI cực mạnh ở việc số hoá, kiểm chứng được: code, toán, số liệu có công thức. Ở những việc khác, có lúc rất giỏi, có lúc đoán. Người hiểu \"răng cưa\" này biết giao gì yên tâm, giao gì phải soát kỹ. Với dân văn phòng: tóm tắt hợp đồng thì giỏi, nhưng khi hợp đồng không nói gì, AI dễ lấp chỗ trống bằng một con số gần giống ( Bậc 2 ). Đây là vế Dám hỏi lại mọi thứ .", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "3. Quyền truy cập: miễn phí, trả phí, nội bộ", "u": "khoang-cach.html#3-quyen-truy-cap-mien-phi-tra-phi-noi-bo", "x": "Bản miễn phí, bản trả phí và bản nội bộ của phòng lab là ba AI rất khác nhau. Người chỉ thấy bản miễn phí dễ kết luận \"AI cũng thường thôi\". Với dân văn phòng: biết lúc nào bản miễn phí là đủ (phần lớn bài trên website này), lúc nào đáng thử bản trả phí (agent, file lớn, việc cần suy nghĩ lâu). Gói và giới hạn thay đổi thường xuyên, hãy xem trang chính thức của từng công cụ, hoặc trang Công cụ .", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Mỗi tầng trông thế nào ở văn phòng", "u": "khoang-cach.html#moi-tang-trong-the-nao-o-van-phong", "x": "Phễu của Karpathy nói về cả thế giới. Ở văn phòng, các tầng có thể nhận ra qua thói quen hằng ngày: Tầng Dấu hiệu Việc tiêu biểu Bậc trên website Chưa chạm Chưa có tài khoản, hoặc thử một lần rồi thôi Không có Bắt đầu Dùng thỉnh thoảng Hỏi như hỏi Google, một câu một lần, kết quả \"chung chung\" Viết lại email, hỏi định nghĩa Bậc 1 , Bậc 2 Dùng thành thạo Đưa file, nói tiếp trong một cuộc trò chuyện, biết hỏi căn cứ Dọ", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Bạn đang ở đâu?", "u": "khoang-cach.html#ban-dang-o-dau", "x": "Đọc từng dòng, đếm xem bao nhiêu dòng đúng với bạn trong tuần vừa rồi : Mình đã nhờ AI ít nhất 5 lần. Mình đã để AI hỏi lại mình trước khi làm (\"thiếu gì thì hỏi mình\"). Mình đã hỏi \"căn cứ đâu?\" hoặc đòi AI chỉ nguồn. Mình đã đưa cho AI một file (Word, Excel, PDF, ảnh). Mình đã nói tiếp nhiều lượt trong cùng một cuộc trò chuyện để ra nhiều thành phẩm. Mình có một Project, Gem hoặc hướng dẫn tuỳ chỉnh dùng đi dùng lạ", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Kế hoạch 30 ngày đi xuống một bậc", "u": "khoang-cach.html#ke-hoach-30-ngay-di-xuong-mot-bac", "x": "Mỗi tuần một trọng tâm, mỗi ngày 15–20 phút. Việc nào cũng là việc thật của bạn, không phải bài tập.", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Bước 1 · Tuần 1: nhờ mỗi ngày, giao như cho đồng nghiệp", "u": "khoang-cach.html#buoc-1-tuan-1-nho-moi-ngay-giao-nhu-cho-dong-nghiep", "x": "Mỗi ngày nhờ một việc nhỏ, nói rõ muốn gì, công sức bao nhiêu, kiểm tra thế nào , và thêm \"thiếu gì thì hỏi mình\". Cuối tuần, hỏi lại căn cứ cho ít nhất một câu trả lời quan trọng. Đọc Giao việc như giao cho đồng nghiệp , Bậc 1 , Bậc 2 .", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Bước 2 · Tuần 2: đưa file và nói tiếp", "u": "khoang-cach.html#buoc-2-tuan-2-dua-file-va-noi-tiep", "x": "Đưa cho bạn ấy một file thật (đã che thông tin nhạy cảm), nhờ dọn, tổng hợp, rồi nói tiếp trong cùng cuộc trò chuyện để ra báo cáo hoặc slide. Đọc Bậc 3 , Bậc 4 .", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Bước 3 · Tuần 3: dạy bạn ấy một việc lặp lại", "u": "khoang-cach.html#buoc-3-tuan-3-day-ban-ay-mot-viec-lap-lai", "x": "Chọn một việc bạn làm hằng tuần, để bạn ấy phỏng vấn bạn và tự viết hướng dẫn, rồi tạo Project hoặc Gem. Đọc Bậc 5 , chuyên đề Viết đúng giọng của bạn .", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Bước 4 · Tuần 4: giao một việc lớn hơn bạn nghĩ", "u": "khoang-cach.html#buoc-4-tuan-4-giao-mot-viec-lon-hon-ban-nghi", "x": "Nhờ làm một công cụ nhỏ cho nhóm, hoặc giao một đầu việc nhiều bước và chỉ duyệt kế hoạch. Đọc Bậc 6 , Bậc 7 . Đo khoảng cách của chính bạn Cuối mỗi tuần ghi ba con số: số lần nhờ trong tuần, việc lớn nhất đã giao, và số lần đã kiểm chứng . Sau 4 tuần, nhìn lại: việc lớn nhất có lớn dần không?", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Đừng chỉ bứt lên: kéo người khác theo", "u": "khoang-cach.html#dung-chi-but-len-keo-nguoi-khac-theo", "x": "Sáu tỷ người chưa chạm vào AI. Trong số đó có thể có bố mẹ, con cái, đồng nghiệp của bạn. Khoảng cách không chỉ để mình bứt lên. Người đi trước có thể kéo người đi sau, và dạy lại cho người khác cũng là cách học nhanh nhất.", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Hiểu đúng về phễu", "u": "khoang-cach.html#hieu-dung-ve-pheu", "x": "Không phải cuộc đua. Mục tiêu là làm việc tốt hơn, không phải dùng AI nhiều hơn người khác. 19/21 người trong khảo sát của nhóm muốn AI giúp làm tốt hơn , không chỉ nhanh hơn. Đi sâu phải đi cùng tỉnh táo. Càng giao việc lớn, càng cần kiểm chứng và giữ ranh giới dữ liệu. Xem An toàn & tỉnh táo . Trả phí không tự động đưa bạn xuống phễu. Nhiều người trả phí mà vẫn hỏi một câu một lần. Thói quen giao việc mới là thứ tạ", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Tự kiểm tra", "u": "khoang-cach.html#tu-kiem-tra", "x": "Giải thích được cái phễu của Karpathy bằng lời của mình. Nói được ba nguyên nhân phễu ngày càng sâu, và câu để nhớ ứng với mỗi nguyên nhân. Biết mình đang ở tầng nào (đã đếm 8 dòng ở trên). Đã có kế hoạch 30 ngày, tuần đầu đã bắt đầu. Đã nghĩ ra một người mình sẽ \"kéo theo\".", "k": "page"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Đi xa hơn", "u": "khoang-cach.html#di-xa-hon", "x": "Xem phần mở đầu của bài trình chiếu ở chế độ tự học, có phễu chuyển động và lời dẫn. Đọc Giao việc như giao cho đồng nghiệp : thói quen quan trọng nhất để đi xuống phễu. Chọn ba thói quen trong chuyên đề Một ngày làm việc cùng AI để bắt đầu từ mai. Làm Thử thách 7 ngày cùng một đồng nghiệp.", "k": "page"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Vì sao đọc trang này", "u": "mot-ngay.html#vi-sao-doc-trang-nay", "x": "Bạn đã biết nhiều cách nhờ. Nhưng sáng mai, giữa email, họp hành và tin nhắn của khách, nhờ bạn ấy vào lúc nào? Trang này theo chân bốn đồng nghiệp ở Công ty CP Phân phối Thiết bị Văn phòng Sao Mai qua một ngày bình thường: năm phút trước cuộc họp, mười phút sau khi gặp khách, một câu hỏi lại trước khi bấm gửi. Rồi bạn chọn 2–3 thói quen để bắt đầu từ mai. Góc nhìn Andrej Karpathy ví khoảng cách hiểu biết về AI như m", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Nhịp chung của một ngày", "u": "mot-ngay.html#nhip-chung-cua-mot-ngay", "x": "Nghề nào cũng có chung một nhịp. Nhìn bảng, rồi tìm khe trống trong ngày của bạn. Lúc Việc thường làm Nhờ bạn ấy thế nào Đầu ngày Đọc email, xếp việc Dán danh sách việc, nhờ xếp thứ tự Trước họp Đọc tài liệu Nhờ tóm tắt, đoán trước 3 câu hỏi khó Giữa buổi Soạn văn bản, số liệu Nói rõ 3 điều: muốn gì, công sức, kiểm tra thế nào Sau họp Biên bản, chia việc Dán ghi chú vội, nhờ tách ai làm gì, hạn nào Buổi chiều Trả lời", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "⚖️ Một ngày của người làm pháp lý", "u": "mot-ngay.html#mot-ngay-cua-nguoi-lam-phap-ly", "x": "Anh Minh, chuyên viên pháp chế của Sao Mai, sống giữa hợp đồng, công văn và những câu hỏi \"cái này ký được không anh?\".", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "8:15 · Lọc văn bản mới", "u": "mot-ngay.html#8-15-loc-van-ban-moi", "x": "Văn bản pháp luật là dữ liệu 🟢. Anh Minh nhờ bạn ấy lọc trước, cái nào đụng tới công ty mới đọc kỹ.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "9:00 · Rà phụ lục: nói rõ 3 điều", "u": "mot-ngay.html#9-00-ra-phu-luc-noi-ro-3-dieu", "x": "Mười giờ anh họp với nhà cung cấp kệ kho về phụ lục gia hạn. Anh dành hai phút nói rõ ba điều.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "9:40 · Dám hỏi lại: \"căn cứ đâu?\"", "u": "mot-ngay.html#9-40-dam-hoi-lai-can-cu-dau", "x": "Bạn ấy ghi một điều khoản phạt là \"trái quy định của pháp luật\". Nghe rất chắc, nên anh Minh hỏi lại. Bạn ấy thừa nhận chưa chắc số điều. Năm phút tra văn bản gốc, anh vào họp với một căn cứ đứng vững. AI rút ngắn việc tìm, còn xác nhận là việc của người làm nghề.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "14:30 · Trả lời đồng nghiệp bằng lời thường", "u": "mot-ngay.html#14-30-tra-loi-dong-nghiep-bang-loi-thuong", "x": "Chị Thu Hà bên Kinh doanh nhắn: khách đòi thêm điều khoản \"bồi thường mọi thiệt hại\", đồng ý được không anh?", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "💰 Một ngày của người làm kế toán – tài chính", "u": "mot-ngay.html#mot-ngay-cua-nguoi-lam-ke-toan-tai-chinh", "x": "Chị Ngọc là kế toán tổng hợp, tuần này chốt số liệu tháng 9.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "8:30 · Công thức cho bảng công nợ", "u": "mot-ngay.html#8-30-cong-thuc-cho-bang-cong-no", "x": "Viết công thức thì không cần biết khách nào nợ bao nhiêu, nên chị Ngọc chỉ mô tả các cột.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "10:30 · Thuyết minh biến động: nói rõ 3 điều", "u": "mot-ngay.html#10-30-thuyet-minh-bien-dong-noi-ro-3-dieu", "x": "Kế toán trưởng cần thuyết minh chi phí tháng 9 trước trưa. Bản nháp nội bộ nên chị chọn \"nhanh gọn\", nhưng không bỏ phần kiểm tra.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "13:30 · Dám hỏi lại: mỗi con số lấy ở đâu?", "u": "mot-ngay.html#13-30-dam-hoi-lai-moi-con-so-lay-o-dau", "x": "Bản thuyết minh đọc rất trôi. Chính vì trôi nên chị soi kỹ. Chị dùng hàm SUM đối chiếu ba số lớn nhất: hai số khớp, một số lệch vì làm tròn quá sớm. Ba phút, đổi lại chị yên tâm ký tên.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "16:30 · Quy chế thành hướng dẫn một trang", "u": "mot-ngay.html#16-30-quy-che-thanh-huong-dan-mot-trang", "x": "Cả tuần chị trả lời đi trả lời lại: \"hoàn ứng cần giấy tờ gì hả chị?\". Chiều nay, trả lời một lần cho xong.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "🤝 Một ngày của người làm kinh doanh – CSKH", "u": "mot-ngay.html#mot-ngay-cua-nguoi-lam-kinh-doanh-cskh", "x": "Chị Trần Thu Hà (bạn đã gặp ở Bậc 5 ) là trưởng nhóm Kinh doanh chi nhánh Hà Nội, nửa ngày ở văn phòng, nửa ngày trên đường.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "7:45 · Tập trước cuộc gặp bằng giọng nói", "u": "mot-ngay.html#7-45-tap-truoc-cuoc-gap-bang-giong-noi", "x": "Trên taxi tới gặp khách, chị Hà bật chế độ giọng nói và tập.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "14:00 · Báo giá: nói rõ 3 điều", "u": "mot-ngay.html#14-00-bao-gia-noi-ro-3-dieu", "x": "Chị thay tên trường bằng [Trường A], bỏ số điện thoại người liên hệ (đèn 🟡, 🔴 ở trang An toàn ).", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "15:30 · Dám hỏi lại: chỗ nào bạn tự thêm?", "u": "mot-ngay.html#15-30-dam-hoi-lai-cho-nao-ban-tu-them", "x": "Thư có câu \"miễn phí lắp đặt, bảo hành 36 tháng\". Nghe hấp dẫn, nhưng chị Hà chưa hề nhắc chuyện lắp đặt. Đúng là bạn ấy tự thêm. Một email hứa điều công ty không có còn tệ hơn email gửi chậm nửa tiếng.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "17:30 · Nhắn vào Project báo cáo tuần", "u": "mot-ngay.html#17-30-nhan-vao-project-bao-cao-tuan", "x": "Chị nhắn vài dòng vào cuộc trò chuyện của tuần trong Project \"Báo cáo tuần\". Thứ Sáu, một câu là có bản nháp. Chưa có Project? Một cuộc trò chuyện riêng cũng được.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "🏗️ Một ngày của người làm vận hành – xây dựng", "u": "mot-ngay.html#mot-ngay-cua-nguoi-lam-van-hanh-xay-dung", "x": "Anh Tuấn phụ trách vận hành kho, tháng này giám sát lắp kệ cho kho mới, ở công trường nhiều hơn ở bàn.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "7:30 · Chụp bảng trắng giao ca", "u": "mot-ngay.html#7-30-chup-bang-trang-giao-ca", "x": "Anh Tuấn chụp bảng trắng, cắt góc có số điện thoại, rồi gửi.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "10:00 · Hàng về thiếu: ảnh thành biên bản", "u": "mot-ngay.html#10-00-hang-ve-thieu-anh-thanh-bien-ban", "x": "Lô thanh giằng kệ về thiếu, vài thanh móp. Anh đếm tay, chụp ảnh, nhờ soạn biên bản để hai bên ký luôn.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "13:30 · Xếp lại lịch lắp đặt: nói rõ 3 điều", "u": "mot-ngay.html#13-30-xep-lai-lich-lap-dat-noi-ro-3-dieu", "x": "Hàng bổ sung sớm nhất thứ Năm mới về. Sếp cần biết có kịp ngày bàn giao không.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "15:30 · Dám hỏi lại: số an toàn lấy từ đâu?", "u": "mot-ngay.html#15-30-dam-hoi-lai-so-an-toan-lay-tu-dau", "x": "Bạn ấy gợi ý xếp hàng lên dãy kệ đã lắp, kèm câu \"mỗi tầng chịu khoảng 500 kg\". Chuyện an toàn, anh Tuấn không dùng số chưa rõ nguồn. Bạn ấy thừa nhận đó chỉ là \"mức thường gặp\". Anh chụp trang thông số trong hồ sơ kỹ thuật, nhờ bạn ấy đọc lại. AI đọc hộ, còn người ký tên vẫn là anh.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Buổi tối: cho chính mình", "u": "mot-ngay.html#buoi-toi-cho-chinh-minh", "x": "Hết giờ làm, bạn ấy vẫn ở đó. Buổi tối là chỗ tập nhờ tốt nhất, vì không đụng dữ liệu công ty. Bữa tối: chụp tủ lạnh, hỏi nấu gì trong 30 phút. Con học bài: nhờ bạn ấy làm gia sư gợi mở, không làm hộ. Cuối tuần: nhờ lên hai phương án đi chơi hợp ngân sách, giá vé thì tự kiểm lại. Học một kỹ năng: mười lăm phút mỗi tối, có bạn ấy kèm riêng.", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Chọn 3 thói quen để bắt đầu từ mai", "u": "mot-ngay.html#chon-3-thoi-quen-de-bat-dau-tu-mai", "x": "Đừng thử hết một lúc. Chọn 3 thói quen bạn thấy \"làm được ngay\": Đầu ngày: nhờ xếp thứ tự việc. Trước họp: nhờ đoán trước 3 câu hỏi khó. Giữa buổi: nói rõ 3 điều trước khi nhờ. Sau họp: dán ghi chú vội, nhờ chia việc. Chụp, nói thay vì gõ: chụp bảng trắng, tập trước cuộc gặp bằng giọng nói. Trước khi gửi: hỏi \"chỗ nào bạn tự thêm?\". Cuối tuần: ghi lại việc đã nhờ ba lần, để dạy thành Project. Viết ra giấy, dán cạnh m", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Dám hỏi lại", "u": "mot-ngay.html#dam-hoi-lai", "x": "Thói quen nhờ luôn đi kèm thói quen hỏi lại. Hỏi lại xuyên suốt cả ngày Trước khi dán: xanh, vàng hay đỏ? Che tên, số tiền, số điện thoại ( An toàn ). Khi bạn ấy dẫn luật, quy chuẩn, thông số: hỏi \"căn cứ đâu?\", rồi tự mở nguồn gốc. Khi có con số: số nào từ file, số nào tự tính? Tự đối chiếu 2–3 số lớn nhất. Trước khi gửi: hỏi \"chỗ nào bạn tự thêm?\", xoá lời hứa bạn không có quyền hứa. Việc pháp lý, tiền bạc, an toàn", "k": "topic"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Đi xa hơn", "u": "mot-ngay.html#di-xa-hon", "x": "Biến thói quen thành trợ lý. Việc nhờ đến lần thứ ba nên được dạy một lần trong Project hoặc Gem: Bậc 5 . Giao cả đầu việc. Khi một việc cần năm, sáu lần nhờ nối nhau, thử giao trọn cho AI agent ở Bậc 7 (cần gói trả phí). Theo Karpathy, độ lớn của việc giao cho AI là một nguyên nhân làm khoảng cách nới rộng. Luyện \"3 điều\" thành phản xạ với Giao việc như giao cho đồng nghiệp . Chưa biết bắt đầu từ đâu? Làm Thử thách ", "k": "topic"}, {"t": "Tải tài liệu thực hành", "h": "Tải tài liệu thực hành", "u": "tai-lieu.html", "x": "Mọi file trên trang này dùng để luyện tập . Bạn tải về, tải lên AI, làm theo bài, rồi đối chiếu với đáp án trong từng bài. Toàn bộ dữ liệu là hư cấu Công ty, con người, con số trong các file đều được dựng lên để luyện tập, xoay quanh công ty hư cấu Công ty CP Phân phối Thiết bị Văn phòng Sao Mai . Bạn cứ thoải mái tải lên bất kỳ công cụ AI nào, không lo lộ dữ liệu. Đáp án ở đâu? Đáp án nằm ngay trong từng bài, trong ", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Bài trình chiếu, bản để đọc offline", "u": "tai-lieu.html#bai-trinh-chieu-ban-de-doc-offline", "x": "Toàn bộ bài trình chiếu, mỗi trang một slide kèm lời dẫn và câu nhờ, gói trong một file PDF để đọc trên điện thoại, máy tính bảng hoặc in ra. Tải bài trình chiếu (.pdf) Muốn xem bản luôn mới nhất? Mở bản in trên web , hoặc xem bài ở chế độ tự học hay xem như phim .", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Bậc 1 và Bậc 4", "u": "tai-lieu.html#bac-1-va-bac-4", "x": "Không cần tải gì. Bậc 1 dùng tình huống email của chính bạn. Bậc 4 nói tiếp trong cùng cuộc trò chuyện với file của Bậc 3.", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Bậc 2 · Tài liệu dài và bẫy \"AI bịa\"", "u": "tai-lieu.html#bac-2-tai-lieu-dai-va-bay-ai-bia", "x": "Hợp đồng mua bán kệ kho dài vài trang kèm phụ lục. Bạn đóng vai bên mua, nhờ AI tóm tắt, tìm điểm bất lợi, và thử bắt bạn ấy \"đoán\". Dùng ở Bậc 2 . Tải hợp đồng mẫu (.docx)", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Bậc 3 · Excel lộn xộn thành sạch", "u": "tai-lieu.html#bac-3-excel-lon-xon-thanh-sach", "x": "Bảng chi phí tháng 9 khoảng 300 dòng, đủ kiểu lộn xộn: ngày gõ nhiều định dạng, tên nhà cung cấp viết mỗi lần một kiểu, có dòng trùng, ô trống, số tiền gõ dạng chữ. Nhiệm vụ: nhờ AI dọn sạch và tính tổng đúng. Dùng ở Bậc 3 . Tải bảng chi phí tháng 9 (.xlsx) Bảng công nợ 25 khách hàng, có sẵn ngày hoá đơn, số tiền, ngày đã trả. Hai cột cuối để trống cho bạn nhờ AI viết công thức tính số ngày quá hạn và tình trạng. Tải", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Bậc 5 · Dạy bạn ấy một lần, nhờ mãi mãi", "u": "tai-lieu.html#bac-5-day-ban-ay-mot-lan-nho-mai-mai", "x": "Bộ tài liệu để dựng một trợ lý viết báo cáo tuần trong Project hoặc Gem. Dùng ở Bậc 5 . Tải trọn bộ một lần cho tiện: Tải trọn bộ Bậc 5 (.zip) Hoặc tải từng file: Mẫu báo cáo tuần còn trống, có sẵn các mục: tóm tắt tuần, kết quả chính, việc trễ hạn, rủi ro và đề xuất, kế hoạch tuần tới. Đây là \"khuôn\" để trợ lý viết theo. Tải mẫu báo cáo tuần (.docx) Hai báo cáo tuần cũ của phòng Kinh doanh chi nhánh Hà Nội, để trợ l", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Bậc 6 · Thiếu công cụ? Nhờ bạn ấy làm luôn", "u": "tai-lieu.html#bac-6-thieu-cong-cu-nho-ban-ay-lam-luon", "x": "Một ứng dụng mẫu theo dõi tiến độ công việc được làm hoàn toàn bằng cách nói chuyện với AI: đổi màu theo hạn, lọc theo người phụ trách, tính phần trăm tiến độ, xuất file CSV. Mở bằng trình duyệt để xem thành phẩm trông thế nào trước khi tự làm. Dùng ở Bậc 6 . Tải ứng dụng mẫu theo dõi tiến độ (.html)", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Bậc 7 · Giao cả đầu việc", "u": "tai-lieu.html#bac-7-giao-ca-dau-viec", "x": "Số liệu tháng 9 của 5 chi nhánh, mỗi nơi gửi một kiểu: Excel đúng mẫu, Excel tính bằng đơn vị khác, Word viết thành đoạn văn, CSV xuất từ phần mềm kế toán, và một file có sheet nháp cũ. Nhiệm vụ: giao cho agent gom thành báo cáo quản trị tháng. Dùng ở Bậc 7 . Tải báo cáo tháng 9 của 5 chi nhánh (.zip) Bậc 7 cần agent Bài này làm trọn vẹn nhất với agent như Claude Cowork (cần gói trả phí). Chưa có gói trả phí, bạn vẫn", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Để in", "u": "tai-lieu.html#de-in", "x": "Thẻ 7 bậc: tích từng bậc bạn đã làm được, ghi việc bạn sẽ nhờ và việc táo bạo nhất muốn thử. Tải thẻ 7 bậc (.html) Chứng nhận \"level up\" để tự thưởng cho mình (hoặc trao cho đồng nghiệp) sau khi đi hết hành trình. Tải chứng nhận level up (.html) In file .html thế nào? Mở file bằng trình duyệt (Chrome, Edge, Safari), bấm Ctrl + P (trên Mac là Cmd + P ). Chọn máy in, hoặc chọn \"Lưu dưới dạng PDF\" (Save as PDF) để giữ b", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Mở và giải nén file", "u": "tai-lieu.html#mo-va-giai-nen-file", "x": "", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "File .zip trên Windows", "u": "tai-lieu.html#file-zip-tren-windows", "x": "Mở thư mục Downloads (Tải xuống), tìm file .zip vừa tải. Bấm chuột phải vào file, chọn Extract All… (Giải nén tất cả). Chọn nơi lưu, bấm Extract (Giải nén). Một thư mục mới chứa các file sẽ hiện ra. Đừng làm việc ngay trong file .zip Windows cho bạn bấm đúp mở file .zip như một thư mục, nhưng file mở từ đó thường không lưu được hoặc khó tải lên AI. Hãy giải nén ra trước.", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "File .zip trên Mac", "u": "tai-lieu.html#file-zip-tren-mac", "x": "Bấm đúp vào file .zip trong Finder. Mac tự giải nén ra một thư mục cùng tên, ngay cạnh file .zip.", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "File .zip trên điện thoại", "u": "tai-lieu.html#file-zip-tren-dien-thoai", "x": "Trên iPhone, mở app Tệp (Files) và chạm vào file .zip để giải nén. Trên Android, dùng app quản lý tệp có sẵn hoặc Files by Google, chọn file rồi chọn giải nén. Tên nút có thể khác tuỳ máy.", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Các file khác", "u": "tai-lieu.html#cac-file-khac", "x": ".docx, .xlsx: mở bằng Word, Excel, hoặc tải lên Google Docs, Google Sheets. Bạn cũng có thể tải thẳng lên AI mà không cần mở. .txt: mở bằng Notepad (Windows) hoặc TextEdit (Mac). .html: bấm đúp để mở bằng trình duyệt, không cần mạng, không cần cài gì.", "k": "page"}, {"t": "Tải tài liệu thực hành", "h": "Tự kiểm tra", "u": "tai-lieu.html#tu-kiem-tra", "x": "Mình đã tải được file của bậc mình đang học Mình đã giải nén được file .zip (nếu có) Mình đã tự làm bài trước khi mở hộp \"Xem đáp án\" Mình đã in hoặc lưu thẻ 7 bậc", "k": "page"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Thử thách 7 ngày, 7 lần nhờ", "u": "thu-thach-7-ngay.html", "x": "Đọc về AI thì dễ quên. Nhờ AI làm thật thì nhớ lâu. Thử thách này giúp bạn biến những gì đã đọc thành thói quen , chỉ với khoảng 15 phút mỗi ngày. Góc nhìn Mỗi lần nhờ một việc mới là một lần bạn mở rộng ranh giới \"việc này AI làm được không nhỉ?\". Sau 7 ngày, câu hỏi đó sẽ đổi thành \"việc này nhờ bạn ấy thế nào nhỉ?\".", "k": "page"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Luật chơi", "u": "thu-thach-7-ngay.html#luat-choi", "x": "Mỗi ngày nhờ người bạn AI một việc bạn chưa từng nhờ . Rồi khoe lại : vào nhóm Zalo, kể cho đồng nghiệp, hoặc ghi vào sổ của riêng bạn. Khoe 3 ý: nhờ gì · mở lời thế nào · kết quả ra sao. Gợi ý từng ngày chỉ là gợi ý. Tự nghĩ ra việc lạ hơn thì càng vui. Lỡ một ngày? Làm bù hôm sau, không sao cả. Không cần đúng thứ tự. Việc dùng tài liệu công ty thì nhớ đèn giao thông dữ liệu : che tên và số trước khi đưa vào. Mẫu để", "k": "page"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Ngày 1 · \"Bạn giúp được mình việc gì?\"", "u": "thu-thach-7-ngay.html#ngay-1-ban-giup-duoc-minh-viec-gi", "x": "Hôm nay bạn không cần nghĩ ra việc gì cả, để bạn ấy gợi ý. Kể về công việc thật của bạn càng cụ thể, danh sách càng sát. Rồi chọn một việc trong danh sách và làm thử luôn. Bạn sẽ thấy Một danh sách 10 việc sát với nghề của bạn, có vài việc bạn chưa từng nghĩ tới. Việc bạn chọn thử cho ra kết quả dùng được, hoặc ít nhất là một bản nháp tốt để sửa tiếp. Nếu danh sách còn chung chung, kể thêm về công việc của bạn và nhờ", "k": "page"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Ngày 2 · Nhờ góp ý thẳng", "u": "thu-thach-7-ngay.html#ngay-2-nho-gop-y-thang", "x": "Chọn một email hoặc văn bản bạn sắp gửi thật . Thay vì nhờ viết, hôm nay nhờ bạn ấy chê . Người bạn tốt là người dám nói thật. Bạn sẽ thấy Ba góp ý cụ thể, có chỉ đúng câu nào, vì sao. Bản viết lại rõ hơn, đúng giọng hơn. Bạn không nhất thiết đồng ý hết: chỗ nào không hợp thì nói lại với bạn ấy, như với một đồng nghiệp. Đã làm ngày 2", "k": "page"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Ngày 3 · Chụp ảnh đống lộn xộn", "u": "thu-thach-7-ngay.html#ngay-3-chup-anh-dong-lon-xon", "x": "Mở app AI trên điện thoại, chụp một thứ lộn xộn quanh bạn: xấp hoá đơn, bảng trắng sau cuộc họp, tủ lạnh, góc bàn làm việc, tờ ghi chú viết tay. Rồi hỏi bạn ấy giúp được gì. Bạn sẽ thấy Bạn ấy đọc được chữ và hiểu được nội dung trong ảnh: hoá đơn thành bảng chi tiêu, bảng trắng thành biên bản và danh sách việc cần làm, tủ lạnh thành thực đơn 3 bữa. Kiểm tra lại vài con số hoặc chữ đọc từ ảnh, vì ảnh mờ dễ bị đọc sai.", "k": "page"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Ngày 4 · Nói chuyện bằng giọng nói 5 phút", "u": "thu-thach-7-ngay.html#ngay-4-noi-chuyen-bang-giong-noi-5-phut", "x": "Hôm nay không gõ. Mở app ChatGPT, Gemini hoặc Claude trên điện thoại, bấm biểu tượng sóng âm hoặc micro để vào chế độ giọng nói. Nói chuyện 5 phút về một điều bạn đang băn khoăn: một quyết định khó trong công việc, kế hoạch cuối tuần, hay một cuộc nói chuyện sắp tới mà bạn ngại. Câu mở đầu, bạn nói thành lời: Bạn sẽ thấy Một cuộc trò chuyện thật: bạn ấy trả lời ngay, bạn có thể ngắt lời, nói lan man, đổi ý. Sau 5 phú", "k": "page"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Ngày 5 · Tạo Project hoặc Gem đầu tiên", "u": "thu-thach-7-ngay.html#ngay-5-tao-project-hoac-gem-dau-tien", "x": "Hôm nay bạn \"dạy bạn ấy một lần, nhờ mãi mãi\". Chọn một việc bạn làm đi làm lại: báo cáo tuần, trả lời một loại email, soạn một loại văn bản. Thay vì tự viết hướng dẫn, để bạn ấy phỏng vấn bạn rồi tự viết. Sau đó: Tạo Project (ChatGPT, Claude) hoặc Gem (Gemini). Dán phần hướng dẫn bạn ấy vừa viết vào ô hướng dẫn. Tải lên file mẫu hoặc văn bản cũ đã che thông tin (nếu có). Mở một cuộc trò chuyện trong Project và thử m", "k": "page"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Ngày 6 · Nhờ làm một công cụ hoặc trò chơi nhỏ", "u": "thu-thach-7-ngay.html#ngay-6-nho-lam-mot-cong-cu-hoac-tro-choi-nho", "x": "Thiếu công cụ? Nhờ bạn ấy làm luôn. Dùng Claude (Artifact) hoặc ChatGPT (Canvas). Làm cho bạn, cho con, hay cho cả nhà đều được: bảng chi tiêu, lịch tập, máy tính báo giá có VAT, trò chơi ôn bảng cửu chương. Rồi cứ nói chuyện tiếp để sửa: \"thêm âm thanh khi trả lời đúng\", \"nút này bấm không ăn, sửa giúp mình\", \"đổi màu vui hơn\". Bạn sẽ thấy Một công cụ chạy được ngay bên cạnh khung chat, bấm thử được. Lần đầu có thể ", "k": "page"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Ngày 7 · Việc táo bạo nhất", "u": "thu-thach-7-ngay.html#ngay-7-viec-tao-bao-nhat", "x": "Lấy thẻ 7 bậc ra (hoặc nghĩ lại), làm đúng việc táo bạo nhất bạn từng nghĩ \"chắc AI không làm được đâu\". Làm chưa được thì cũng không sao: nói chuyện tiếp, hỏi thẳng bạn ấy cách nhờ. Bạn sẽ thấy Hoặc là bạn ấy làm được, và bạn bất ngờ. Hoặc là bạn ấy chia việc lớn thành các bước nhỏ, trong đó có vài bước bạn làm được ngay hôm nay. Cả hai đều là thắng. Đã làm ngày 7", "k": "page"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Nhìn lại 7 ngày", "u": "thu-thach-7-ngay.html#nhin-lai-7-ngay", "x": "Gom lại các ghi chú (hoặc tin nhắn đã khoe) của 7 ngày, rồi nhờ bạn ấy giúp bạn rút ra bài học. Tự thưởng cho mình Đi hết 7 bậc và 7 ngày rồi? In một tấm chứng nhận level up cho chính mình. Rồi rủ một đồng nghiệp bắt đầu thử thách, vì dạy người khác là cách học nhanh nhất.", "k": "page"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Khi nào dùng", "u": "tra-cuu-co-nguon.html#khi-nao-dung", "x": "Kiến thức của người bạn AI dừng ở một thời điểm, gọi là mốc kiến thức . Hỏi chuyện hay thay đổi như luật, giá cả, tin doanh nghiệp, bạn ấy vẫn trả lời trôi chảy bằng \"trí nhớ\", và trí nhớ đó có thể đã cũ. Bật tìm kiếm web , bạn ấy đọc các trang trên mạng rồi mới trả lời, kèm link. Nhớ một câu: không có link là đang trả lời từ trí nhớ . Không chắc thì hỏi thẳng: \"câu này bạn nhớ hay bạn vừa tìm?\" Bạn cần Nên dùng Kiến", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Cách nhờ", "u": "tra-cuu-co-nguon.html#cach-nho", "x": "Boris Cherny, người tạo ra Claude Code, khuyên nói chuyện với AI như với đồng nghiệp và nói rõ 3 điều : Bạn muốn gì: câu hỏi cụ thể, dùng vào việc gì, cho ai đọc. Bỏ bao nhiêu công sức: tra nhanh vài nguồn, hay tìm thật kỹ. Kiểm tra thế nào: mỗi ý có link và ngày, ưu tiên nguồn chính thức. Rồi thêm: thiếu gì thì hỏi mình .", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Làm thật", "u": "tra-cuu-co-nguon.html#lam-that", "x": "", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Tình huống 1 · Văn bản pháp luật còn hiệu lực không?", "u": "tra-cuu-co-nguon.html#tinh-huong-1-van-ban-phap-luat-con-hieu-luc-khong", "x": "Ai cũng từng trích một thông tư rồi mới biết nó đã bị thay thế. Cứ nhờ tìm, nhưng bắt buộc tự mở nguồn ra xem . Bạn sẽ thấy Câu trả lời kèm link, nhiều khi dẫn tới thuvienphapluat.vn, trang tư nhân phổ biến, tiện tra cứu. Khi cần chắc chắn, tự mở vbpl.vn hoặc Công báo, gõ số hiệu, đối chiếu ngày hiệu lực và văn bản sửa đổi, thay thế. Địa chỉ trang có thể đổi, khi đó tìm theo tên cơ quan.", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Tình huống 2 · So sánh 3–5 nhà cung cấp", "u": "tra-cuu-co-nguon.html#tinh-huong-2-so-sanh-35-nha-cung-cap", "x": "Thay vì mở mười tab, nhờ bạn ấy lập bảng, rồi bạn chỉ kiểm những ô quan trọng. Bạn sẽ thấy Một bảng có link và vài ô \"không công bố\", vì giá thường phải xin báo giá. Ô đó là dấu hiệu tốt: bạn ấy đang trung thực. Bảng là điểm khởi đầu, chưa phải kết luận.", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Tình huống 3 · Tìm hiểu đối tác trước cuộc gặp", "u": "tra-cuu-co-nguon.html#tinh-huong-3-tim-hieu-doi-tac-truoc-cuoc-gap", "x": "Chỉ tìm thông tin công khai về doanh nghiệp , đừng nhờ bạn ấy đào đời tư một cá nhân. Bạn sẽ thấy Nửa trang có link, kèm 5 câu hỏi. Cẩn thận nhất là trùng tên : tin công ty này có thể bị ghép sang công ty kia. Đối chiếu mã số thuế hoặc địa chỉ trước khi nhắc chi tiết nào.", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Tình huống 4 · Câu hỏi lớn: giao cho nghiên cứu sâu", "u": "tra-cuu-co-nguon.html#tinh-huong-4-cau-hoi-lon-giao-cho-nghien-cuu-sau", "x": "\"Công ty 200 người nên chọn phần mềm kế toán nào?\" không trả lời được bằng năm cái link. Hãy dùng nghiên cứu sâu : Deep Research ở ChatGPT, Gemini; Research ở Claude (tên gọi có thể thay đổi); Perplexity cũng có chế độ tìm sâu. Bạn ấy tự đọc hàng chục nguồn rồi viết báo cáo dài có trích dẫn. Theo Andrej Karpathy, khoảng cách giữa người dùng AI đến một phần từ độ lớn của việc mình dám giao; đây là một bước nhỏ đi về p", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Dám hỏi lại", "u": "tra-cuu-co-nguon.html#dam-hoi-lai", "x": "Có link chưa chắc đã đúng. Coi chừng nguồn không tồn tại hoặc không hề nói điều đó; trích sai, lệch năm ; blog đứng ngang trang chính thức . Kiểm chứng trong 5 phút Mở ít nhất 2 nguồn quan trọng nhất , nhấn Ctrl + F tìm đúng câu được trích. Xem ngày đăng; văn bản pháp luật thì xem ngày hiệu lực trên nguồn chính thức. Con số quan trọng cần 2 nguồn độc lập, trong đó 1 nguồn chính thức. Link chết hoặc không thấy thông t", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Biến thể theo ngành", "u": "tra-cuu-co-nguon.html#bien-the-theo-nganh", "x": "", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "⚖️ Pháp lý", "u": "tra-cuu-co-nguon.html#phap-ly", "x": "Lập \"bản đồ văn bản\" đang áp dụng để không trích nhầm văn bản hết hiệu lực.", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "💰 Kế toán – Tài chính", "u": "tra-cuu-co-nguon.html#ke-toan-tai-chinh", "x": "Thay đổi về thuế, hoá đơn đều có văn bản gốc; link phải dẫn về đó.", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "🤝 Kinh doanh – CSKH", "u": "tra-cuu-co-nguon.html#kinh-doanh-cskh", "x": "Thông tin đối thủ cũ đi rất nhanh, nên luôn đòi ngày.", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "🏗️ Vận hành – Xây dựng", "u": "tra-cuu-co-nguon.html#van-hanh-xay-dung", "x": "Giá vật liệu và quy chuẩn đều có nguồn chính thức, đòi đúng kỳ, đúng địa phương.", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Còn việc gì giống vậy?", "u": "tra-cuu-co-nguon.html#con-viec-gi-giong-vay", "x": "💼 Công việc Tra mức xử phạt hiện hành trước khi tư vấn So 3 khoá đào tạo cho phòng Tìm hiểu khách trước khi chào hàng Mẫu tờ khai mới nhất của cơ quan nhà nước 🏡 Đời sống So 3 gói bảo hiểm sức khoẻ Thủ tục làm hộ chiếu hiện hành Quy định hành lý trước chuyến bay Một tin \"nghe nói\" bắt nguồn từ đâu Câu trả lời có thể đã thay đổi , hoặc sẽ dẫn tới một quyết định? Nhờ tìm có nguồn, rồi tự mở ít nhất hai link.", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Tự kiểm tra", "u": "tra-cuu-co-nguon.html#tu-kiem-tra", "x": "Phân biệt được trả lời từ trí nhớ và trả lời có tìm kiếm. Đã dùng câu mẫu TC1 cho một câu hỏi thật. Đã tự kiểm tra hiệu lực một văn bản trên vbpl.vn hoặc Công báo. Đã mở 2 link và tìm thấy đúng câu được trích.", "k": "topic"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Đi xa hơn", "u": "tra-cuu-co-nguon.html#di-xa-hon", "x": "Hỏi chéo hai công cụ. Chỗ hai bên nói khác nhau là chỗ cần tự đọc, như ở Bậc 2 . Biến tra cứu định kỳ thành trợ lý. Project hoặc Gem dặn sẵn \"luôn tìm, kèm link và ngày\", như ở Bậc 5 . Đề bài nghiên cứu càng rõ, báo cáo càng dùng được. Cách viết ở Giao việc như giao cho đồng nghiệp . Điều gõ vào ô tìm kiếm cũng là dữ liệu. Xem An toàn trước khi gõ tên khách.", "k": "topic"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Từ điển AI cho dân văn phòng", "u": "tu-dien.html", "x": "Nghe ai đó nói \"token\", \"agent\", \"MCP\" mà thấy mình như người ngoài cuộc? Không sao cả. Trang này giải thích từng từ bằng lời thường, mỗi từ vài câu. Bạn không cần thuộc hết, chỉ cần biết chỗ để tra. Tra nhanh Bấm Ctrl + F (trên Mac là Cmd + F ) rồi gõ từ bạn cần tìm.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Cơ bản", "u": "tu-dien.html#co-ban", "x": "", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "AI (trí tuệ nhân tạo)", "u": "tu-dien.html#ai-tri-tue-nhan-tao", "x": "Phần mềm làm được những việc trước đây cần trí óc con người: hiểu câu hỏi, viết văn bản, đọc tài liệu, nhìn ảnh. Trên trang này, \"AI\" chủ yếu là các trợ lý trò chuyện như ChatGPT, Claude, Gemini.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Mô hình ngôn ngữ lớn (LLM)", "u": "tu-dien.html#mo-hinh-ngon-ngu-lon-llm", "x": "\"Bộ não\" phía sau các trợ lý AI, được huấn luyện trên một lượng chữ khổng lồ để hiểu và tạo ra ngôn ngữ. Mỗi công cụ có nhiều mô hình với tên và phiên bản khác nhau; bản mới thường giỏi hơn bản cũ.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Chatbot", "u": "tu-dien.html#chatbot", "x": "Chương trình bạn trò chuyện bằng cách gõ hoặc nói. Chatbot ngày xưa chỉ trả lời theo kịch bản cài sẵn; chatbot dùng mô hình ngôn ngữ lớn thì hiểu được câu hỏi tự nhiên và trả lời linh hoạt.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Prompt (câu nhờ)", "u": "tu-dien.html#prompt-cau-nho", "x": "Những gì bạn gõ hoặc nói với AI. Trang này gọi vui là \"câu nhờ\" hoặc \"câu mở lời\". Prompt tốt không cần công thức phức tạp, chỉ cần kể đủ như kể cho một người bạn mới vào nghề.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Ngữ cảnh (context)", "u": "tu-dien.html#ngu-canh-context", "x": "Mọi thông tin bạn ấy đang có trong cuộc trò chuyện: lời bạn kể, tài liệu bạn đưa, các câu trả lời trước đó. Ngữ cảnh càng đủ, kết quả càng đúng ý. Đây là lý do Bậc 1 bảo bạn \"kể đủ bối cảnh\".", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Cửa sổ ngữ cảnh (context window)", "u": "tu-dien.html#cua-so-ngu-canh-context-window", "x": "Lượng chữ tối đa bạn ấy \"nhìn thấy\" cùng lúc trong một cuộc trò chuyện. Khi cuộc trò chuyện quá dài, bạn ấy có thể quên hoặc lẫn phần đầu. Lúc đó, nhờ bạn ấy tóm tắt rồi mở cuộc trò chuyện mới kèm bản tóm tắt.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Token", "u": "tu-dien.html#token", "x": "Đơn vị nhỏ mà AI dùng để đọc và đếm chữ, thường là một phần của một từ. Giới hạn độ dài và giới hạn sử dụng thường tính bằng token. Bạn không cần đếm, chỉ cần biết: tài liệu càng dài thì càng tốn nhiều token.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "\"Bịa\" (hallucination, ảo giác)", "u": "tu-dien.html#bia-hallucination-ao-giac", "x": "Khi AI đưa ra thông tin nghe rất hợp lý nhưng sai, ví dụ trích một điều khoản không tồn tại. Lý do là bạn ấy dự đoán chữ tiếp theo chứ không tra cứu sự thật. Cách xử lý: hỏi \"căn cứ đâu?\" và tự kiểm 1–2 điểm. Xem Dùng AI an toàn .", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Đa phương thức (multimodal)", "u": "tu-dien.html#da-phuong-thuc-multimodal", "x": "Khả năng xử lý nhiều loại thông tin, không chỉ chữ: ảnh, giọng nói, file PDF, bảng tính, đôi khi cả video. Nhờ đó bạn có thể chụp ảnh một tờ hoá đơn và hỏi \"bạn giúp được gì với cái này?\".", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Mốc kiến thức (knowledge cutoff)", "u": "tu-dien.html#moc-kien-thuc-knowledge-cutoff", "x": "Thời điểm mà kiến thức \"học sẵn\" của mô hình dừng lại. Chuyện xảy ra sau mốc này, bạn ấy không biết, trừ khi được tìm kiếm trên mạng hoặc bạn đưa tài liệu vào. Đặc biệt cần nhớ với luật, thuế, giá cả vừa thay đổi.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Cách dùng", "u": "tu-dien.html#cach-dung", "x": "", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Cuộc trò chuyện mới (new chat)", "u": "tu-dien.html#cuoc-tro-chuyen-moi-new-chat", "x": "Mỗi cuộc trò chuyện mới là một trang giấy trắng: bạn ấy không nhớ những gì bạn nói ở cuộc khác (trừ khi bật bộ nhớ hoặc dùng Project). Việc mới thì mở chat mới; việc đang dở thì nói tiếp trong cùng cuộc, như ở Bậc 4 .", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Đóng vai (role)", "u": "tu-dien.html#dong-vai-role", "x": "Nhờ bạn ấy nhập vai một người cụ thể: \"bạn là kế toán trưởng 15 năm kinh nghiệm\", \"bạn là ông khách khó tính\". Đóng vai giúp kết quả đúng giọng và đúng góc nhìn, và là cách hay để nhờ phản biện.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Hỏi thẳng bạn ấy", "u": "tu-dien.html#hoi-thang-ban-ay", "x": "Cách nhờ cốt lõi của trang này: khi không biết nhờ thế nào, hỏi thẳng \"bạn cần biết gì để làm tốt việc này? Hỏi mình từng câu một nhé.\" Bạn ấy sẽ hỏi lại như một đồng nghiệp tận tâm.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Giao việc như giao cho đồng nghiệp", "u": "tu-dien.html#giao-viec-nhu-giao-cho-dong-nghiep", "x": "Cách giao việc cho AI mà Boris Cherny (người tạo ra Claude Code) khuyên: không cần câu lệnh dài, chỉ cần nói rõ ba điều: muốn gì , bỏ bao nhiêu công sức , kiểm tra thế nào . Ví dụ: \"Mình cần báo cáo chi phí tháng 9 cho Giám đốc. Cứ làm kỹ. Xong thì đối chiếu tổng với file gốc, báo mình đã kiểm gì.\" Xem trang riêng .", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Công sức (effort)", "u": "tu-dien.html#cong-suc-effort", "x": "Mức độ bạn cho phép AI đầu tư vào một việc: làm nhanh gọn, hay suy nghĩ lâu, thử nhiều hướng. Nói thẳng trong câu nhờ (\"cứ làm kỹ, không cần vội\"), hoặc dùng chế độ suy nghĩ nếu công cụ có. \"Dùng nhiều token\" là cách nói của dân công nghệ cho ý \"cứ làm kỹ\".", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Phễu khoảng cách", "u": "tu-dien.html#pheu-khoang-cach", "x": "Hình ảnh Andrej Karpathy dùng (10/2026) để tả khoảng cách hiểu biết về AI: khoảng 6 tỷ người gần như chưa dùng, 1–2 tỷ dùng thỉnh thoảng, khoảng 20 triệu dùng bản mạnh nhất cho việc chuyên môn, khoảng 5.000 người dùng hệ thống nội bộ ở các phòng lab. Khoảng cách đang nới rộng. Xem Khoảng cách AI .", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Năng lực không đều (răng cưa)", "u": "tu-dien.html#nang-luc-khong-deu-rang-cua", "x": "AI giỏi lệch: cực mạnh ở việc kiểm chứng được như code, toán, số liệu có công thức, nhưng thất thường ở việc khác, ví dụ trả lời điều tài liệu không nói. Biết chỗ \"răng cưa lõm\" giúp bạn biết khi nào phải hỏi \"căn cứ đâu?\".", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Cho xem mẫu", "u": "tu-dien.html#cho-xem-mau", "x": "Đưa một văn bản cũ làm mẫu và nói \"viết theo đúng phong cách này\". Một mẫu tốt hiệu quả hơn mười dòng mô tả, nhất là khi bạn muốn giữ giọng văn của công ty.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Hướng dẫn tuỳ chỉnh (custom instructions)", "u": "tu-dien.html#huong-dan-tuy-chinh-custom-instructions", "x": "Phần cài đặt nơi bạn ghi sẵn vài điều về mình (\"mình là chuyên viên pháp chế, thích câu trả lời ngắn, dùng tiếng Việt\"). Bạn ấy áp dụng cho mọi cuộc trò chuyện, đỡ phải nhắc lại.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Bộ nhớ (memory)", "u": "tu-dien.html#bo-nho-memory", "x": "Tính năng để AI ghi nhớ một số điều về bạn qua nhiều cuộc trò chuyện. Tiện, nhưng hãy thỉnh thoảng xem bạn ấy đang nhớ gì và xoá những gì không muốn giữ. Tên và cách hoạt động khác nhau giữa các công cụ.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Chế độ suy nghĩ (reasoning, thinking)", "u": "tu-dien.html#che-do-suy-nghi-reasoning-thinking", "x": "Một số mô hình có chế độ \"nghĩ kỹ\" trước khi trả lời: chậm hơn, nhưng tốt hơn với bài toán nhiều bước, phân tích số liệu, rà soát logic. Việc đơn giản như viết email thì không cần.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Tính năng", "u": "tu-dien.html#tinh-nang", "x": "", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Upload file (tải file lên)", "u": "tu-dien.html#upload-file-tai-file-len", "x": "Đưa file PDF, Word, Excel, ảnh vào cuộc trò chuyện bằng nút ghim giấy hoặc dấu cộng. Bản miễn phí thường giới hạn số file hoặc dung lượng. Nhớ áp dụng đèn giao thông dữ liệu trước khi tải lên.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Project", "u": "tu-dien.html#project", "x": "\"Góc làm việc riêng\" trong ChatGPT và Claude, nơi bạn để sẵn hướng dẫn và tài liệu. Mọi cuộc trò chuyện trong Project đều biết sẵn bối cảnh đó. Đây là chìa khoá của Bậc 5 .", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Gem", "u": "tu-dien.html#gem", "x": "Tên gọi của trợ lý tuỳ chỉnh trong Gemini: bạn viết hướng dẫn một lần, đặt tên, rồi dùng lại mãi. Tương tự Project.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Custom GPT", "u": "tu-dien.html#custom-gpt", "x": "Phiên bản ChatGPT do bạn cài sẵn hướng dẫn và tài liệu, đặt tên riêng, có thể chia sẻ cho người khác dùng. Ví dụ \"Trợ lý báo cáo tuần phòng Kinh doanh\".", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Artifact", "u": "tu-dien.html#artifact", "x": "Khung riêng bên cạnh cuộc trò chuyện trong Claude, nơi hiện ra văn bản, slide, trang web hoặc ứng dụng chạy được ngay. Bạn nói tiếp để sửa, Artifact cập nhật theo. Xem Bậc 6 .", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Canvas", "u": "tu-dien.html#canvas", "x": "Khung làm việc chung trong ChatGPT (Gemini cũng có tính năng cùng tên) để cùng sửa văn bản hoặc code bên cạnh khung chat. Bạn có thể bôi đen một đoạn và nhờ sửa riêng đoạn đó.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Deep Research", "u": "tu-dien.html#deep-research", "x": "Chế độ nghiên cứu sâu: bạn ấy tự tìm và đọc nhiều nguồn trên mạng trong vài phút, rồi viết báo cáo dài có trích nguồn. Hợp cho tìm hiểu thị trường, tổng quan một chủ đề. Vẫn cần bấm vào nguồn để kiểm tra ý quan trọng.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Chế độ giọng nói (voice mode)", "u": "tu-dien.html#che-do-giong-noi-voice-mode", "x": "Nói chuyện với AI bằng giọng như gọi điện, bạn ấy trả lời bằng giọng nói. Hợp để động não khi đang đi đường, luyện tiếng Anh, tập thuyết trình.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Connector (kết nối ứng dụng)", "u": "tu-dien.html#connector-ket-noi-ung-dung", "x": "Cầu nối cho AI đọc dữ liệu ở ứng dụng khác như Gmail, Google Drive, lịch, đôi khi còn thao tác trên đó. Tiện, nhưng là cánh cửa vào dữ liệu thật: chỉ bật khi công ty cho phép và chỉ cấp quyền cần thiết.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Agent & tự động hoá", "u": "tu-dien.html#agent-tu-dong-hoa", "x": "", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Agent", "u": "tu-dien.html#agent", "x": "AI không chỉ trả lời mà còn tự làm nhiều bước để hoàn thành một đầu việc: lên kế hoạch, mở file, đọc, tính, tạo file mới, rồi báo lại. Bạn giao việc như giao cho một trợ lý, và vẫn là người duyệt cuối. Xem Bậc 7 .", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Claude Cowork", "u": "tu-dien.html#claude-cowork", "x": "AI agent trong ứng dụng Claude trên máy tính, làm việc trực tiếp với file và thư mục trên máy bạn. Cần gói trả phí.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "ChatGPT Agent", "u": "tu-dien.html#chatgpt-agent", "x": "Chế độ để ChatGPT tự thao tác nhiều bước, ví dụ tự mở trang web, tìm thông tin, tạo file. Thường cần gói trả phí, kiểm tra trang chính thức.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Claude Code", "u": "tu-dien.html#claude-code", "x": "Công cụ agent của Anthropic, chạy trong Terminal, ứng dụng desktop hoặc IDE. Giỏi viết code và tự động hoá việc trên máy như gộp nhiều file Excel. Cần gói trả phí; với trang này đây là phần tự chọn.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Codex", "u": "tu-dien.html#codex", "x": "Agent lập trình của OpenAI, viết và sửa code theo yêu cầu bằng lời. Dân văn phòng chỉ cần biết tên.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "MCP (Model Context Protocol)", "u": "tu-dien.html#mcp-model-context-protocol", "x": "Một chuẩn chung để kết nối AI với ứng dụng và dữ liệu khác . Hãy hình dung như cổng USB-C: một kiểu cắm, dùng được cho nhiều thiết bị. Nhờ MCP, một trợ lý AI có thể \"cắm\" vào lịch, kho tài liệu, phần mềm quản lý công việc. Bạn không cần tự làm gì với MCP, chỉ cần hiểu khi nghe nhắc.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Skill", "u": "tu-dien.html#skill", "x": "Một gói hướng dẫn đóng sẵn (có thể kèm file mẫu và các bước làm) cho một quy trình cụ thể, để AI lấy ra dùng lại đúng chuẩn mỗi khi gặp việc đó. Ví dụ một skill \"làm báo cáo tuần theo mẫu công ty\". Claude có tính năng tên là Skills; các công cụ khác có cách làm tương tự với tên khác.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "API", "u": "tu-dien.html#api", "x": "Cửa giao tiếp để phần mềm khác \"nói chuyện\" với AI bằng code, dùng khi lập trình viên muốn gắn AI vào ứng dụng của công ty. Trang này không dùng API, bạn chỉ cần biết tên.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Terminal", "u": "tu-dien.html#terminal", "x": "Cửa sổ gõ lệnh bằng chữ trên máy tính (trên Windows có PowerShell, Command Prompt hoặc Windows Terminal). Một số công cụ như Claude Code chạy ở đây. Trang này không bắt buộc bạn mở Terminal.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "An toàn", "u": "tu-dien.html#an-toan", "x": "", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Đèn giao thông dữ liệu", "u": "tu-dien.html#den-giao-thong-du-lieu", "x": "Quy tắc của trang này: 🟢 thông tin công khai thì kể thoải mái, 🟡 tài liệu nội bộ thì che tên và số trước, 🔴 thông tin khách hàng, tài khoản, mật khẩu thì không đưa. Xem Dùng AI an toàn .", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Ẩn danh hoá dữ liệu", "u": "tu-dien.html#an-danh-hoa-du-lieu", "x": "Thay tên người, tên công ty, số hợp đồng, số tiền bằng mã như [CÔNG TY A], [NGƯỜI 1] trước khi dán vào AI. Giữ bảng \"thật → mã\" trên máy để đổi ngược lại khi nhận kết quả.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Kiểm chứng", "u": "tu-dien.html#kiem-chung", "x": "Tự kiểm tra kết quả AI trước khi dùng: hỏi căn cứ, mở bản gốc đối chiếu, hỏi \"điểm nào bạn không chắc?\", so với nguồn khác, và để con người duyệt cuối. Đây là vế thứ hai của câu \"dám nhờ mọi thứ, dám hỏi lại mọi thứ\".", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Dùng dữ liệu để cải thiện mô hình", "u": "tu-dien.html#dung-du-lieu-de-cai-thien-mo-hinh", "x": "Tuỳ chọn cho phép nhà cung cấp dùng cuộc trò chuyện của bạn để huấn luyện mô hình sau này. Với tài khoản cá nhân, nên tắt trong phần cài đặt. Tắt rồi vẫn phải giữ đèn giao thông.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Prompt injection (lời nhờ cài cắm)", "u": "tu-dien.html#prompt-injection-loi-nho-cai-cam", "x": "Lời chỉ dẫn được giấu trong tài liệu, email hay trang web mà AI đọc, nhằm \"ra lệnh\" cho AI làm điều bạn không muốn, ví dụ gửi dữ liệu ra ngoài. Rủi ro này lớn hơn khi dùng agent được đọc email hay duyệt web. Cách phòng: chỉ cấp quyền cần thiết, duyệt kế hoạch trước khi agent làm, và không để agent tự gửi hay xoá thứ gì quan trọng.", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Gặp từ chưa có ở đây?", "u": "tu-dien.html#gap-tu-chua-co-o-day", "x": "", "k": "page"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Tự kiểm tra", "u": "tu-dien.html#tu-kiem-tra", "x": "Mình giải thích được cho đồng nghiệp: prompt, ngữ cảnh, cửa sổ ngữ cảnh Mình biết vì sao AI \"bịa\" và mốc kiến thức ảnh hưởng thế nào Mình phân biệt được Project, Gem, Custom GPT Mình phân biệt được chat thường và agent Mình hiểu prompt injection là gì và vì sao cần cẩn thận khi cho AI đọc email, trang web", "k": "page"}, {"t": "Trang chủ", "h": "Làm thật, thấy thật", "u": "index.html", "x": "Trang tự học AI cho dân văn phòng: phễu khoảng cách, giao việc như giao cho đồng nghiệp, 7 bậc từ email 30 giây đến giao cả đầu việc cho AI agent, và 7 chuyên đề thực chiến.", "k": "page"}, {"t": "Thư viện prompt", "h": "Thư viện prompt", "u": "thu-vien-prompt.html", "x": "Tất cả câu mở lời, lọc theo bài và ngành, copy hoặc mở thẳng trong ChatGPT, Claude.", "k": "page"}, {"t": "Video bằng code", "h": "Video bằng code", "u": "video-bang-code.html", "x": "Thủ thuật · Showcase Không camera · Không phần mềm dựng phim Video bằng code Một trong những thủ thuật \"wow\" nhất của năm: nói chuyện với Claude Code để nó viết ra cả một bộ phim . Trang này giải thích nguyên lý, cho bạn xem 3 bộ phim được viết hoàn toàn bằng code ngay tại đây, và hướng dẫn bạn tự làm video MP4 thật. Trong trang này Nguyên lý: video là một hàm của thời gian Xem tận mắt: 3 bộ phim viết bằng code Tự là", "k": "page"}, {"t": "Video bằng code", "h": "Nguyên lý: video là một hàm của thời gian", "u": "video-bang-code.html#nguyen-ly", "x": "Bình thường, làm video là quay, cắt, ghép, thêm chữ trong phần mềm dựng phim. Với cách làm \"video bằng code\", một video chỉ là một hàm của thời gian : ở giây thứ t , khung hình trông thế nào? Chữ nằm ở đâu, màu gì, to bao nhiêu? Viết điều đó ra bằng code, cho thời gian chạy từ 0 đến hết, là bạn có một bộ phim. Remotion là một thư viện mã nguồn mở cho phép viết video bằng React (một công nghệ làm web). Mỗi khung hình ", "k": "page"}, {"t": "Video bằng code", "h": "Xem tận mắt: 3 bộ phim viết bằng code", "u": "video-bang-code.html#xem-tan-mat", "x": "", "k": "page"}, {"t": "Video bằng code", "h": "Phim 1 · 7 bậc trong 60 giây", "u": "video-bang-code.html#phim-1", "x": "Phim mở màn cho buổi chia sẻ: bìa tạp chí, ba câu tinh thần, rồi lần lượt 7 bậc. 15 cảnh, 52 giây, phong cách tạp chí đen trắng với một màu nhấn đỏ son. Xem code của phim này", "k": "page"}, {"t": "Video bằng code", "h": "Phim 2 · Bẫy “AI bịa”", "u": "video-bang-code.html#phim-2", "x": "Minh hoạ cấp 2: hỏi AI một điều không có trong hợp đồng, AI \"đoán\" bằng một con số trông giống đáp án. Bài học: dám hỏi lại \"căn cứ đâu?\". Xem code của phim này", "k": "page"}, {"t": "Video bằng code", "h": "Phim 3 · Excel lộn xộn thành sạch", "u": "video-bang-code.html#phim-3", "x": "Minh hoạ cấp 3: bảng chi phí \"như đời thật\" được sắp xếp lại, dòng trùng biến mất, tên nhà cung cấp được chuẩn hoá, rồi thành biểu đồ. Tổng đúng: 384.070.000đ. Xem code của phim này Mẹo Nút Tải video ghi phim theo thời gian thực, nên hãy giữ tab mở cho tới khi phim chạy hết. Trình duyệt Chrome hoặc Edge trên máy tính cho kết quả ổn định nhất. Tuỳ trình duyệt, file sẽ là .webm hoặc .mp4 .", "k": "page"}, {"t": "Video bằng code", "h": "Tự làm video MP4 với Claude Code + Remotion", "u": "video-bang-code.html#tu-lam-mp4", "x": "Phần này dành cho bạn nào muốn thử \"thật\": làm video MP4 để đăng mạng xã hội, chiếu trong cuộc họp, hay làm video giới thiệu sản phẩm. Bạn cần một máy tính, gói Claude có Claude Code, và khoảng 30 phút cho lần đầu.", "k": "page"}, {"t": "Video bằng code", "h": "Bước 1 · Cài Node.js", "u": "video-bang-code.html#b1", "x": "Vào nodejs.org , tải bản LTS và cài như phần mềm bình thường. Đây là \"động cơ\" để chạy Remotion trên máy bạn.", "k": "page"}, {"t": "Video bằng code", "h": "Bước 2 · Tạo dự án video", "u": "video-bang-code.html#b2", "x": "Mở Terminal (hoặc PowerShell trên Windows) trong một thư mục trống, chạy lệnh dưới đây và làm theo hướng dẫn trên màn hình. Nếu được hỏi có muốn cài Agent Skills không, hãy chọn có. npx create-video@latest Copy", "k": "page"}, {"t": "Video bằng code", "h": "Bước 3 · Cài Agent Skills của Remotion cho Claude Code", "u": "video-bang-code.html#b3", "x": "Nếu chưa cài ở bước trên, chạy lệnh này trong thư mục dự án: npx skills add remotion-dev/skills Copy", "k": "page"}, {"t": "Video bằng code", "h": "Bước 4 · Nói chuyện với Claude Code", "u": "video-bang-code.html#b4", "x": "Mở Claude Code trong thư mục dự án và mô tả bộ phim bằng lời, như nói chuyện với một người dựng phim. Nhớ chiêu quen thuộc: để bạn ấy hỏi lại trước, rồi duyệt kịch bản từng cảnh trước khi viết code.", "k": "page"}, {"t": "Video bằng code", "h": "Bước 5 · Xem trước và xuất MP4", "u": "video-bang-code.html#b5", "x": "Xem trước trong Remotion Studio (một trang web chạy trên máy bạn, có thanh tua như phần mềm dựng phim): npm start Copy Lệnh trên tương đương npx remotion studio . Khi ưng ý, xuất ra file MP4. Thay TenComposition bằng tên phim mà Claude Code đã đặt (cứ hỏi thẳng bạn ấy: \"lệnh render phim này là gì?\"): npx remotion render src/index.ts TenComposition out/video.mp4 Copy Lưu ý về giấy phép Remotion miễn phí cho cá nhân, t", "k": "page"}, {"t": "Video bằng code", "h": "Không muốn cài gì? Dùng ngay Claude", "u": "video-bang-code.html#khong-cai-gi", "x": "Bạn vẫn có thể làm phim bằng code mà không cần cài gì: nhờ Claude (Artifacts) hoặc ChatGPT (Canvas) viết một trang HTML dùng canvas, giống hệt cách các phim trên trang này được làm. Đây cũng chính là cấp 6: tự tạo công cụ không cần code .", "k": "page"}, {"t": "Video bằng code", "h": "Nguồn tham khảo", "u": "video-bang-code.html#nguon", "x": "Remotion · Agent Skills (cách cài Skills cho Claude Code) GitHub · remotion-dev/skills Remotion · Prompting videos with coding agents Remotion · npx create-video Remotion · lệnh render Remotion · giấy phép Dám hỏi lại Lệnh và điều khoản của công cụ có thể thay đổi theo thời gian. Nếu một lệnh không chạy, hãy dán nguyên thông báo lỗi cho Claude Code và hỏi: \"Lỗi này là gì, mình cần làm gì tiếp?\"", "k": "page"}, {"t": "Trình chiếu", "h": "Bài trình chiếu: trình chiếu, tự học, xem như phim", "u": "trinh-chieu.html?mode=study", "x": "Bài chia sẻ đầy đủ dạng trình chiếu: phễu khoảng cách, giao việc như đồng nghiệp, 7 bậc. Có chế độ tự học (bài đọc, câu nhờ để copy) và xem như phim (tự chạy, có phụ đề).", "k": "page"}, {"t": "Thư viện prompt", "h": "Soạn công văn trả lời cơ quan nhà nước", "u": "thu-vien-prompt.html#p-_thu-vien-them-1", "x": "Công ty mình vừa nhận công văn của [cơ quan] về việc [nội dung], yêu cầu [giải trình / cung cấp hồ sơ] trước ngày [___]. Quan điểm của công ty là [___], hồ sơ mình có thể cung cấp gồm [___].\nSoạn giúp mình công văn trả lời đúng thể thức văn bản hành chính: số, ký hiệu, trích yếu, kính gửi, nội dung,", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Viết tờ trình xin duyệt", "u": "thu-vien-prompt.html#p-_thu-vien-them-2", "x": "Mình cần trình [Giám đốc / Hội đồng quản trị] duyệt [nội dung: mua thiết bị, chi phí phát sinh, thay đổi nhà cung cấp…]. Lý do: [___]. Chi phí dự kiến: [___]. Phương án thay thế mình đã cân nhắc: [___].\nViết giúp mình tờ trình gồm: sự cần thiết, nội dung đề xuất, chi phí và nguồn kinh phí, so sánh p", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Email nhắc thanh toán lần 2", "u": "thu-vien-prompt.html#p-_thu-vien-them-3", "x": "Khách hàng [tên công ty] đang quá hạn thanh toán [số] ngày với số tiền [___], hoá đơn số [___]. Mình đã nhắc lần 1 vào ngày [___] nhưng chưa thấy phản hồi. Đây là khách [lâu năm / mới], mình muốn giữ quan hệ.\nViết email nhắc lần 2: lịch sự nhưng cương quyết, nêu rõ số tiền, hạn mới, cách thanh toán,", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Từ chối khéo một đề nghị", "u": "thu-vien-prompt.html#p-_thu-vien-them-4", "x": "Mình cần từ chối [đề nghị: giảm giá thêm / nhận thêm việc / tham gia dự án] của [ai, quan hệ thế nào]. Lý do thật là [___], nhưng mình muốn giữ quan hệ tốt và nếu được thì đưa ra một phương án khác: [___].\nViết giúp mình [email / tin nhắn Zalo] ngắn, chân thành, không vòng vo, không nghe như lấy cớ.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Thông báo nội bộ dễ hiểu", "u": "thu-vien-prompt.html#p-_thu-vien-them-5", "x": "Mình cần thông báo tới [toàn công ty / cư dân / nhân viên ca đêm] về việc [nội dung thay đổi], áp dụng từ [ngày]. Người đọc cần biết: [điều gì thay đổi, ảnh hưởng gì đến họ, họ phải làm gì, hỏi ai].\nViết thông báo ngắn, dễ đọc trên điện thoại: tiêu đề rõ, gạch đầu dòng, không thuật ngữ khó. Thêm một", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Viết lại cho ngắn và rõ", "u": "thu-vien-prompt.html#p-_thu-vien-them-6", "x": "Đoạn văn dưới đây mình viết dài và rối quá. Viết lại giúp mình ngắn còn khoảng một nửa, giữ đủ ý chính, câu ngắn, dễ hiểu. Sau đó liệt kê những ý bạn đã bỏ để mình xem có cần giữ lại ý nào không.\n\n[Dán đoạn văn]", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Trả lời khiếu nại của khách", "u": "thu-vien-prompt.html#p-_thu-vien-them-7", "x": "Khách hàng [tên hoặc mô tả] khiếu nại về [vấn đề]. Sự thật là [phía mình sai ở đâu, phía khách hiểu lầm ở đâu]. Công ty có thể [đền bù / sửa / giải thích] như sau: [___].\nViết thư trả lời: xin lỗi đúng chỗ cần xin lỗi, giải thích ngắn không đổ lỗi, đưa giải pháp kèm mốc thời gian. Sau đó đóng vai ch", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Rà soát hợp đồng theo phía mình", "u": "thu-vien-prompt.html#p-_thu-vien-them-8", "x": "Mình là [bên mua / bên bán / bên thuê…] trong hợp đồng đính kèm (đã che tên và số). Rà soát giúp mình:\n1. Nghĩa vụ chính và thời hạn của mỗi bên.\n2. Điều khoản bất lợi cho phía mình, xếp theo mức rủi ro.\n3. Điều khoản mơ hồ, có thể hiểu theo nhiều cách.\n4. Những gì thường có trong loại hợp đồng này ", "k": "prompt"}, {"t": "Thư viện prompt", "h": "So sánh hai phiên bản văn bản", "u": "thu-vien-prompt.html#p-_thu-vien-them-9", "x": "Mình gửi hai phiên bản của cùng một [hợp đồng / quy chế / văn bản]: bản cũ và bản mới. Lập bảng so sánh gồm: Điều, Bản cũ, Bản mới, Thay đổi có ý nghĩa gì với [phía mình]. Chỉ liệt kê những chỗ thay đổi về nội dung, bỏ qua lỗi chính tả hay đổi cách trình bày. Cuối bảng, nêu 3 thay đổi quan trọng nhấ", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Giải thích văn bản pháp luật cho người không chuyên", "u": "thu-vien-prompt.html#p-_thu-vien-them-10", "x": "Đây là [tên văn bản / đoạn trích]. Giải thích giúp mình cho [nhân viên kinh doanh / kế toán / ban giám đốc] hiểu: văn bản này quy định gì, áp dụng cho ai, từ khi nào, công ty mình cần làm gì khác đi. Dùng lời thường, có ví dụ.\nChỉ dựa trên nội dung mình gửi. Chỗ nào văn bản không nói rõ thì ghi \"văn", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Lập checklist hồ sơ", "u": "thu-vien-prompt.html#p-_thu-vien-them-11", "x": "Mình cần chuẩn bị hồ sơ cho [thủ tục / gói thầu / nghiệm thu / ký hợp đồng với nhà cung cấp mới]. Dựa trên [tài liệu hướng dẫn đính kèm / yêu cầu sau: ___], lập giúp mình checklist gồm: tên giấy tờ, số bản, bản gốc hay bản sao, ai chuẩn bị, hạn chót. Đánh dấu những giấy tờ hay bị thiếu hoặc mất nhiề", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Tóm tắt hồ sơ mời thầu", "u": "thu-vien-prompt.html#p-_thu-vien-them-12", "x": "Đây là hồ sơ mời thầu [tên gói thầu]. Tóm tắt giúp mình trên 1 trang: yêu cầu bắt buộc (năng lực, kinh nghiệm, tài chính), tiêu chí đánh giá, các mốc thời gian quan trọng, bảo lãnh dự thầu. Rồi liệt kê những điểm công ty mình có thể yếu, biết rằng công ty mình [mô tả ngắn năng lực].\nMỗi ý ghi số mục", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Soạn phụ lục sửa đổi hợp đồng", "u": "thu-vien-prompt.html#p-_thu-vien-them-13", "x": "Hai bên muốn sửa hợp đồng số [___] ở các điểm sau: [liệt kê: đổi thời hạn giao hàng, đổi giá, thêm hạng mục…]. Các điều khoản khác giữ nguyên.\nSoạn giúp mình phụ lục sửa đổi: căn cứ, nội dung sửa đổi ghi rõ \"Điều X được sửa thành…\", hiệu lực, số bản. Thêm 3 lưu ý pháp lý mình nên kiểm tra trước khi ", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Viết công thức Excel bằng tiếng Việt", "u": "thu-vien-prompt.html#p-_thu-vien-them-14", "x": "Bảng của mình: cột A là [___], cột B là [___], cột C là [___], dữ liệu từ dòng 2 đến dòng [___]. Mình muốn [mô tả điều muốn tính, ví dụ: tổng tiền theo từng nhà cung cấp trong tháng 9].\nViết công thức giúp mình và giải thích từng phần thật dễ hiểu. Excel của mình dùng dấu [\";\" / \",\"] để ngăn cách. N", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Đối chiếu công nợ", "u": "thu-vien-prompt.html#p-_thu-vien-them-15", "x": "Mình có hai bảng: sổ chi tiết công nợ của công ty và biên bản đối chiếu khách hàng [mã KH] gửi về (đã che tên). Đối chiếu giúp mình từng hoá đơn và từng lần thanh toán: khớp, lệch số tiền, có bên này mà không có bên kia. Lập bảng chênh lệch, đoán nguyên nhân có thể (ghi rõ là đoán), và soạn sẵn emai", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Giải thích biến động so với kỳ trước", "u": "thu-vien-prompt.html#p-_thu-vien-them-16", "x": "Đây là số liệu [chi phí / doanh thu] kỳ này và kỳ trước theo từng khoản mục. Chỉ ra 5 khoản biến động lớn nhất (cả số tuyệt đối và phần trăm), rồi viết đoạn thuyết minh ngắn cho từng khoản. Chỗ nào bạn không biết nguyên nhân thì để [CẦN BỔ SUNG LÝ DO] cho mình điền, đừng tự nghĩ ra lý do.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Dọn sạch một danh sách", "u": "thu-vien-prompt.html#p-_thu-vien-them-17", "x": "Đây là danh sách [khách hàng / nhà cung cấp / nhân sự] gõ tay qua nhiều năm, khá lộn xộn. Dọn giúp mình: gộp tên viết khác nhau của cùng một đơn vị, chuẩn hoá số điện thoại và ngày tháng, đánh dấu dòng trùng và dòng thiếu thông tin. Cho mình tải file đã sửa, kèm bảng ghi lại bạn đã sửa những gì.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Tìm điểm bất thường", "u": "thu-vien-prompt.html#p-_thu-vien-them-18", "x": "Đây là bảng [chi phí / nhật ký kho / chấm công] tháng [___]. Tìm giúp mình những điểm bất thường: số tiền lớn khác thường, giao dịch trùng, ngày lạ (cuối tuần, ngày lễ), người đề nghị lặp lại nhiều. Với mỗi điểm, nói vì sao bạn thấy bất thường và mình nên kiểm tra gì. Đừng kết luận ai sai, chỉ đánh ", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Từ bảng số đến nhận xét cho sếp", "u": "thu-vien-prompt.html#p-_thu-vien-them-19", "x": "Đây là bảng số liệu [doanh số / tiến độ / chi phí] tuần này. Viết giúp mình 5 dòng nhận xét cho Giám đốc: điều tốt nhất, điều đáng lo nhất, xu hướng so với tuần trước, một việc cần sếp quyết định, một đề xuất. Mỗi nhận xét phải kèm con số cụ thể từ bảng. Sau đó đóng vai sếp khó tính, hỏi vặn mình 2 ", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Biên bản họp từ ghi chú vội", "u": "thu-vien-prompt.html#p-_thu-vien-them-20", "x": "Đây là ghi chú mình viết vội trong cuộc họp [tên cuộc họp] ngày [___], thành phần gồm [___]. Viết lại thành biên bản: nội dung đã thống nhất, việc cần làm (ai làm, hạn khi nào), vấn đề còn treo. Chỗ nào ghi chú không rõ ai nhận việc hoặc hạn khi nào thì đánh dấu [CẦN XÁC NHẬN], đừng tự điền.\n\n[Dán g", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Lên kế hoạch tuần", "u": "thu-vien-prompt.html#p-_thu-vien-them-21", "x": "Tuần này mình có các việc sau: [liệt kê, kèm hạn nếu có]. Lịch cố định: [các cuộc họp, buổi đi công tác]. Mình làm việc tốt nhất vào [buổi sáng / buổi chiều].\nSắp xếp giúp mình kế hoạch tuần: việc nào làm trước, chia vào từng ngày, chừa thời gian cho việc phát sinh. Chỉ ra việc nào có thể nhờ AI làm", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Viết OKR cho quý", "u": "thu-vien-prompt.html#p-_thu-vien-them-22", "x": "Mình là [vị trí] ở [phòng ban]. Quý tới, công ty ưu tiên [___], còn phòng mình muốn [___]. Giúp mình viết 2–3 mục tiêu (Objective) truyền cảm hứng, mỗi mục tiêu có 2–4 kết quả then chốt (Key Result) đo được bằng con số. Sau đó chỉ ra kết quả nào đang mơ hồ hoặc khó đo, và gợi ý sửa.\nHỏi mình vài câu", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Chuẩn bị cho một cuộc họp khó", "u": "thu-vien-prompt.html#p-_thu-vien-them-23", "x": "Tuần sau mình họp với [ai] về [vấn đề]. Mình muốn đạt được [___], còn phía bên kia có thể muốn [___]. Giúp mình chuẩn bị: mục tiêu cuộc họp, 3 luận điểm chính, 5 câu hỏi khó họ có thể hỏi và cách trả lời, điểm mình có thể nhượng bộ và điểm không được nhượng. Sau đó đóng vai họ để mình tập nói thử.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Chia việc lớn thành đầu việc nhỏ", "u": "thu-vien-prompt.html#p-_thu-vien-them-24", "x": "Mình phụ trách [dự án / sự kiện / chuyển văn phòng], hạn hoàn thành [ngày], nhóm có [số người, vai trò]. Chia giúp mình thành các đầu việc nhỏ, mỗi việc làm xong trong 1–2 ngày, có người phụ trách gợi ý, thứ tự trước sau, và mốc kiểm tra. Đánh dấu những việc dễ bị trễ nhất. Xuất thành bảng để mình d", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Bộ câu hỏi phỏng vấn tuyển dụng", "u": "thu-vien-prompt.html#p-_thu-vien-them-25", "x": "Mình cần phỏng vấn ứng viên vị trí [___], yêu cầu chính: [kỹ năng, kinh nghiệm]. Văn hoá nhóm mình: [___].\nSoạn giúp mình 10 câu hỏi phỏng vấn: kiểm tra chuyên môn, kỹ năng xử lý tình huống, độ hợp văn hoá. Với mỗi câu, ghi câu trả lời tốt trông thế nào và dấu hiệu đáng lo. Kèm một bảng chấm điểm đơ", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Viết nhận xét đánh giá nhân viên", "u": "thu-vien-prompt.html#p-_thu-vien-them-26", "x": "Mình cần viết nhận xét đánh giá [6 tháng / cuối năm] cho một thành viên trong nhóm (không ghi tên). Điểm mạnh mình quan sát được: [ví dụ cụ thể]. Điểm cần cải thiện: [ví dụ cụ thể]. Mục tiêu kỳ tới: [___].\nViết giúp mình bản nhận xét công bằng, cụ thể, dựa trên hành vi chứ không phán xét con người, ", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Dàn ý bài thuyết trình", "u": "thu-vien-prompt.html#p-_thu-vien-them-27", "x": "Mình cần thuyết trình [chủ đề] trong [số] phút cho [ai nghe, họ quan tâm gì]. Điều mình muốn họ nhớ nhất sau buổi là [___].\nGiúp mình dàn ý: mở đầu gây chú ý, 3 ý chính, mỗi ý có ví dụ hoặc con số, kết thúc với lời kêu gọi rõ ràng. Gợi ý nội dung cho từng slide, mỗi slide không quá 15 chữ.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Luyện trả lời câu hỏi khó", "u": "thu-vien-prompt.html#p-_thu-vien-them-28", "x": "Mình sắp trình bày [nội dung] trước [ai]. Bạn đóng vai người nghe khó tính nhất trong phòng, hỏi mình từng câu một, mỗi lần một câu. Sau mỗi câu trả lời của mình, chấm điểm 1–10 và gợi ý cách trả lời gọn, thuyết phục hơn. Hỏi tổng cộng 5 câu nhé.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Báo giá kèm thư chào hàng", "u": "thu-vien-prompt.html#p-_thu-vien-them-29", "x": "Khách [mô tả: loại doanh nghiệp, nhu cầu] hỏi báo giá [sản phẩm / dịch vụ]. Thông tin: [danh mục, số lượng, đơn giá, chiết khấu, VAT, thời gian giao, hiệu lực báo giá].\nLàm giúp mình bảng báo giá rõ ràng, tự tính thành tiền, chiết khấu, VAT, tổng cộng, kèm một thư chào hàng ngắn nhấn vào lợi ích khá", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Bài đăng giới thiệu sản phẩm", "u": "thu-vien-prompt.html#p-_thu-vien-them-30", "x": "Viết giúp mình 3 phiên bản bài đăng [Facebook / LinkedIn / Zalo OA] giới thiệu [sản phẩm, dịch vụ] cho [khách hàng mục tiêu]. Điểm khác biệt: [___]. Ưu đãi: [___].\nMỗi bản một phong cách: kể chuyện, ngắn gọn thẳng vào lợi ích, hỏi đáp. Không phóng đại, không dùng từ \"tốt nhất\", \"số 1\" nếu không có c", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Kịch bản chăm sóc khách hàng qua điện thoại", "u": "thu-vien-prompt.html#p-_thu-vien-them-31", "x": "Mình cần kịch bản gọi điện cho [khách mới mua hàng / khách lâu không quay lại / khách vừa phàn nàn] của công ty [ngành]. Mục tiêu cuộc gọi: [___].\nViết kịch bản gồm: câu chào, câu hỏi mở, cách xử lý 4 phản ứng thường gặp (bận, không quan tâm, đang bực, hỏi giá), cách kết thúc. Lời nói tự nhiên như n", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Viết lại cho từng đối tượng", "u": "thu-vien-prompt.html#p-_thu-vien-them-32", "x": "Đây là nội dung về [chủ đề, ví dụ: chính sách công tác phí mới]. Viết lại thành 3 phiên bản: một cho Ban giám đốc (ngắn, tập trung tác động và chi phí), một cho nhân viên (dễ hiểu, họ cần làm gì), một cho khách hàng hoặc đối tác (nếu liên quan, lịch sự, ngắn). Giữ đúng thông tin, chỉ đổi cách nói.\n\n", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Luyện tiếng Anh theo tình huống công việc", "u": "thu-vien-prompt.html#p-_thu-vien-them-33", "x": "Mình muốn luyện tiếng Anh để [họp với đối tác / viết email cho khách nước ngoài / phỏng vấn]. Trình độ của mình khoảng [mới bắt đầu / giao tiếp cơ bản / khá]. Bạn đóng vai [đối tác / khách hàng / người phỏng vấn], nói chuyện với mình bằng tiếng Anh đơn giản, mỗi lần 1–2 câu. Sau mỗi câu mình trả lời", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Sửa email tiếng Anh và giải thích lỗi", "u": "thu-vien-prompt.html#p-_thu-vien-them-34", "x": "Đây là email tiếng Anh mình viết gửi [ai] về [việc gì]. Sửa giúp mình cho tự nhiên và chuyên nghiệp, giữ đúng ý. Sau đó lập bảng các lỗi mình hay mắc (ngữ pháp, từ dùng chưa hợp, câu dịch kiểu tiếng Việt), giải thích bằng tiếng Việt để lần sau mình tự tránh được.\n\n[Dán email]", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Lộ trình học nhanh một chủ đề mới", "u": "thu-vien-prompt.html#p-_thu-vien-them-35", "x": "Mình cần hiểu về [chủ đề, ví dụ: hoá đơn điện tử, quản trị dự án, phân tích báo cáo tài chính] đủ để [mục tiêu cụ thể] trong 2 tuần, mỗi ngày học được khoảng [số] phút.\nLập giúp mình lộ trình theo ngày: học gì, tài liệu loại gì nên tìm, bài tập nhỏ để tự kiểm tra. Bắt đầu bằng việc hỏi mình 3 câu để", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Chuẩn bị phỏng vấn hoặc đàm phán lương", "u": "thu-vien-prompt.html#p-_thu-vien-them-36", "x": "Mình sắp [phỏng vấn vị trí ___ / nói chuyện tăng lương với sếp]. Những gì mình đã làm được: [kết quả cụ thể, con số]. Điều mình mong muốn: [___].\nGiúp mình chuẩn bị: cách kể thành tích ngắn gọn, thuyết phục; 5 câu khó có thể bị hỏi và gợi ý trả lời; những câu nên tránh nói. Rồi đóng vai [người phỏng", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Tóm tắt sách để áp dụng ngay", "u": "thu-vien-prompt.html#p-_thu-vien-them-37", "x": "Mình vừa đọc (hoặc muốn đọc) cuốn [tên sách] của [tác giả]. Tóm tắt giúp mình các ý chính, rồi gợi ý 5 cách áp dụng cụ thể cho công việc [nghề của bạn] và đời sống. Nếu bạn không chắc về nội dung cuốn sách thì nói rõ, đừng đoán.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Kế hoạch du lịch gia đình", "u": "thu-vien-prompt.html#p-_thu-vien-them-38", "x": "Nhà mình [số người, độ tuổi các con, ông bà có đi không] muốn đi [địa điểm] [số] ngày vào [thời gian], ngân sách khoảng [___]. Nhà mình thích [biển / ăn uống / thiên nhiên / nghỉ ngơi nhẹ nhàng], không thích [___].\nLên giúp mình lịch trình từng ngày, có thời gian nghỉ cho trẻ nhỏ, danh sách đồ cần m", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Thực đơn tuần và danh sách đi chợ", "u": "thu-vien-prompt.html#p-_thu-vien-them-39", "x": "Nhà mình [số người], có [trẻ nhỏ / người lớn tuổi / người ăn kiêng / dị ứng ___]. Mình có khoảng [số] phút nấu mỗi tối, thích món [miền Bắc / miền Nam / đa dạng].\nLên thực đơn 7 ngày cho bữa tối, cân bằng dinh dưỡng, tận dụng nguyên liệu giữa các ngày để đỡ phí. Kèm danh sách đi chợ gom theo nhóm (r", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Giúp con học mà không làm hộ", "u": "thu-vien-prompt.html#p-_thu-vien-them-40", "x": "Con mình học lớp [___], đang gặp khó với [môn / dạng bài]. Mình muốn giúp con tự hiểu, không làm hộ.\nBạn đóng vai gia sư kiên nhẫn: giải thích bằng ví dụ gần gũi với trẻ [tuổi], rồi đưa từng câu hỏi gợi mở để con tự tìm ra đáp án. Cho thêm 5 bài luyện từ dễ đến khó. Mình sẽ đọc to cho con nghe, nên ", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Lập ngân sách gia đình", "u": "thu-vien-prompt.html#p-_thu-vien-them-41", "x": "Thu nhập hằng tháng của nhà mình khoảng [___]. Các khoản chi cố định: [___]. Mục tiêu: [tiết kiệm mua nhà / quỹ học cho con / quỹ dự phòng] khoảng [___] trong [thời gian].\nGiúp mình chia ngân sách hằng tháng thành các nhóm hợp lý, chỉ ra khoản nào có thể cắt giảm, và làm một bảng theo dõi đơn giản m", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Lời chúc, lời phát biểu", "u": "thu-vien-prompt.html#p-_thu-vien-them-42", "x": "Mình cần [phát biểu ở đám cưới bạn thân / chúc mừng sinh nhật mẹ / chia tay đồng nghiệp nghỉ hưu], dài khoảng [số] phút. Vài kỷ niệm thật: [___]. Mình muốn giọng [xúc động / vui vẻ / trang trọng].\nViết giúp mình 2 phiên bản, câu ngắn để dễ nói, không sáo rỗng. Đánh dấu chỗ nên ngừng lại một chút khi", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Đọc hiểu giấy tờ cá nhân", "u": "thu-vien-prompt.html#p-_thu-vien-them-43", "x": "Đây là [hợp đồng thuê nhà / điều khoản bảo hiểm / hợp đồng vay] mình sắp ký (đã che tên và số giấy tờ). Giải thích giúp mình bằng lời thường: mình phải làm gì, mất tiền ở những khoản nào, trường hợp nào mình bị thiệt, điều khoản nào nên hỏi lại trước khi ký. Trích nguyên văn điều khoản để mình đối c", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Bạn cần biết gì?", "u": "thu-vien-prompt.html#p-_thu-vien-them-44", "x": "Mình muốn [việc bạn cần]. Bạn cần biết gì từ mình để làm tốt nhất? Hỏi mình từng câu một, đợi mình trả lời rồi mới hỏi câu tiếp nhé.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Viết lại câu nhờ của mình cho tốt hơn", "u": "thu-vien-prompt.html#p-_thu-vien-them-45", "x": "Đây là câu mình định nhờ AI: \"[dán câu nhờ]\". Bạn góp ý giúp: còn thiếu bối cảnh gì, chỗ nào dễ hiểu sai, kết quả mình mong đợi đã rõ chưa. Rồi viết lại thành một câu nhờ tốt hơn, giải thích ngắn vì sao tốt hơn.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Tự chấm bài theo tiêu chí", "u": "thu-vien-prompt.html#p-_thu-vien-them-46", "x": "Trước khi đưa mình bản cuối, tự chấm bài của bạn theo các tiêu chí sau, mỗi tiêu chí điểm 1–10: [đúng mục tiêu / chính xác về số liệu / đúng giọng văn / ngắn gọn / người nhận hành động được ngay]. Tiêu chí nào dưới 8 điểm thì sửa, rồi mới đưa mình bản cuối kèm bảng điểm.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Đóng vai người phản biện", "u": "thu-vien-prompt.html#p-_thu-vien-them-47", "x": "Bạn đóng vai [luật sư phía đối tác / sếp khó tính / khách hàng khó chiều / kiểm toán viên], đọc bản nháp này và phản biện thẳng thắn: 3 điểm yếu nhất, 3 câu hỏi khó nhất họ sẽ hỏi. Sau đó giúp mình sửa bản nháp để trả lời trước những câu hỏi đó.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Có file mà chưa biết nhờ gì", "u": "thu-vien-prompt.html#p-_thu-vien-them-48", "x": "Mình có [file / tài liệu / ảnh] này nhưng chưa biết nên nhờ bạn làm gì với nó. Mình làm [nghề], file này dùng để [___]. Bạn xem qua rồi gợi ý 5 việc bạn có thể giúp, việc nào tiết kiệm thời gian nhất cho mình thì đưa lên đầu.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Tóm tắt để mở cuộc trò chuyện mới", "u": "thu-vien-prompt.html#p-_thu-vien-them-49", "x": "Cuộc trò chuyện này dài quá rồi. Tóm tắt giúp mình mọi thứ quan trọng để mình mở cuộc trò chuyện mới mà không mất mạch: mục tiêu, bối cảnh, những gì đã quyết định, kết quả hiện tại, việc còn dang dở. Viết thành một đoạn để mình copy dán vào cuộc trò chuyện mới.", "k": "prompt"}, {"t": "Thư viện prompt", "h": "Biến cách làm hôm nay thành hướng dẫn dùng lại", "u": "thu-vien-prompt.html#p-_thu-vien-them-50", "x": "Hôm nay mình với bạn đã làm xong [việc] qua cuộc trò chuyện này. Viết giúp mình một bản hướng dẫn để lần sau dán vào Project (hoặc gửi cho đồng nghiệp làm theo): đầu vào cần chuẩn bị, các bước, câu nhờ mẫu cho từng bước, cách kiểm tra kết quả, những lỗi đã gặp và cách tránh.", "k": "prompt"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Prompt: Nhờ tạo bảng thay thế mẫu (không dùng dữ liệu thật)", "u": "an-toan.html#p-an-toan-1", "x": "Mình sắp ẩn danh một [hợp đồng / bảng công nợ / email khách hàng] trước khi nhờ AI đọc. Mình sẽ không gửi dữ liệu thật cho bạn.\nBạn tạo giúp mình một bảng thay thế mẫu gồm 3 cột: Loại thông tin, Mã thay thế gợi ý, Lưu ý khi thay. Liệt kê đủ các loại thông tin dễ bị sót trong loại tài liệu này của ng", "k": "prompt"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Prompt: Soạn tin nhắn hỏi về chính sách AI", "u": "an-toan.html#p-an-toan-2", "x": "Mình muốn hỏi [quản lý / bộ phận IT] xem công ty có cho dùng AI trong công việc không và được đưa loại dữ liệu nào vào. Mình muốn tin nhắn nghe như đang muốn làm đúng quy định, chứ không như đang xin làm việc riêng.\nViết giúp mình một [tin nhắn Zalo / email] ngắn, lịch sự, kèm 4–5 câu hỏi cụ thể. Gi", "k": "prompt"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Prompt: Căn cứ đâu?", "u": "an-toan.html#p-an-toan-3", "x": "Với mỗi ý bạn vừa đưa ra, trích nguyên văn câu trong tài liệu kèm số Điều (hoặc số trang). Chỗ nào là bạn suy luận chứ không có trong tài liệu thì ghi rõ \"suy luận\".", "k": "prompt"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Prompt: Điểm nào bạn không chắc?", "u": "an-toan.html#p-an-toan-4", "x": "Trong câu trả lời vừa rồi, điểm nào bạn không chắc chắn nhất? Xếp từ ít chắc đến chắc nhất, và nói mình nên kiểm tra từng điểm ở đâu.", "k": "prompt"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Prompt: Dặn trước: không có thì nói không có", "u": "an-toan.html#p-an-toan-5", "x": "Trước khi bắt đầu: chỉ trả lời dựa trên tài liệu mình gửi. Nếu tài liệu không có thông tin, nói rõ \"tài liệu không đề cập\", đừng đoán. Nếu bạn dùng kiến thức bên ngoài, đánh dấu riêng để mình biết.", "k": "prompt"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Prompt: Làm sao để mình kiểm tra bạn?", "u": "an-toan.html#p-an-toan-6", "x": "Làm sao để mình biết bạn không bịa trong câu trả lời này? Gợi ý cho mình 3 cách cụ thể để tự kiểm tra, cách nhanh nhất trước.", "k": "prompt"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Prompt: Chỉ cách tính", "u": "an-toan.html#p-an-toan-7", "x": "Chỉ cho mình từng bước bạn tính ra con số [___]: lấy từ dòng nào, cộng trừ thế nào, có làm tròn hay bỏ dòng nào không. Chọn 3 dòng bất kỳ để mình đối chiếu với file gốc.", "k": "prompt"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Prompt: Văn bản còn hiệu lực không?", "u": "an-toan.html#p-an-toan-8", "x": "Bạn vừa dẫn [tên văn bản / số điều]. Văn bản này hiện còn hiệu lực không, đã bị sửa đổi hay thay thế chưa? Kiến thức của bạn cập nhật đến khi nào? Nếu không chắc thì nói thẳng, và chỉ mình nên tra ở nguồn chính thức nào.", "k": "prompt"}, {"t": "Dùng AI an toàn & tỉnh táo", "h": "Prompt: Đóng vai người soát lỗi khó tính", "u": "an-toan.html#p-an-toan-9", "x": "Giờ bạn đóng vai một người soát lỗi khó tính, đọc lại câu trả lời của chính bạn. Tìm mọi chỗ có thể sai: con số, ngày tháng, tên riêng, trích dẫn, suy luận vội. Liệt kê ra, rồi sửa những chỗ bạn chắc là sai.", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Gửi ảnh kèm đủ 3 điều", "u": "anh-chup.html#p-anh-chup-1", "x": "Mình gửi [số] ảnh [hoá đơn / bảng trắng / màn hình báo lỗi]. Mình cần [bảng chi phí để nộp kế toán]. Làm [kỹ, đây là số liệu quyết toán / nhanh, nháp là được]. Để mình kiểm: chép đúng những gì đọc được, chỗ nào mờ hay không chắc thì ghi [?] và liệt kê ở cuối, đừng đoán. Thiếu gì thì hỏi mình trước.", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Hoá đơn thành bảng chi phí", "u": "anh-chup.html#p-anh-chup-2", "x": "Đây là ảnh [10] hoá đơn của [chuyến công tác tháng 9]. Lập bảng: Ngày, Nhà cung cấp, Nội dung, Số tiền (VND), và cột \"Cần kiểm tra lại\" cho dòng đọc không chắc. Cuối bảng có dòng tổng. Sau bảng, liệt kê riêng các số không chắc, ghi rõ ảnh số mấy.", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Bảng trắng thành biên bản", "u": "anh-chup.html#p-anh-chup-3", "x": "Ảnh này là bảng trắng sau cuộc họp [kế hoạch quý 4], chữ viết tay hơi xấu. Chuyển thành: (1) biên bản ngắn: đã bàn gì, chốt gì; (2) bảng việc cần làm: việc, người phụ trách, hạn. Chỗ nào không đọc ra hoặc không chắc mũi tên nối ý nào, ghi [?] và hỏi mình.", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Màn hình báo lỗi", "u": "anh-chup.html#p-anh-chup-4", "x": "Mình đang [nhập công thức trong Excel trên Windows] thì hiện lỗi như ảnh. Mình không rành kỹ thuật, chỉ mình từng bước, nói rõ bấm vào đâu. Xong mỗi bước mình báo lại rồi mới sang bước tiếp.", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Giải thích từng ô trong tờ khai", "u": "anh-chup.html#p-anh-chup-5", "x": "Đây là ảnh mẫu [tờ khai / đơn đăng ký] còn trống. Giải thích từng ô: ô đó hỏi gì, thường lấy thông tin từ giấy tờ nào, lỗi hay gặp. Mình sẽ tự điền. Chỗ nào phụ thuộc quy định hiện hành, nói rõ để mình kiểm tra với nơi tiếp nhận.", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Đọc biểu đồ, gợi ý câu hỏi", "u": "anh-chup.html#p-anh-chup-6", "x": "Đây là biểu đồ [doanh thu theo quý] mình sắp nghe trình bày. Cho mình: (1) biểu đồ nói gì, trong 3 câu; (2) điểm bất thường hoặc dễ gây hiểu lầm, như trục không bắt đầu từ 0; (3) 3 câu hỏi nên đặt cho người trình bày. Số nào ước lượng từ hình, ghi rõ là ước lượng.", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Liệt kê chỗ đọc không chắc", "u": "anh-chup.html#p-anh-chup-7", "x": "Trước khi mình dùng: (1) liệt kê mọi ô, mọi số bạn đọc không chắc, ghi ảnh số mấy, vị trí nào; (2) với từng hoá đơn, cộng các dòng hàng và so với tổng in trên tờ, chỗ nào lệch thì báo; (3) mình gửi [10] ảnh, bảng có đủ [10] dòng không?", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Tóm tắt công văn giấy", "u": "anh-chup.html#p-anh-chup-8", "x": "Đây là ảnh công văn [đã che tên công ty và người ký]. Tóm tắt: ai yêu cầu gì, căn cứ nào được viện dẫn, thời hạn trả lời. Trích nguyên văn câu chứa thời hạn để mình đối chiếu với bản giấy.", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Biên bản đối chiếu thành bảng", "u": "anh-chup.html#p-anh-chup-9", "x": "Đây là ảnh biên bản đối chiếu công nợ [đã che tên và mã số thuế]. Chuyển thành bảng: Số hoá đơn, Ngày, Số tiền, Đã thanh toán, Còn lại. Ô nào đọc không chắc thì ghi [?]. Cộng cột Còn lại và so với số tổng in trên biên bản.", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Ảnh hàng lỗi thành phản hồi", "u": "anh-chup.html#p-anh-chup-10", "x": "Khách gửi ảnh [ghế xoay] bị [nứt chân], mình đã cắt phần có mặt người và địa chỉ. Mô tả lỗi nhìn thấy, gợi ý 3 câu cần hỏi thêm để xét bảo hành, soạn tin trả lời ngắn, ân cần. Chỗ nào ảnh không đủ để kết luận, nói rõ.", "k": "prompt"}, {"t": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "h": "Prompt: Ảnh hiện trường thành báo cáo", "u": "anh-chup.html#p-anh-chup-11", "x": "Đây là [3] ảnh [vết thấm trần tầng hầm]. Viết phần mô tả hiện trạng cho báo cáo sự cố: vị trí, điều nhìn thấy, mức độ ước lượng, đề xuất kiểm tra tiếp. Phần đoán nguyên nhân ghi rõ là suy đoán.", "k": "prompt"}, {"t": "Làm quen người bạn AI", "h": "Prompt: Bạn cần biết gì từ mình?", "u": "bat-dau.html#p-bat-dau-1", "x": "Mình muốn [việc bạn cần]. Bạn cần biết gì từ mình để làm tốt nhất? Hỏi mình từng câu một nhé.", "k": "prompt"}, {"t": "Làm quen người bạn AI", "h": "Prompt: Gợi ý việc bạn giúp được", "u": "bat-dau.html#p-bat-dau-2", "x": "Mình có [file / tình huống] này nhưng chưa biết nên nhờ bạn làm gì. Bạn gợi ý 5 việc bạn có thể giúp mình?", "k": "prompt"}, {"t": "Làm quen người bạn AI", "h": "Prompt: Mình làm nghề này, bạn giúp được gì?", "u": "bat-dau.html#p-bat-dau-3", "x": "Mình làm nghề [___], mỗi ngày mình hay làm [___]. Bạn giúp được mình những việc gì? Gợi ý 10 việc, xếp từ dễ đến khó.", "k": "prompt"}, {"t": "Làm quen người bạn AI", "h": "Prompt: Chưa đúng ý mà không biết nói sao", "u": "bat-dau.html#p-bat-dau-4", "x": "Kết quả này chưa đúng ý mình lắm, nhưng mình cũng không biết diễn tả sao. Bạn hỏi mình vài câu để hiểu rõ hơn nhé.", "k": "prompt"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Prompt: Kiểu \"người lạ\"", "u": "cap-1.html#p-cap-1-1", "x": "viết email trả lời khách về việc giao hàng chậm", "k": "prompt"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Prompt: Hỏi thẳng bạn ấy", "u": "cap-1.html#p-cap-1-2", "x": "Mình cần trả lời một khách hàng lâu năm đang rất bực vì đơn hàng giao chậm. Bạn cần biết gì để viết email này thật tốt? Hỏi mình từng câu một nhé.", "k": "prompt"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Prompt: Nhờ góp ý thẳng", "u": "cap-1.html#p-cap-1-3", "x": "Giờ bạn đóng vai người nhận, một người đang rất bực và khó tính. Đọc email này rồi nói thật 3 chỗ chưa ổn. Xong viết lại giúp mình.", "k": "prompt"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Prompt: Chốt bản cuối", "u": "cap-1.html#p-cap-1-4", "x": "Ok, chốt giúp mình bản cuối: có tiêu đề, thân dưới 150 chữ, 2 phiên bản (trang trọng và thân thiện). Đánh dấu giúp mình những chỗ bạn tự thêm thông tin mà mình chưa nói.", "k": "prompt"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Prompt: Giao một lần cho trọn, như cho đồng nghiệp", "u": "cap-1.html#p-cap-1-5", "x": "Mình cần trả lời khách hàng [Công ty A], khách lâu năm, vừa phàn nàn vì đơn hàng giao chậm [5 ngày] do lỗi điều phối kho của bên mình. Họ đang rất bực, và mình muốn giữ khách.\nThế nào là tốt: xin lỗi cụ thể, không đổ lỗi, có giải pháp và mốc thời gian, đề xuất 1 ưu đãi bù đắp hợp lý. Có tiêu đề, thâ", "k": "prompt"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Prompt: Soi chỗ bạn ấy tự thêm", "u": "cap-1.html#p-cap-1-6", "x": "Trong email này, liệt kê giúp mình mọi tên người, con số, ngày giờ, cam kết và ưu đãi. Cái nào là mình đã nói, cái nào là bạn tự thêm?", "k": "prompt"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Prompt: Công văn giải trình", "u": "cap-1.html#p-cap-1-7", "x": "Công ty mình vừa nhận công văn của [cơ quan] yêu cầu giải trình về [vấn đề] trong 10 ngày. Mình cần soạn công văn trả lời, chặt chẽ, đúng thể thức, không thừa nhận quá những gì đã xảy ra. Bạn cần biết gì thì hỏi mình từng câu một nhé.", "k": "prompt"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Prompt: Nhắc nợ lần 2", "u": "cap-1.html#p-cap-1-8", "x": "Khách hàng [B] quá hạn thanh toán 45 ngày, mình đã nhắc 1 lần qua email. Mình cần email nhắc lần 2, lịch sự mà cương quyết, nêu rõ bước tiếp theo nếu vẫn chưa thanh toán. Hỏi mình từng câu một trước khi viết nhé.", "k": "prompt"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Prompt: Từ chối giảm giá khéo léo", "u": "cap-1.html#p-cap-1-9", "x": "Khách hỏi giảm giá 15% nhưng mình chỉ được duyệt tối đa 5%. Mình cần trả lời khéo để không mất khách, có thể đề xuất thứ khác thay cho giảm giá. Bạn cần biết gì về khách và đơn hàng thì hỏi mình nhé.", "k": "prompt"}, {"t": "Email khó, viết lại trong 30 giây", "h": "Prompt: Thông báo dừng thang máy", "u": "cap-1.html#p-cap-1-10", "x": "Thang máy block B phải dừng bảo trì 2 ngày. Mình cần thông báo gửi cư dân: ngắn, dễ hiểu, có thời gian cụ thể, phương án hỗ trợ người già và trẻ nhỏ, số liên hệ khi cần. Hỏi mình những gì còn thiếu rồi viết nhé. Xong đóng vai một cư dân khó tính góp ý luôn.", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Tóm tắt theo góc nhìn bên mua", "u": "cap-2.html#p-cap-2-1", "x": "Mình là bên mua. Tóm tắt giúp mình hợp đồng này nhé. Mình cần biết: ai phải làm gì, hạn khi nào, và chỗ nào bất lợi hoặc viết mơ hồ cho mình.", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Thử bắt bạn ấy đoán", "u": "cap-2.html#p-cap-2-2", "x": "Nếu bên bán giao hàng chậm thì bị phạt bao nhiêu tiền?", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Hỏi thẳng bạn ấy", "u": "cap-2.html#p-cap-2-3", "x": "Làm sao để mình biết bạn không bịa? Bạn gợi ý cách để mình kiểm tra câu trả lời của bạn đi.", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Trích nguyên văn kèm số Điều", "u": "cap-2.html#p-cap-2-4", "x": "Ok, làm đúng như bạn vừa nói nhé: với mỗi ý, trích nguyên văn câu trong tài liệu kèm số Điều (hoặc số trang). Chỗ nào là bạn suy luận thì nói rõ.", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Hỏi lại câu bẫy với luật chơi mới", "u": "cap-2.html#p-cap-2-5", "x": "Giờ trả lời lại câu lúc nãy theo đúng cách đó: nếu bên bán giao hàng chậm thì bị phạt bao nhiêu? Chỉ dùng thông tin trong hợp đồng, trích nguyên văn. Hợp đồng không nói thì nói là không có.", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Khi trích dẫn không khớp", "u": "cap-2.html#p-cap-2-6", "x": "Câu bạn trích ở Điều [số] không khớp với file của mình. Trong file ghi: \"[dán câu gốc]\". Kiểm tra lại toàn bộ các trích dẫn khác và sửa những chỗ sai giúp mình.", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Hỏi trong NotebookLM", "u": "cap-2.html#p-cap-2-7", "x": "Mình là bên mua. Liệt kê các điều khoản bất lợi cho mình. Nếu bên bán giao hàng chậm thì bị phạt bao nhiêu?", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: So sánh hai phiên bản văn bản", "u": "cap-2.html#p-cap-2-8", "x": "Mình gửi bạn 2 file: bản cũ và bản mới của [văn bản / hợp đồng]. Điểm nào mới, điểm nào bị bỏ, điểm nào sửa câu chữ làm đổi nghĩa? Với mỗi điểm, trích nguyên văn cả bản cũ và bản mới kèm số Điều.", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Đọc nhanh báo cáo tài chính", "u": "cap-2.html#p-cap-2-9", "x": "Đây là báo cáo tài chính [kỳ này] (đã che tên công ty). Khoản mục nào thay đổi nhiều nhất so với kỳ trước, vì sao? Với mỗi con số, ghi rõ lấy từ bảng nào, dòng nào để mình đối chiếu. Phần trăm thay đổi thì ghi luôn cách tính.", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Đọc hồ sơ mời thầu", "u": "cap-2.html#p-cap-2-10", "x": "Đây là hồ sơ mời thầu. Liệt kê giúp mình: các yêu cầu bắt buộc (không đáp ứng là bị loại), hạn nộp và các mốc thời gian, những điểm công ty mình có thể yếu. Mỗi ý trích nguyên văn kèm số mục hoặc số trang.", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Rà nghĩa vụ trong hợp đồng thi công", "u": "cap-2.html#p-cap-2-11", "x": "Mình là bên [nhà thầu / chủ đầu tư]. Đọc hợp đồng thi công này, lập bảng: nghĩa vụ của bên mình, mốc thời gian, điều kiện nghiệm thu, mức phạt nếu chậm. Mỗi dòng trích nguyên văn kèm số Điều. Chỗ nào hợp đồng không nói rõ thì ghi \"không quy định\".", "k": "prompt"}, {"t": "Tài liệu dài, và bẫy “AI bịa”", "h": "Prompt: Luật chơi khi đọc tài liệu", "u": "cap-2.html#p-cap-2-12", "x": "Trong cuộc trò chuyện này, chỉ dùng thông tin trong tài liệu mình gửi. Mỗi ý trích nguyên văn kèm số Điều hoặc số trang. Chỗ nào là suy luận thì ghi rõ \"suy luận\". Tài liệu không nói thì trả lời \"không có trong tài liệu\", đừng đoán.", "k": "prompt"}, {"t": "Excel lộn xộn thành sạch", "h": "Prompt: Hỏi thẳng bạn ấy", "u": "cap-3.html#p-cap-3-1", "x": "File này lộn xộn quá, mình cũng chưa biết nên làm gì với nó. Bạn xem qua rồi gợi ý 5 việc bạn có thể làm giúp mình nhé.", "k": "prompt"}, {"t": "Excel lộn xộn thành sạch", "h": "Prompt: Dọn, phân nhóm, tổng hợp, cho tải file", "u": "cap-3.html#p-cap-3-2", "x": "Làm hết mấy việc đó giúp mình nhé. Cụ thể:\n1. Bỏ dòng trùng (dòng giống hệt nhau ở mọi cột).\n2. Đưa cột Ngày về một định dạng ngày/tháng/năm. Tất cả đều là tháng 9/2026.\n3. Thống nhất tên nhà cung cấp, mỗi nơi một tên chuẩn.\n4. Đổi số tiền gõ dạng chữ thành số.\n5. Ô trống thì ghi \"Chưa rõ\", đừng tự ", "k": "prompt"}, {"t": "Excel lộn xộn thành sạch", "h": "Prompt: Giải thích 3 dòng và cách tính", "u": "cap-3.html#p-cap-3-3", "x": "Chọn ngẫu nhiên 3 dòng trong file gốc, cho mình biết số thứ tự dòng, rồi giải thích từng dòng: bạn đã sửa gì, xếp vào nhóm nào và vì sao. Chỉ luôn cho mình cách bạn tính tổng của nhóm Tiếp khách.", "k": "prompt"}, {"t": "Excel lộn xộn thành sạch", "h": "Prompt: Chỉ cách tự kiểm trong Excel", "u": "cap-3.html#p-cap-3-4", "x": "Mình đã tải file về. Chỉ mình cách tự kiểm tra trong Excel trong 2 phút: đếm số dòng, tính lại tổng tiền, và lọc xem tên nhà cung cấp đã thống nhất chưa. Hướng dẫn từng bước, nói rõ bấm vào đâu.", "k": "prompt"}, {"t": "Excel lộn xộn thành sạch", "h": "Prompt: Viết công thức và giải thích bằng tiếng Việt", "u": "cap-3.html#p-cap-3-5", "x": "Bảng của mình: cột A mã khách hàng, cột B ngày hoá đơn, cột C số tiền, cột D ngày đã trả (trống nếu chưa trả). Dữ liệu từ dòng 2 đến dòng 26. Hạn trả là 30 ngày kể từ ngày hoá đơn.\nMình muốn cột E tính số ngày quá hạn (khoản chưa trả thì tính đến hôm nay, khoản đã trả thì để 0), cột F ghi \"Đã trả\", ", "k": "prompt"}, {"t": "Excel lộn xộn thành sạch", "h": "Prompt: Hỏi lại dòng trùng và tổng tiền", "u": "cap-3.html#p-cap-3-6", "x": "Bạn tìm được bao nhiêu dòng trùng? Liệt kê số thứ tự các dòng đó trong file gốc. Tổng chi phí sau khi bỏ trùng là bao nhiêu? Có dòng nào số tiền không phải dạng số không, bạn xử lý chúng thế nào?", "k": "prompt"}, {"t": "Excel lộn xộn thành sạch", "h": "Prompt: Dọn danh sách hồ sơ vụ việc", "u": "cap-3.html#p-cap-3-7", "x": "Đây là danh sách hồ sơ vụ việc (đã thay tên khách hàng bằng mã). Bạn xem rồi gợi ý cách sắp xếp lại cho dễ theo dõi. Sau đó đánh dấu giúp mình những hồ sơ còn dưới 7 ngày là đến hạn, và giải thích bạn tính hạn thế nào.", "k": "prompt"}, {"t": "Excel lộn xộn thành sạch", "h": "Prompt: Phân loại sao kê ngân hàng", "u": "cap-3.html#p-cap-3-8", "x": "Đây là sao kê tài khoản tháng [9] tải từ ngân hàng (mình đã xoá số tài khoản). Phân loại các khoản thu chi theo nhóm hợp lý, tổng hợp theo nhóm, đánh dấu các khoản bất thường. Chọn 3 dòng giải thích cách bạn phân loại để mình kiểm tra.", "k": "prompt"}, {"t": "Excel lộn xộn thành sạch", "h": "Prompt: Ai là khách hàng quan trọng nhất?", "u": "cap-3.html#p-cap-3-9", "x": "Đây là danh sách đơn hàng 3 tháng gần nhất. Gộp những tên khách hàng bị viết khác nhau, rồi cho mình biết: top 10 khách hàng theo doanh số, và những khách đang mua ít đi so với tháng trước. Nói rõ cách bạn tính.", "k": "prompt"}, {"t": "Excel lộn xộn thành sạch", "h": "Prompt: Phân tích nhật ký sự cố", "u": "cap-3.html#p-cap-3-10", "x": "Đây là nhật ký sự cố bảo trì 6 tháng. Chuẩn hoá tên hạng mục, rồi cho mình biết: hạng mục nào hỏng nhiều nhất, thời gian xử lý trung bình bao lâu, tháng nào nhiều sự cố nhất. Vẽ biểu đồ và cho mình tải file đã làm sạch.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Nói tiếp từ bậc 3", "u": "cap-4.html#p-cap-4-1", "x": "Mình nói tiếp nhé. Trước khi làm báo cáo, bạn nhắc lại giúp mình: tổng chi phí tháng 9 sau khi bỏ dòng trùng, chi phí theo 5 nhóm (số tiền và tỷ trọng), và chi phí theo từng tuần. Trình bày thành 2 bảng gọn.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Số liệu mẫu nếu bạn bỏ qua bậc 3", "u": "cap-4.html#p-cap-4-2", "x": "Đây là chi phí tháng 9/2026 của công ty mình (đã làm sạch, bỏ 8 dòng trùng). Tổng: 384.070.000đ.\n\nTheo nhóm:\n- Văn phòng phẩm: 48.279.000đ (12,6%)\n- Đi lại: 30.258.000đ (7,9%)\n- Tiếp khách: 121.722.000đ (31,7%)\n- Dịch vụ thuê ngoài: 134.183.000đ (34,9%)\n- Khác: 49.628.000đ (12,9%)\n\nTheo tuần:\n- Tuần", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Hỏi thẳng bạn ấy", "u": "cap-4.html#p-cap-4-3", "x": "Giờ mình cần báo cáo kết quả này lên Giám đốc. Trước khi viết, bạn hỏi mình 3 câu về sếp và cuộc họp để viết cho hợp gu nhé. Hỏi từng câu một.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Viết báo cáo một trang", "u": "cap-4.html#p-cap-4-4", "x": "Dựa trên số liệu và những gì mình vừa kể về sếp, viết giúp mình báo cáo chi phí tháng 9 gửi Giám đốc, gói gọn trong 1 trang:\n1. Tóm tắt cho lãnh đạo: đúng 3 câu.\n2. Ba phát hiện chính, mỗi phát hiện có con số cụ thể.\n3. Hai việc đề xuất, có người phụ trách và thời hạn (chỗ nào chưa biết thì để [ngoặ", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Sếp khó tính vặn trước", "u": "cap-4.html#p-cap-4-5", "x": "Giờ bạn đóng vai Giám đốc tài chính rất khó tính, nổi tiếng hay vặn số liệu. Đọc báo cáo trên rồi hỏi mình 3 câu khó nhất mà ông ấy có thể hỏi trong cuộc họp. Chưa cần trả lời.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Sửa báo cáo để trả lời trước", "u": "cap-4.html#p-cap-4-6", "x": "Cảm ơn bạn. Giờ quay lại vai người viết, sửa báo cáo để trả lời trước cả 3 câu đó ngay trong bài, vẫn gói trong 1 trang. Câu nào chưa đủ số liệu để trả lời thì ghi rõ \"cần bổ sung\" và gợi ý mình nên lấy số liệu đó ở đâu.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Biến thành slide", "u": "cap-4.html#p-cap-4-7", "x": "Biến báo cáo vừa sửa thành bài trình chiếu 6 slide dạng trang web: chữ to dễ đọc, gọn và đẹp, có biểu đồ chi phí theo nhóm và theo tuần, có nút chuyển slide và dùng được phím mũi tên. Toàn bộ bằng tiếng Việt. Slide cuối là 2 đề xuất cần sếp quyết định.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Dàn ý slide cho PowerPoint", "u": "cap-4.html#p-cap-4-8", "x": "Viết giúp mình dàn ý 6 slide cho PowerPoint từ báo cáo này. Mỗi slide gồm: tiêu đề dưới 10 chữ, 3–4 gạch đầu dòng ngắn, gợi ý loại biểu đồ nếu cần (kèm số liệu để mình tự vẽ), và 2–3 câu ghi chú để mình nói khi trình bày.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Hỏi cách mang slide đi họp", "u": "cap-4.html#p-cap-4-9", "x": "Mình cần chiếu bộ slide này trên máy phòng họp và gửi sếp một bản PDF. Với công cụ mình đang dùng, cách nào đơn giản nhất? Hướng dẫn mình từng bước, như hướng dẫn người không rành máy tính.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Rà nguồn từng con số", "u": "cap-4.html#p-cap-4-10", "x": "Rà lại giúp mình: liệt kê mọi con số xuất hiện trong báo cáo và trên slide, ghi bên cạnh nguồn của nó (bảng nào phía trên, hay do bạn tính). Số nào do bạn tính thì ghi phép tính. Câu nào là nhận định của bạn chứ không phải dữ liệu thì đánh dấu.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Từ rà soát hợp đồng đến memo", "u": "cap-4.html#p-cap-4-11", "x": "Từ các điểm bất lợi bạn vừa tìm trong hợp đồng, viết giúp mình memo 1 trang gửi Ban Giám đốc: 3 rủi ro lớn nhất (kèm số Điều), mức độ rủi ro, đề xuất đàm phán lại từng điểm. Trước khi viết, hỏi mình 2 câu về người sẽ quyết định ký hợp đồng này. Xong làm 4 slide cho buổi họp duyệt ký.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Báo cáo tuổi nợ", "u": "cap-4.html#p-cap-4-12", "x": "Từ bảng công nợ mình vừa làm, chia khách hàng thành các nhóm: trong hạn, quá hạn 1–30 ngày, 31–60 ngày, trên 60 ngày. Viết báo cáo 1 trang gửi Kế toán trưởng: tổng nợ từng nhóm, 3 khách cần ưu tiên thu hồi, 2 đề xuất. Sau đó làm 4 slide có biểu đồ tuổi nợ.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Doanh số tháng thành bài họp sales", "u": "cap-4.html#p-cap-4-13", "x": "Đây là bảng doanh số tháng [tháng] theo nhân viên và khách hàng (đã che tên khách): [dán bảng]. Hỏi mình 3 câu về buổi họp sales sáng thứ Hai, rồi viết báo cáo 1 trang: ai vượt chỉ tiêu, khách nào mua ít đi, 2 việc cả nhóm cần làm tuần này. Xong làm 5 slide thật có năng lượng để mở đầu buổi họp.", "k": "prompt"}, {"t": "Số liệu thành báo cáo thành slide", "h": "Prompt: Nhật ký bảo trì thành báo cáo quý", "u": "cap-4.html#p-cap-4-14", "x": "Đây là nhật ký sự cố bảo trì quý [quý]: [dán bảng]. Tìm 3 hạng mục hỏng nhiều nhất, thời gian xử lý trung bình, chi phí từng hạng mục. Viết báo cáo 1 trang gửi Ban quản lý, có 2 đề xuất thay thế hoặc bảo dưỡng định kỳ. Rồi đóng vai trưởng ban quản lý khó tính, vặn mình 3 câu.", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Hỏi về góc làm việc riêng", "u": "cap-5.html#p-cap-5-1", "x": "Mình muốn tạo một \"góc làm việc riêng\" để bạn nhớ hướng dẫn và tài liệu của mình (kiểu Project hoặc Gem). Với công cụ mình đang dùng, tính năng đó tên là gì, nằm ở đâu, các bước tạo ra sao? Nếu bạn không chắc giao diện hiện tại, cứ nói thật để mình tự kiểm tra.", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Phỏng vấn rồi tự viết hướng dẫn", "u": "cap-5.html#p-cap-5-2", "x": "Mình muốn tạo một trợ lý nhớ cách mình làm báo cáo tuần. Bạn phỏng vấn mình từng câu một: mình là ai, làm việc này thế nào, thích kết quả ra sao, điều gì tuyệt đối không được làm. Hỏi đủ thì dừng, rồi tự viết giúp mình phần hướng dẫn để dán vào Project. Viết ngắn gọn, rõ ràng, dưới 300 chữ.", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Kiểm tra bạn ấy đã học bài", "u": "cap-5.html#p-cap-5-3", "x": "Trước khi làm việc, bạn cho mình biết: bạn hiểu mình sẽ nhờ bạn làm gì? Mẫu báo cáo có những mục nào? Giọng văn bạn rút ra từ 2 báo cáo cũ ra sao? Có điều gì trong hướng dẫn bạn thấy chưa rõ không?", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Số liệu tuần 40", "u": "cap-5.html#p-cap-5-4", "x": "Số liệu tuần 40:\nso lieu tuan 40 (28/9 - 4/10) - Ha ghi vội\n- ds tuan nay ~1,29 ty (CHUA tinh don truong Hoa Sen 85tr dang cho xuat hd)\n- don: 44 / kh moi: 7 (2 truong hoc, 1 van phong luat, con lai le)\n- thu no dc 1,02 ty. Phuc Loc tra them 40tr, con 80tr, qua han 40 ngay roi\n- Minh Quang: KH doi t", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Dạy thêm một điều", "u": "cap-5.html#p-cap-5-5", "x": "Báo cáo ổn rồi, nhưng từ nay mình muốn [phần Tóm tắt luôn mở đầu bằng % kế hoạch doanh số / mục Rủi ro xếp từ mức độ cao xuống thấp]. Viết lại toàn bộ phần hướng dẫn, đã thêm điều này, để mình dán đè vào Project.", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Gợi ý trợ lý cho riêng mình", "u": "cap-5.html#p-cap-5-6", "x": "Mình làm [nghề, vị trí]. Mỗi tuần mình hay lặp lại những việc như [kể 3–4 việc]. Ở nhà, mình [kể chút về gia đình, sở thích, việc hay phải lo]. Gợi ý cho mình 5 trợ lý nên tạo bằng Project hoặc Gem, mỗi trợ lý ghi: tên, việc nó làm, cần tải lên tài liệu gì, và câu mở lời mỗi lần dùng.", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Hỏi nguồn từng con số", "u": "cap-5.html#p-cap-5-7", "x": "Với mỗi con số trong báo cáo, ghi giúp mình nó lấy từ đâu: từ ghi chú tuần 40 mình vừa dán, từ báo cáo tuần trước trong phần tệp, hay do bạn tự tính. Số nào tự tính thì ghi phép tính.", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Trợ lý rà soát hợp đồng", "u": "cap-5.html#p-cap-5-8", "x": "Mình muốn tạo một trợ lý pháp chế rà soát hợp đồng mua bán theo đúng checklist của công ty (mình sẽ tải lên checklist và 2 hợp đồng mẫu đã che tên). Phỏng vấn mình từng câu: công ty thường ở vị thế bên mua hay bên bán, điều khoản nào bắt buộc phải có, rủi ro mức nào phải báo sếp, trình bày kết quả r", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Trợ lý báo cáo tháng", "u": "cap-5.html#p-cap-5-9", "x": "Mình muốn tạo trợ lý viết thuyết minh báo cáo quản trị tháng. Phỏng vấn mình từng câu: báo cáo gửi ai, gồm những khoản mục nào, chênh lệch so với kế hoạch bao nhiêu phần trăm thì phải giải thích, giọng văn ra sao. Xong viết hướng dẫn cho Project. Nhớ thêm quy tắc: không bịa số, số tự tính phải ghi p", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Trợ lý trả lời khách", "u": "cap-5.html#p-cap-5-10", "x": "Mình muốn tạo trợ lý soạn câu trả lời cho khách hàng đúng giọng công ty mình. Mình sẽ tải lên chính sách đổi trả, bảo hành và 10 câu trả lời mẫu mà sếp khen. Phỏng vấn mình từng câu về giọng điệu, cách xưng hô, điều gì không bao giờ hứa với khách. Xong viết hướng dẫn cho Project.", "k": "prompt"}, {"t": "Trợ lý biết nhớ việc", "h": "Prompt: Trợ lý báo cáo hiện trường", "u": "cap-5.html#p-cap-5-11", "x": "Mình muốn tạo trợ lý viết báo cáo ngày công trường từ ghi chú vội và ảnh chụp của mình. Mình sẽ tải lên mẫu báo cáo ngày và 2 báo cáo cũ. Phỏng vấn mình từng câu: báo cáo gửi ai, gồm mục nào, sự cố nào phải báo ngay. Xong viết hướng dẫn cho Project, nhớ đánh dấu [CẦN KIỂM TRA] với khối lượng tự suy ", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Hỏi thẳng bạn ấy", "u": "cap-6.html#p-cap-6-1", "x": "Nhóm mình hay quên hạn công việc. Mình muốn một công cụ nhỏ theo dõi tiến độ, cảnh báo trước hạn 5 ngày, nhưng không biết mô tả thế nào. Hỏi mình vài câu rồi làm luôn nhé. Giao diện tiếng Việt, hiện đại.", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Trả lời gộp và làm luôn", "u": "cap-6.html#p-cap-6-2", "x": "Mình trả lời gộp nhé: nhóm 5 người. Mỗi việc có tên việc, người phụ trách, ngày bắt đầu, hạn chót, trạng thái (Chưa làm / Đang làm / Xong). Tô đỏ việc quá hạn, cam việc còn 5 ngày trở xuống, xanh việc đã xong. Cần lọc theo người phụ trách, thanh % tiến độ cả dự án, nút xuất CSV để mở bằng Excel. Có ", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Nhờ bạn ấy chỉ cách thử", "u": "cap-6.html#p-cap-6-3", "x": "Chỉ mình 5 thao tác để thử xem app chạy đúng chưa. Mỗi thao tác ghi rõ: bấm vào đâu, và nếu đúng thì mình phải thấy gì.", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Thêm tính năng", "u": "cap-6.html#p-cap-6-4", "x": "Thêm cột mức ưu tiên (Cao / Trung bình / Thấp). Việc ưu tiên cao và sắp đến hạn xếp lên đầu.", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Báo lỗi như nói chuyện", "u": "cap-6.html#p-cap-6-5", "x": "Cái nút [Xuất CSV] bấm không ăn, bạn sửa giúp. Mình bấm vào thì [không có gì xảy ra / hiện thông báo: dán nội dung lỗi vào đây].", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Đổi giao diện", "u": "cap-6.html#p-cap-6-6", "x": "Đẹp hơn được không? Mình muốn kiểu [vui vẻ, nhiều màu, dành cho trẻ con / tối giản, tông xanh dương / chữ thật to cho người lớn tuổi].", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Gộp thành một file HTML", "u": "cap-6.html#p-cap-6-7", "x": "Gộp toàn bộ app thành một file HTML duy nhất, không cần cài đặt gì, mở được bằng trình duyệt trên máy tính và điện thoại. Hướng dẫn mình cách lưu file này về máy, từng bước, cho người không rành máy tính.", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Thử thách táo bạo", "u": "cap-6.html#p-cap-6-8", "x": "Mình có một ý tưởng hơi \"điên\": [mô tả công cụ hoặc trò chơi bạn muốn, càng cụ thể càng tốt: dành cho ai, để làm gì, vui hay nghiêm túc]. Mình không biết code. Hỏi mình vài câu rồi làm luôn bản đầu tiên. Mình sẽ cùng bạn sửa dần.", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Hỏi lại cách app tính", "u": "cap-6.html#p-cap-6-9", "x": "Giải thích cho mình bằng lời thường: app quyết định một việc là đỏ, cam hay xanh theo quy tắc nào? Việc có hạn đúng 5 ngày nữa thì màu gì? Hạn đúng hôm nay thì sao? Dữ liệu mình nhập được lưu ở đâu, tải lại trang có mất không, người khác có xem được không?", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Checklist rà soát hợp đồng", "u": "cap-6.html#p-cap-6-10", "x": "Mình làm pháp chế. Mình muốn một checklist rà soát hợp đồng mua bán dạng app: tick từng mục (thanh toán, giao nhận, chuyển rủi ro, bảo hành, phạt vi phạm, giải quyết tranh chấp…), mỗi mục có ô ghi chú và mức rủi ro, cuối cùng in ra một trang tóm tắt. Hỏi mình vài câu rồi làm luôn.", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Bảng tính khấu hao", "u": "cap-6.html#p-cap-6-11", "x": "Mình muốn một công cụ tính khấu hao tài sản cố định theo phương pháp đường thẳng: nhập nguyên giá, ngày bắt đầu, số năm sử dụng; ra bảng khấu hao từng tháng, từng năm, có biểu đồ giá trị còn lại, xuất được CSV. Hỏi mình vài câu trước khi làm, và ghi rõ công thức để mình kiểm tra.", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Công cụ lập báo giá", "u": "cap-6.html#p-cap-6-12", "x": "Mình muốn một công cụ lập báo giá: chọn sản phẩm từ danh sách, nhập số lượng, tự tính chiết khấu theo bậc số lượng, thuế VAT (mình tự nhập tỷ lệ), tổng tiền bằng số và bằng chữ, in ra một trang báo giá có chỗ cho logo công ty. Hỏi mình vài câu rồi làm luôn, dùng dữ liệu sản phẩm mẫu trước.", "k": "prompt"}, {"t": "Tự tạo công cụ không cần code", "h": "Prompt: Sổ theo dõi bảo trì", "u": "cap-6.html#p-cap-6-13", "x": "Mình quản lý vận hành toà nhà. Mình muốn một sổ theo dõi bảo trì dạng app: ghi sự cố theo hạng mục (thang máy, điện, nước, phòng cháy chữa cháy), ngày báo, ngày xử lý, người xử lý, chi phí; thống kê hạng mục hỏng nhiều nhất và thời gian xử lý trung bình; nhắc lịch bảo dưỡng định kỳ sắp tới. Hỏi mình", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Làm quen với thư mục", "u": "cap-7.html#p-cap-7-1", "x": "Trong thư mục này có số liệu tháng 9 của 5 chi nhánh. Chưa làm gì cả, bạn chỉ đọc qua từng file rồi kể lại cho mình: mỗi file của chi nhánh nào, trình bày kiểu gì, đơn vị tính là gì, có điểm gì bất thường cần lưu ý.", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Giao cả đầu việc", "u": "cap-7.html#p-cap-7-2", "x": "Đây là số liệu tháng 9 của 5 chi nhánh, mỗi nơi gửi một kiểu (có nơi tính bằng triệu đồng, có nơi viết thành đoạn văn). Mình cần báo cáo quản trị tháng gửi Giám đốc, lưu vào thư mục con tên \"output\":\n1. Một file Excel tổng hợp theo chi nhánh: kế hoạch doanh thu, doanh thu, % kế hoạch, giá vốn, chi p", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Duyệt kế hoạch có điều kiện", "u": "cap-7.html#p-cap-7-3", "x": "Kế hoạch ổn. Trước khi làm, bổ sung giúp mình: [file HCM có mấy sheet, bạn định dùng sheet nào và vì sao?]. Trong file Excel, thêm một sheet tên \"Nguon\" ghi nguồn của từng con số. Xong thì làm đi, gặp chỗ không chắc thì dừng lại hỏi mình.", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Hỏi tiến độ", "u": "cap-7.html#p-cap-7-4", "x": "Đang làm tới đâu rồi? Có file nào bạn đọc chưa được, hay con số nào bạn đang phân vân không?", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Tóm tắt thành phẩm", "u": "cap-7.html#p-cap-7-5", "x": "Tóm tắt cho mình: 3 file nằm ở đâu, mỗi file có gì, 5 con số quan trọng nhất, và những điểm bạn chưa chắc chắn. Đừng gửi email.", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Giao việc kiểu từng file", "u": "cap-7.html#p-cap-7-6", "x": "Mình cần làm báo cáo quản trị tháng 9 từ số liệu 5 chi nhánh, mỗi nơi gửi một kiểu. Mình sẽ gửi từng file một. Với mỗi file, bạn chỉ cần: đọc kỹ, lấy ra kế hoạch doanh thu, doanh thu, giá vốn, chi phí bán hàng, chi phí quản lý, lợi nhuận trước thuế, công nợ quá hạn và ghi chú đáng chú ý; quy hết về ", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Tổng hợp sau khi đủ 5 file", "u": "cap-7.html#p-cap-7-7", "x": "Đủ 5 chi nhánh rồi. Giờ làm giúp mình: (1) bảng tổng hợp theo chi nhánh và dòng toàn công ty; (2) báo cáo 1 trang cho Giám đốc: chi nhánh hụt kế hoạch, chi phí bất thường, công nợ quá hạn trên 60 ngày, việc cần Giám đốc quyết định; (3) email soạn sẵn gửi Giám đốc. Nếu công cụ cho phép, tạo file Exce", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Hỏi lại quy đổi đơn vị", "u": "cap-7.html#p-cap-7-8", "x": "Số liệu của chi nhánh Hải Phòng bạn quy đổi đơn vị thế nào? Chỉ cho mình dòng gốc trong file để mình đối chiếu.", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Hỏi lại các chỗ dễ sai khác", "u": "cap-7.html#p-cap-7-9", "x": "Thêm 3 câu nữa: (1) File HCM có mấy sheet, bạn lấy số ở sheet nào, vì sao? (2) File Cần Thơ dùng mã tài khoản: bạn hiểu mỗi mã là gì, và lấy kế hoạch doanh thu ở đâu? (3) Chi phí bán hàng HCM đã gồm các dòng chi tiết bên dưới chưa, bạn có cộng thêm lần nữa không?", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Bảng theo dõi hạn hồ sơ", "u": "cap-7.html#p-cap-7-10", "x": "Thư mục này có [30] hồ sơ vụ việc (Word, PDF, email đã lưu). Đọc từng hồ sơ, lập file Excel theo dõi: mã vụ việc, khách hàng (chỉ ghi mã), loại việc, mốc thời hạn sắp tới, người phụ trách, việc cần làm tiếp. Tô đỏ hồ sơ còn dưới 7 ngày đến hạn. Mỗi thời hạn ghi rõ lấy từ trang nào của hồ sơ nào. Trì", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Đối chiếu sao kê với sổ sách", "u": "cap-7.html#p-cap-7-11", "x": "Thư mục có sao kê ngân hàng tháng [tháng] và sổ chi tiết tiền gửi xuất từ phần mềm kế toán. Đối chiếu từng giao dịch: khớp, lệch số tiền, có ở sao kê mà không có ở sổ, và ngược lại. Lập file Excel kết quả và danh sách khoản cần giải trình. Không sửa file gốc. Hỏi mình trước nếu có quy ước ghi sổ bạn", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: So sánh báo giá nhà cung cấp", "u": "cap-7.html#p-cap-7-12", "x": "Thư mục có báo giá của 5 nhà cung cấp, mỗi nơi một định dạng (PDF, Excel, ảnh chụp). Gộp thành một bảng so sánh: mã hàng, đơn giá, đã gồm VAT chưa, chiết khấu, thời gian giao, bảo hành, điều kiện thanh toán. Đánh dấu chỗ các báo giá không cùng điều kiện để so sánh. Viết thêm 1 trang đề xuất chọn nhà", "k": "prompt"}, {"t": "Giao cả đầu việc cho AI agent", "h": "Prompt: Báo cáo tuần từ nhiều công trường", "u": "cap-7.html#p-cap-7-13", "x": "Thư mục có báo cáo ngày trong tuần của [3] công trường, mỗi đội viết một kiểu. Tổng hợp thành báo cáo tuần: khối lượng hoàn thành so với kế hoạch, nhân lực, sự cố an toàn, vật tư thiếu, việc cần Ban chỉ huy quyết định. Lưu thành file Word và một bảng Excel. Ghi rõ nguồn từng con số. Hỏi mình trước, ", "k": "prompt"}, {"t": "Bản đồ công cụ AI", "h": "Prompt: Thử cùng một việc ở hai bạn", "u": "cong-cu.html#p-cong-cu-1", "x": "Mình đang thử so sánh hai công cụ AI cho cùng một việc. Việc của mình là: [mô tả việc]. Bối cảnh: [mình là ai, làm ở đâu, kết quả dùng để làm gì].\nLàm giúp mình, rồi cuối câu trả lời tự chấm bài của bạn theo 3 tiêu chí: đúng ý, dễ dùng ngay, có chỗ nào cần mình kiểm tra lại.", "k": "prompt"}, {"t": "Bản đồ công cụ AI", "h": "Prompt: Hỏi thẳng: việc này nên dùng công cụ gì?", "u": "cong-cu.html#p-cong-cu-2", "x": "Mình cần [mô tả việc], thường làm [mỗi ngày / mỗi tuần / mỗi tháng], đầu vào là [loại file hoặc thông tin]. Theo bạn mình nên dùng loại công cụ AI nào, tính năng nào (ví dụ Project, upload file, Deep Research, agent)? Giải thích ngắn vì sao.\nNếu bạn không chắc tính năng hay gói hiện tại của công cụ ", "k": "prompt"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Prompt: Mẫu giao việc như giao cho đồng nghiệp", "u": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-1", "x": "Mình cần [việc gì], để [dùng vào đâu / gửi cho ai].\n[Những gì một đồng nghiệp mới cần biết: ai, chuyện gì, thế nào là tốt.]\nCứ [làm nhanh gọn thôi / làm thật kỹ, không cần vội].\nXong thì tự kiểm tra bằng cách [___], rồi báo mình đã kiểm gì, chưa kiểm được gì.\nThiếu gì thì hỏi mình trước nhé.", "k": "prompt"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Prompt: Biến câu nhờ quen thuộc thành kiểu đồng nghiệp", "u": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-2", "x": "Đây là câu mình hay nhờ AI: \"[dán câu của bạn]\". Viết lại giúp mình theo kiểu giao việc cho một đồng nghiệp giỏi: nói rõ mình muốn gì, bỏ bao nhiêu công sức, và kiểm tra thế nào. Giải thích ngắn vì sao bản mới tốt hơn.", "k": "prompt"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Prompt: Rà soát hợp đồng như giao cho đồng nghiệp", "u": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-3", "x": "Mình cần rà soát hợp đồng này cho phía [bên mua / bên bán], để báo sếp trước khi ký vào [ngày]. Thế nào là tốt: chỉ ra điều khoản bất lợi, rủi ro lớn nhất, và đề xuất sửa. Cứ làm kỹ. Mỗi ý trích nguyên văn kèm số Điều; ý nào là suy luận thì ghi rõ. Thiếu gì thì hỏi mình trước.", "k": "prompt"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Prompt: Thuyết minh biến động chi phí", "u": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-4", "x": "Mình cần đoạn thuyết minh biến động chi phí tháng [X] so với tháng trước, để đưa vào báo cáo gửi Kế toán trưởng. Số liệu ở bảng dưới. Làm vừa phải, ngắn gọn. Xong thì tự cộng lại các khoản, đối chiếu với dòng tổng, và báo mình chỗ nào chưa khớp.\n[dán bảng số liệu đã che tên]", "k": "prompt"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Prompt: Thư chào hàng cho khách cũ", "u": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-5", "x": "Mình cần thư chào hàng sản phẩm [tên] cho khách cũ [mô tả khách], mục tiêu là hẹn được một cuộc gọi 15 phút. Giọng thân thiện, dưới 120 chữ. Làm 2 phương án. Đánh dấu mọi con số, ưu đãi, cam kết trong thư để mình kiểm tra lại, mình chỉ được hứa [điều được phép].", "k": "prompt"}, {"t": "Giao việc như giao cho đồng nghiệp", "h": "Prompt: Xếp lại lịch thi công khi bị trễ", "u": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-6", "x": "Mình cần xếp lại lịch thi công tuần tới vì [hạng mục] bị trễ 3 ngày, để gửi các tổ đội chiều nay. Ràng buộc: [danh sách]. Cứ làm kỹ, thử vài cách sắp xếp rồi chọn cách ít ảnh hưởng nhất. Xong thì tự soát lại xem có tổ nào bị xếp trùng ca hoặc thiếu vật tư không, báo mình đã kiểm gì.", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Mở đầu cuộc nói chuyện bằng giọng", "u": "giong-noi.html#p-giong-noi-1", "x": "Mình muốn [nghĩ cho rõ chuyện ___]. Cuối buổi mình cần [3 ý chính và 1 bước tiếp theo]. Mình có [10 phút], bạn trả lời ngắn thôi. Trước khi kết thúc, nhắc lại các tên, con số mình đã nói và tóm tắt thành văn bản. Thiếu gì thì hỏi mình, từng câu một.", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Nghĩ thành tiếng", "u": "giong-noi.html#p-giong-noi-2", "x": "Mình đang rối chuyện [___]. Mình sẽ kể lan man, bạn nghe hết, đừng vội khuyên. Sau đó hỏi mình từng câu ngắn. Khi mình nói \"chốt đi\", tóm lại: điều mình thật sự lo, các lựa chọn, và một bước nhỏ làm được ngay hôm nay.", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Đóng vai người khó nói chuyện", "u": "giong-noi.html#p-giong-noi-3", "x": "Mình sắp phải [xin sếp tăng lương / nhắc khách quen trả nợ quá hạn / báo khách là hàng về trễ]. Bạn đóng vai [sếp / khách hàng], tính cách [bận rộn, hay cắt ngang]. Đừng dễ dãi, phản ứng như người thật. Khi mình nói \"dừng\", ra khỏi vai và góp ý thẳng 3 chỗ nên nói khác, kèm câu thay thế.", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Luyện tiếng Anh công việc", "u": "giong-noi.html#p-giong-noi-4", "x": "Mình muốn luyện tiếng Anh để [họp online với đối tác nước ngoài], trình độ [nói được câu đơn giản]. Bạn đóng vai [đối tác], nói chậm, mỗi lượt một câu hỏi. Mình sai thì đừng ngắt ngay. Cứ sau 5 lượt, dừng lại, nói bằng tiếng Việt 2 lỗi đáng sửa nhất và cách nói tự nhiên hơn.", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Ý tưởng lộn xộn thành việc cần làm", "u": "giong-noi.html#p-giong-noi-5", "x": "Mình sẽ đọc một mạch, hơi lộn xộn, bạn nghe hết rồi mới làm. [đọc ý tưởng]. Xong, xếp lại thành 3 nhóm: việc cần làm (ai làm, hạn nào nếu mình có nói), ý tưởng để nghĩ thêm, câu cần hỏi người khác. Chỗ nào không rõ, ghi [CHƯA RÕ], đừng tự đoán.", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Nghe mình tập phát biểu", "u": "giong-noi.html#p-giong-noi-6", "x": "Mình sắp phát biểu về [chủ đề] khoảng [3 phút] trước [ai nghe]. Mình nói thử một lượt, bạn đừng ngắt. Xong, góp ý thẳng: câu mở có giữ được người nghe không, chỗ nào khó hiểu khi chỉ nghe, câu kết có đọng lại gì không. Rồi sửa giúp mình 2 đoạn yếu nhất.", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Nhắc lại cho mình kiểm", "u": "giong-noi.html#p-giong-noi-7", "x": "Nhắc lại mọi tên người, con số, ngày tháng mình vừa nói để mình kiểm. Trong lời khuyên của bạn, phần nào mình nên kiểm tra lại với tài liệu hoặc người có chuyên môn?", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Tập buổi tư vấn khó", "u": "giong-noi.html#p-giong-noi-8", "x": "Bạn đóng vai giám đốc doanh nghiệp nhỏ, nóng ruột về [rủi ro trong hợp đồng thuê kho], hỏi dồn mình. Khi mình nói \"dừng\", chỉ ra chỗ mình dùng thuật ngữ khó hiểu và chỗ mình lỡ hứa chắc quá.", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Tập giải trình chênh lệch", "u": "giong-noi.html#p-giong-noi-9", "x": "Mình sắp giải trình vì chi phí [tiếp khách] quý này vượt kế hoạch [20%]. Bạn đóng vai giám đốc kỹ tính, hỏi vặn từng con số. Sau 5 lượt, chỉ ra câu nào mình nói dài dòng, chỗ nào cần mang số liệu chứng minh.", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Luyện gọi chào hàng", "u": "giong-noi.html#p-giong-noi-10", "x": "Bạn đóng vai trưởng phòng hành chính đang bận, nhận cuộc gọi chào hàng [thiết bị văn phòng] của mình. Từ chối mình 2 lần bằng 2 lý do khác nhau. Xong, gợi ý 2 câu mở đầu tốt hơn câu của mình.", "k": "prompt"}, {"t": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "h": "Prompt: Đi một vòng, ra báo cáo ngày", "u": "giong-noi.html#p-giong-noi-11", "x": "Mình vừa kiểm tra [kho / công trường], giờ đọc lại những gì thấy. Viết thành báo cáo ngày: hạng mục đạt, vấn đề phát hiện, việc cần xử lý (ai, hạn nào). Chỗ nào mình không nói, ghi [CẦN BỔ SUNG].", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Viết đúng giọng mình theo 3 điều", "u": "giong-van.html#p-giong-van-1", "x": "Mình cần viết [loại văn bản] gửi [ai] để [mục đích], đúng giọng mình theo bản mô tả giọng văn và bảng thuật ngữ bên dưới.\nĐây là [bản nháp nhanh / bản gửi thật, làm kỹ].\nViết xong, tự soát theo bản mô tả và bảng thuật ngữ, rồi báo mình đã sửa những câu nào.\nThiếu thông tin gì thì hỏi mình trước nhé.", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Rút ra bản mô tả giọng văn", "u": "giong-van.html#p-giong-van-2", "x": "Dưới đây là [4] bài mình từng viết (đã che tên và số). Viết \"bản mô tả giọng văn\" dưới 250 chữ: độ dài câu, cách xưng hô, cách mở và kết, từ mình hay dùng, từ mình không bao giờ dùng, mức trang trọng. Mỗi điểm kèm một câu trích từ bài của mình. Điểm nào bạn đoán thì ghi rõ.\n\n[Dán các bài viết]", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Gói gọn để dán vào cài đặt", "u": "giong-van.html#p-giong-van-3", "x": "Rút gọn bản mô tả ở trên thành các quy tắc ngắn dưới 150 chữ, mở đầu bằng \"Khi viết thay mình:\", để mình dán vào [hướng dẫn tuỳ chỉnh / Project]. Giữ 3 câu ví dụ tiêu biểu nhất.", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Lập bảng thuật ngữ công ty", "u": "giong-van.html#p-giong-van-4", "x": "Lập giúp mình bảng thuật ngữ cho văn bản gửi khách, 3 cột: Dùng · Không dùng · Ghi chú. Quy ước sẵn có: gọi \"khách hàng\", không gọi \"quý khách\"; viết \"Sao Mai\", không viết \"SaoMai\"; [tên sản phẩm viết đúng]. Đọc [3 email mẫu] dưới đây, đề xuất thêm từ nên thống nhất, rồi hỏi mình duyệt từng dòng.", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Một thông điệp cho 3 người đọc", "u": "giong-van.html#p-giong-van-5", "x": "Mình cần báo: [ví dụ: lô hàng giao khách chậm 5 ngày vì nhà cung cấp giao thiếu]. Viết 3 bản theo giọng của mình:\n1. Cho sếp: 3–4 dòng, ảnh hưởng, phương án, điều cần sếp quyết.\n2. Cho khách: xin lỗi chân thành, hẹn ngày mới rõ ràng, không đổ lỗi.\n3. Cho đồng nghiệp kho: tin nhắn ngắn, ai làm gì, tr", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Khử mùi AI", "u": "giong-van.html#p-giong-van-6", "x": "Đọc bản nháp dưới đây, chỉ ra mọi chỗ \"nghe như máy viết\": sáo ngữ, câu văn dịch, liệt kê vô hồn, mở và kết chung chung, kèm lý do. Rồi viết lại theo bản mô tả giọng văn của mình, không thêm ý, không bỏ thông tin.\n\n[Dán bản nháp]", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Chấm bài theo giọng văn", "u": "giong-van.html#p-giong-van-7", "x": "Chấm bài dưới đây theo bản mô tả giọng văn và bảng thuật ngữ của mình, thang 10 điểm. Mỗi điểm trừ: trích câu, nói lệch quy tắc nào, đề xuất câu sửa. Đừng sửa chỗ đã đúng giọng chỉ vì bạn thích cách viết khác.\n\n[Dán bài viết]", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Soi lỗi bắt chước quá đà", "u": "giong-van.html#p-giong-van-8", "x": "So bản vừa viết với các bài gốc của mình. Những cụm từ đặc trưng của mình xuất hiện bao nhiêu lần trong bài gốc, bao nhiêu lần trong bản mới? Chỗ nào dùng dày hơn hẳn thì viết lại cho tự nhiên.", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Giọng thư tư vấn của hãng", "u": "giong-van.html#p-giong-van-9", "x": "Đây là 3 thư tư vấn của hãng mình (đã che tên khách và vụ việc). Rút ra bản mô tả giọng văn: cách mở đầu, cách dẫn chiếu điều luật, mức độ khẳng định khi kết luận. Rồi viết lại đoạn nháp dưới đây theo giọng đó, giữ nguyên mọi dẫn chiếu.", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Thống nhất tên khoản mục", "u": "giong-van.html#p-giong-van-10", "x": "Từ 3 bản thuyết minh báo cáo quản trị cũ dưới đây, lập bảng: mỗi khoản mục đang được gọi bằng những tên nào, nên thống nhất tên nào. Rồi soát bản nháp tháng này, chỉ ra chỗ gọi tên lệch bảng.", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Giọng CSKH của công ty", "u": "giong-van.html#p-giong-van-11", "x": "Đây là 5 câu trả lời khách mà sếp khen (đã che tên). Rút ra giọng chăm sóc khách hàng của công ty, rồi trả lời tình huống sau theo giọng đó, một bản email, một bản tin nhắn Zalo: [mô tả tình huống].", "k": "prompt"}, {"t": "Viết đúng giọng của bạn và của công ty", "h": "Prompt: Thông báo đúng giọng công trường", "u": "giong-van.html#p-giong-van-12", "x": "Viết lại thông báo dưới đây cho anh em công trường đọc trên điện thoại: câu ngắn, ai làm gì, trước giờ nào. Giữ giọng như 2 thông báo cũ mình dán kèm. Phần an toàn giữ nguyên ý, không làm mềm.", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Nhờ gia sư theo 3 điều", "u": "hoc-nhanh.html#p-hoc-nhanh-1", "x": "Mình muốn học [chủ đề] để [dùng vào việc gì]. Hiện mình [đã biết gì, chưa biết gì].\nMình có [15 phút mỗi tối trong 2 tuần], muốn học chắc phần cốt lõi.\nMỗi lần giải thích một ý ngắn, rồi hỏi mình một câu để kiểm tra. Mình sai thì gợi ý, đừng đưa đáp án ngay.\nCần biết thêm gì về mình thì hỏi trước nh", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Giải thích theo 3 mức", "u": "hoc-nhanh.html#p-hoc-nhanh-2", "x": "Giải thích giúp mình [chủ đề, ví dụ: báo cáo lưu chuyển tiền tệ] theo 3 mức:\n1. Cho người mới: khoảng 5 câu, một ví dụ đời thường, không thuật ngữ.\n2. Cho người đã biết chút ít: các khái niệm chính liên quan với nhau thế nào.\n3. Cho chuyên gia: điểm tinh tế, chỗ người ta hay hiểu sai.\nXong thì hỏi m", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Hỏi mình, đừng đưa đáp án", "u": "hoc-nhanh.html#p-hoc-nhanh-3", "x": "Mình muốn hiểu [câu hỏi, ví dụ: vì sao công ty có lãi mà vẫn thiếu tiền]. Dẫn dắt mình bằng câu hỏi, mỗi lần một câu, để mình tự suy ra. Mình sai hoặc bí thì gợi ý thêm chút ít; chỉ khi mình nói \"chịu\" mới giải thích. Cuối buổi, tóm tắt 3 điều mình đã tự tìm ra.", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Kèm con học, không làm hộ", "u": "hoc-nhanh.html#p-hoc-nhanh-4", "x": "Con mình học lớp [___], đang bí bài này: [chép đề hoặc gửi ảnh]. Đừng giải hộ. Gợi ý từng bước nhỏ để con tự làm. Con nghĩ đúng hướng thì khen cách nghĩ, không chỉ khen đáp án. Nói bằng lời hợp với tuổi con.", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Ra đề và chấm điểm", "u": "hoc-nhanh.html#p-hoc-nhanh-5", "x": "Mình vừa học xong [chủ đề]. Ra 5 câu từ dễ đến khó, ít nhất 2 câu là tình huống thật trong nghề [nghề của mình]. Đưa từng câu, chờ mình trả lời rồi chấm: đúng, đúng một phần hay sai, vì sao. Cuối cùng nói mình cần ôn phần nào.", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Lộ trình 2 tuần", "u": "hoc-nhanh.html#p-hoc-nhanh-6", "x": "Sau 2 tuần, mình muốn [kỹ năng, ví dụ: dùng thành thạo SUMIFS và PivotTable / hiểu một quy định mới của ngành]. Mỗi ngày mình có [20] phút. Hỏi trình độ của mình trước, rồi lập lộ trình 14 ngày: mỗi ngày học gì, làm bài tập nhỏ gì. Ngày 14 là bài \"thi cuối kỳ\" sát với việc thật: [mô tả việc].", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Đọc xong, hỏi mình", "u": "hoc-nhanh.html#p-hoc-nhanh-7", "x": "Mình vừa tải lên [tên tài liệu], cần hiểu đủ để [áp dụng vào việc gì]. Cho mình dàn ý 5–7 ý chính trước. Đọc xong phần nào mình sẽ báo, bạn hỏi mình 3 câu về phần đó. Khi chấm, trích đúng điều, mục hoặc trang để mình đối chiếu.", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Chỉ nguồn để mình đối chiếu", "u": "hoc-nhanh.html#p-hoc-nhanh-8", "x": "Trong phần bạn vừa giải thích, ý nào là kiến thức nền ít thay đổi, ý nào có thể đã thay đổi theo thời gian? Với nhóm sau, chỉ mình nguồn chính thức để đối chiếu và nói bạn chắc đến đâu. Không chắc thì nói thẳng.", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Văn bản mới khác gì văn bản cũ", "u": "hoc-nhanh.html#p-hoc-nhanh-9", "x": "Mình tải lên [văn bản mới] và [văn bản cũ]. Chỉ dựa vào hai văn bản này, liệt kê điểm thay đổi ảnh hưởng tới [loại hợp đồng của mình], trích số điều. Rồi cho mình 3 tình huống thử áp dụng và nhận xét câu trả lời của mình.", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Đọc báo cáo tài chính từng bước", "u": "hoc-nhanh.html#p-hoc-nhanh-10", "x": "Mình tải lên báo cáo tài chính của [khách hàng] (đã che tên) để xem họ có trả nợ nổi không. Dạy mình từng bước trên chính báo cáo này: xem chỉ tiêu nào, tính chỉ số nào, dấu hiệu nào đáng lo. Mỗi bước hỏi mình một câu.", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Hiểu ngành của khách trong 30 phút", "u": "hoc-nhanh.html#p-hoc-nhanh-11", "x": "Tuần sau mình gặp khách ngành [ngành] mà mình chưa biết gì. Giúp mình nắm: họ kiếm tiền thế nào, lo nhất điều gì, hay dùng từ chuyên môn nào. Rồi đóng vai khách hỏi mình 5 câu và chấm điểm.", "k": "prompt"}, {"t": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "h": "Prompt: Quy trình thành câu hỏi kiểm tra", "u": "hoc-nhanh.html#p-hoc-nhanh-12", "x": "Mình tải lên [quy trình vận hành thiết bị]. Giải thích theo 3 mức, rồi soạn 10 câu hỏi nhanh kèm đáp án để kiểm tra anh em trước ca. Đánh dấu chỗ liên quan an toàn để mình đối chiếu văn bản gốc và hỏi cán bộ kỹ thuật.", "k": "prompt"}, {"t": "Hỏi đáp thường gặp", "h": "Prompt: Bạn giúp được mình việc gì?", "u": "hoi-dap.html#p-hoi-dap-1", "x": "Mình làm [nghề / vị trí] ở [loại công ty]. Mỗi ngày mình hay làm [kể 3–5 việc]. Bạn giúp được mình những việc gì? Gợi ý 10 việc, xếp từ dễ đến khó, mỗi việc kèm một câu mở lời để mình thử ngay.", "k": "prompt"}, {"t": "Hỏi đáp thường gặp", "h": "Prompt: Hỏi thẳng về chuyện học AI", "u": "hoi-dap.html#p-hoi-dap-2", "x": "Mình là [nghề], đang tự học dùng AI cho công việc, hiện đã biết [kể những gì đã biết]. Mình đang vướng chỗ này: [câu hỏi]. Bạn trả lời ngắn gọn, thực tế, rồi gợi ý 1 việc nhỏ mình làm thử được ngay hôm nay.", "k": "prompt"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Prompt: Biên bản họp: câu mẫu", "u": "hop-hanh.html#p-hop-hanh-1", "x": "Đây là ghi chú vội cuộc họp [tên], ngày [___], thành phần [___]. Viết biên bản gửi [cả nhóm / sếp], gọn 1 trang: điều đã thống nhất, việc cần làm (ai, việc gì, hạn), vấn đề còn treo. Làm nhanh, không cần văn hoa.\nCách kiểm: chỉ ghi điều có trong ghi chú; chưa chốt thì để ở \"vấn đề còn treo\"; không r", "k": "prompt"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Prompt: Chương trình họp và tập phản biện", "u": "hop-hanh.html#p-hop-hanh-2", "x": "Thứ Tư tới phòng mình họp 60 phút về triển khai phần mềm kế toán mới, 5 người từ tài chính, kế toán, IT, kho. Mục tiêu: chốt ngày chạy chính thức, kế hoạch chuyển dữ liệu, lịch đào tạo. Soạn chương trình họp và nửa trang đọc trước cho từng người. Xong, đóng vai Kế toán trưởng rất cẩn trọng, hỏi mình", "k": "prompt"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Prompt: Ghi chú vội thành biên bản", "u": "hop-hanh.html#p-hop-hanh-3", "x": "Viết ghi chú vội này thành biên bản gửi cả nhóm. Chỉ ghi điều có trong ghi chú; ý chưa chốt để ở \"vấn đề còn treo\"; chỗ không rõ ghi [CẦN XÁC NHẬN].\n\nhop trien khai PM ke toan moi, 14/10, a Minh chu tri\ntp: a Minh GDTC, c Lan KTT, a Tuan IT, c Ngoc cong no, a Phong kho\n- go-live 1/1/2027?? a Minh mu", "k": "prompt"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Prompt: Bảng việc và email sau họp", "u": "hop-hanh.html#p-hop-hanh-4", "x": "Từ biên bản này, lập bảng việc cần làm: Việc, Người phụ trách, Hạn. Chưa có người hay hạn thì để trống và đánh dấu, đừng tự gán. Rồi soạn email gửi cả nhóm: 3 điểm chính, bảng việc, và mời mọi người phản hồi trước [hạn] nếu ghi nhận chưa đúng.", "k": "prompt"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Prompt: Tóm tắt khi mình vắng mặt", "u": "hop-hanh.html#p-hop-hanh-5", "x": "Mình vắng [cuộc họp / chuỗi email] này, mình là [vai trò]. Đọc nội dung bên dưới (đã che tên): tóm tắt 5 dòng; điều gì đã chốt, ai chốt; việc nào giao cho mình; quyết định nào đang chờ mình, kèm 2–3 phương án. Chỗ các bên nói khác nhau thì chỉ ra, trích câu gốc ngắn.\n[dán nội dung]", "k": "prompt"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Prompt: Soát biên bản với ghi chú gốc", "u": "hop-hanh.html#p-hop-hanh-6", "x": "Soát biên bản với ghi chú gốc: mỗi câu về người nhận việc, hạn, con số, quyết định là \"có trong ghi chú\", \"suy luận\" hay \"không có căn cứ\"? Sửa để chỉ giữ điều có căn cứ.", "k": "prompt"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Prompt: Biên bản làm việc với đối tác", "u": "hop-hanh.html#p-hop-hanh-7", "x": "Từ ghi chú buổi làm việc với [đối tác] về [vụ việc] (đã che tên), soạn biên bản: ý kiến từng bên, điểm đã thống nhất, điểm còn bảo lưu. Giữ đúng ý, không diễn giải. Không rõ ai nói thì ghi [CẦN XÁC NHẬN].", "k": "prompt"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Prompt: Việc sau họp khoá sổ", "u": "hop-hanh.html#p-hop-hanh-8", "x": "Lập bảng việc từ ghi chú họp khoá sổ tháng [tháng]: việc, người phụ trách, hạn, phải chờ việc nào trước. Sắp theo thứ tự làm. Chưa có người hoặc hạn thì ghi [CẦN XÁC NHẬN].", "k": "prompt"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Prompt: Email sau buổi gặp khách", "u": "hop-hanh.html#p-hop-hanh-9", "x": "Từ ghi chú buổi gặp khách hôm nay (đã che tên), soạn email cảm ơn kèm tóm tắt: nhu cầu khách nêu, điều đã thống nhất, bước tiếp theo của mỗi bên kèm hạn. Giọng thân thiện. Không hứa thêm điều gì ngoài ghi chú.", "k": "prompt"}, {"t": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "h": "Prompt: Biên bản giao ban công trường", "u": "hop-hanh.html#p-hop-hanh-10", "x": "Từ ghi chú giao ban công trường [tên dự án] sáng nay, soạn biên bản theo hạng mục: tiến độ so với kế hoạch, vướng mắc, việc cần làm (ai, hạn), lưu ý an toàn. Chỗ không rõ thì ghi [CẦN XÁC NHẬN].", "k": "prompt"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Prompt: Mình đang ở tầng nào của phễu?", "u": "khoang-cach.html#p-khoang-cach-1", "x": "Mình làm [nghề], dùng AI kiểu: [mô tả ngắn, ví dụ: vài lần một tuần, hỏi đáp, viết email]. Theo phễu của Karpathy (6 tỷ người gần như chưa dùng, 1–2 tỷ dùng thỉnh thoảng bản miễn phí, khoảng 20 triệu dùng bản mạnh nhất cho việc chuyên môn), bạn đoán mình đang ở đâu? Gợi ý 3 việc cụ thể trong công vi", "k": "prompt"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Prompt: Kế hoạch 30 ngày của riêng mình", "u": "khoang-cach.html#p-khoang-cach-2", "x": "Mình muốn trong 30 ngày tới dùng AI sâu hơn trong công việc [nghề, vị trí]. Mỗi tuần mình có khoảng [số] phút. Lên giúp mình kế hoạch 4 tuần, mỗi tuần một việc thật trong công việc của mình, việc sau lớn hơn việc trước, tuần cuối là giao một việc nhiều bước. Mỗi tuần ghi rõ: việc gì, câu nhờ mẫu, và", "k": "prompt"}, {"t": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "h": "Prompt: Dạy lại cho người thân", "u": "khoang-cach.html#p-khoang-cach-3", "x": "Mình muốn chỉ cho [bố mẹ / con / đồng nghiệp] cách dùng AI lần đầu. Họ [mô tả: tuổi, nghề, hay lo điều gì]. Gợi ý cho mình 3 việc đầu tiên thật hợp với họ, câu nói mở đầu để họ không ngại, và một điều an toàn họ cần nhớ.", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Văn bản mới có đụng tới mình không?", "u": "mot-ngay.html#p-mot-ngay-1", "x": "Mình làm pháp chế cho một công ty [phân phối thiết bị văn phòng]. Đây là văn bản mới lấy từ nguồn chính thức. Tóm giúp mình trong 5 dòng: quy định gì, hiệu lực khi nào, công ty mình phải làm gì khác. Văn bản không nói rõ thì ghi \"không đề cập\", đừng đoán.\n\n[Dán văn bản]", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Rà phụ lục, nói rõ 3 điều", "u": "mot-ngay.html#p-mot-ngay-2", "x": "Mình đính kèm hợp đồng gốc và phụ lục gia hạn (đã che tên, số tiền). Công ty mình là bên mua.\nMình muốn: các điểm bất lợi cho bên mua, xếp theo rủi ro, mỗi điểm kèm một câu đề nghị sửa để nói trong cuộc họp.\nCông sức: làm kỹ, gọn trong một trang.\nKiểm tra: trích nguyên văn, ghi số điều, đối chiếu vớ", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Căn cứ đâu?", "u": "mot-ngay.html#p-mot-ngay-3", "x": "Bạn nói điều khoản [___] \"trái quy định\". Văn bản nào, điều mấy? Phần nào bạn chắc chắn, phần nào là suy luận? Không chắc thì nói thẳng, mình sẽ tự tra nguồn chính thức.", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Giải thích cho người không chuyên", "u": "mot-ngay.html#p-mot-ngay-4", "x": "Đồng nghiệp kinh doanh hỏi mình: khách muốn thêm điều khoản \"[dán điều khoản]\", có nên đồng ý không. Viết giúp mình tin nhắn dưới 120 chữ, lời thường: rủi ro chính, đề nghị sửa thế nào, và một câu đồng nghiệp nói thẳng được với khách.", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Công thức tính quá hạn", "u": "mot-ngay.html#p-mot-ngay-5", "x": "Bảng công nợ của mình: cột A mã khách hàng, B ngày hoá đơn, C số tiền, D ngày đã trả (trống nếu chưa trả). Hạn 30 ngày. Viết công thức cho cột E \"Số ngày quá hạn\" và F \"Tình trạng\" (Đã trả, Trong hạn, Quá hạn, Quá hạn trên 60 ngày), giải thích dễ hiểu. Excel của mình dùng dấu [\";\" / \",\"].", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Thuyết minh biến động, nói rõ 3 điều", "u": "mot-ngay.html#p-mot-ngay-6", "x": "Đính kèm chi phí tháng 8 và tháng 9 theo khoản mục (đã bỏ tên nhà cung cấp).\nMình muốn: thuyết minh 5 khoản biến động lớn nhất, mỗi khoản 2–3 câu, có số tuyệt đối và phần trăm.\nCông sức: nhanh gọn, bản nháp nội bộ.\nKiểm tra: cộng tổng từng tháng, so với dòng tổng trong file. Không rõ nguyên nhân thì", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Mỗi con số lấy ở đâu?", "u": "mot-ngay.html#p-mot-ngay-7", "x": "Liệt kê giúp mình mọi con số trong đoạn thuyết minh: số nào lấy từ file (dòng nào, cột nào), số nào bạn tính ra (ghi cách tính), số nào đã làm tròn.", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Quy chế thành hướng dẫn một trang", "u": "mot-ngay.html#p-mot-ngay-8", "x": "Đây là quy chế công tác phí của công ty mình. Viết hướng dẫn một trang cho nhân viên: các bước hoàn ứng, giấy tờ, hạn nộp, và mục \"Hay bị trả lại vì\" dựa trên các lỗi mình kể: [___]. Quy chế không nói thì ghi [HỎI KẾ TOÁN], đừng đoán.\n\n[Dán đoạn quy chế]", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Tập trước cuộc gặp", "u": "mot-ngay.html#p-mot-ngay-9", "x": "Lát nữa mình gặp [phòng hành chính một trường tư thục] lần đầu, họ cần [bàn ghế cho 10 phòng học]. Bạn đóng vai người phụ trách mua sắm, hỏi mình 3 câu khó nhất, từng câu một. Mình trả lời xong thì góp ý ngắn.", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Báo giá, nói rõ 3 điều", "u": "mot-ngay.html#p-mot-ngay-10", "x": "Mình cần báo giá cho [Trường A]: [danh mục, số lượng, đơn giá, chiết khấu được duyệt, VAT, thời gian giao].\nMình muốn: bảng báo giá và thư chào hàng ngắn nhấn vào [điều khách quan tâm nhất], gửi chiều nay.\nCông sức: kỹ ở phần tính toán, gọn ở phần thư.\nKiểm tra: tính tổng tiền bằng hai cách, báo mìn", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Chỗ nào bạn tự thêm?", "u": "mot-ngay.html#p-mot-ngay-11", "x": "Liệt kê mọi con số, thời hạn, bảo hành, ưu đãi trong báo giá và thư. Cái nào lấy từ thông tin mình đưa, cái nào bạn tự thêm? Xoá phần tự thêm, gửi lại bản sạch.", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Cập nhật cuối ngày", "u": "mot-ngay.html#p-mot-ngay-12", "x": "Hôm nay: [gặp Trường A, đã gửi báo giá; Khách B hẹn thanh toán thứ Sáu]. Ghi nhận giúp mình theo mẫu báo cáo tuần. Việc sáng mai cần nhắc thì liệt kê riêng.", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Bảng trắng thành việc của từng tổ", "u": "mot-ngay.html#p-mot-ngay-13", "x": "Đây là ảnh bảng trắng giao ca ở công trường. Chép lại thành danh sách việc của từng tổ: việc gì, ai phụ trách, xong trước mấy giờ. Chữ nào bạn đọc không chắc thì đánh dấu [?].", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Biên bản hàng về thiếu, móp", "u": "mot-ngay.html#p-mot-ngay-14", "x": "Đây là ảnh lô [thanh giằng kệ] vừa giao và phiếu giao hàng (đã che tên, số điện thoại). Mình đếm được [___] thanh, [___] thanh móp. Soạn biên bản ghi nhận: số theo phiếu, số thực nhận, hư hỏng thấy trong ảnh, đề nghị của bên nhận. Ảnh không đủ rõ thì ghi \"cần kiểm tra tại chỗ\".", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Xếp lại lịch, nói rõ 3 điều", "u": "mot-ngay.html#p-mot-ngay-15", "x": "Hàng bổ sung về sớm nhất [thứ Năm]. Đính kèm kế hoạch lắp đặt hiện tại.\nMình muốn: lịch mới để báo sếp chiều nay, cố giữ ngày bàn giao [___]; không giữ được thì nói rõ trễ mấy ngày, vì sao.\nCông sức: làm kỹ, tính cả việc nào làm song song được.\nKiểm tra: không tổ nào làm hai việc cùng lúc, không hạn", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Con số này lấy từ đâu?", "u": "mot-ngay.html#p-mot-ngay-16", "x": "Số [___] kg mỗi tầng kệ lấy từ tài liệu mình gửi (trang nào) hay từ kiến thức chung? Nói thẳng nhé. Việc an toàn, mình chỉ dùng số trong hồ sơ kỹ thuật của nhà sản xuất.", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Tủ lạnh còn gì, nấu nấy", "u": "mot-ngay.html#p-mot-ngay-17", "x": "Đây là ảnh tủ lạnh nhà mình. Nhà có [2 người lớn, 1 bé 6 tuổi], mình có 30 phút. Gợi ý 2 món cho bữa tối, dùng tối đa đồ đang có.", "k": "prompt"}, {"t": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "h": "Prompt: Mười lăm phút học mỗi tối", "u": "mot-ngay.html#p-mot-ngay-18", "x": "Mình muốn [nói tiếng Anh tự tin hơn khi họp], mỗi tối có 15 phút. Hỏi mình 3 câu để biết mình đang ở đâu, rồi cho bài tập đầu tiên.", "k": "prompt"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Prompt: Bạn giúp được mình việc gì?", "u": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-1", "x": "Mình làm [nghề / vị trí] ở [loại công ty]. Mỗi ngày mình hay làm [kể 3–5 việc, ví dụ: soạn công văn, đối chiếu công nợ, trả lời email khách]. Việc mình thấy mất thời gian nhất là [___].\nBạn giúp được mình những việc gì? Gợi ý 10 việc, xếp từ dễ đến khó. Mỗi việc kèm một câu mở lời để mình copy thử n", "k": "prompt"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Prompt: Đóng vai người nhận khó tính", "u": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-2", "x": "Mình sắp gửi [email / tin nhắn / văn bản] này cho [người nhận là ai, quan hệ thế nào]. Mục tiêu của mình là [___].\nBạn đóng vai người nhận khó tính nhất, đọc rồi nói thật 3 chỗ chưa ổn: chỗ nào dễ hiểu lầm, chỗ nào nghe cứng hoặc thiếu tôn trọng, chỗ nào thiếu thông tin. Xong viết lại giúp mình.\n\n[D", "k": "prompt"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Prompt: Bạn giúp được gì với cái này?", "u": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-3", "x": "Đây là ảnh [xấp hoá đơn / bảng trắng sau buổi họp / tủ lạnh nhà mình / bàn làm việc]. Bạn giúp được gì với cái này? Gợi ý 5 việc, rồi làm luôn việc bạn thấy hữu ích nhất.", "k": "prompt"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Prompt: Giúp mình nghĩ cho rõ (nói bằng giọng)", "u": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-4", "x": "Mình đang băn khoăn chuyện [___]. Bạn đừng vội khuyên nhé. Hỏi mình từng câu một để giúp mình nghĩ cho rõ. Trả lời ngắn thôi, như đang nói chuyện.", "k": "prompt"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Prompt: Phỏng vấn mình để tạo trợ lý", "u": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-5", "x": "Mình muốn tạo một trợ lý giúp mình [việc lặp lại, ví dụ: viết báo cáo tuần]. Bạn phỏng vấn mình từng câu một: mình là ai, làm việc này thế nào, thích kết quả ra sao, điều gì tuyệt đối không được làm. Khi đủ thông tin, tự viết giúp mình phần hướng dẫn để dán vào Project.", "k": "prompt"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Prompt: Làm giúp mình một công cụ nhỏ", "u": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-6", "x": "Mình muốn một [trò chơi ôn bảng cửu chương cho con 8 tuổi / bảng theo dõi chi tiêu gia đình / công cụ tính báo giá có chiết khấu và VAT] nhưng không biết mô tả thế nào cho đủ. Hỏi mình vài câu rồi làm luôn nhé. Giao diện tiếng Việt, chữ to, dễ dùng trên điện thoại.", "k": "prompt"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Prompt: Việc táo bạo nhất", "u": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-7", "x": "Mình muốn [việc táo bạo] mà chưa biết bắt đầu từ đâu, cũng không chắc AI làm được không. Bạn hỏi mình vài câu để hiểu rõ, rồi đề xuất cách làm từng bước. Phần nào bạn làm được ngay thì làm luôn, phần nào cần mình chuẩn bị thì nói rõ.", "k": "prompt"}, {"t": "Thử thách 7 ngày, 7 lần nhờ", "h": "Prompt: Tổng kết 7 ngày làm bạn với AI", "u": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-8", "x": "Đây là ghi chú 7 ngày mình thử nhờ AI, mỗi ngày một việc mới:\n[Dán ghi chú 7 ngày]\n\nGiúp mình nhìn lại:\n1. 3 cách nhờ hiệu quả nhất của mình, và vì sao hiệu quả.\n2. 2 thói quen chưa tốt mình nên bỏ.\n3. 1 việc nên biến thành quy trình dùng hằng tuần (gợi ý luôn cách làm).\n4. 5 việc nên thử trong tuần", "k": "prompt"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Prompt: Tra cứu có nguồn: câu mẫu", "u": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-1", "x": "Tìm trên mạng giúp mình: [câu hỏi]. Mình cần thông tin này để [dùng vào việc gì, cho ai đọc].\nCông sức: [tra nhanh, 3–5 nguồn là đủ / tìm kỹ, đọc nhiều nguồn uy tín].\nCách kiểm: mỗi ý ghi link và ngày, ưu tiên trang chính thức. Chưa có nguồn thì ghi \"chưa có nguồn\", đừng đoán. Cuối cùng cho mình biế", "k": "prompt"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Prompt: Kiểm tra hiệu lực văn bản", "u": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-2", "x": "Mình đang dùng [tên và số hiệu văn bản] để [soạn hợp đồng / trả lời khách]. Tìm trên mạng giúp mình: văn bản này còn hiệu lực không? Đã bị sửa đổi, thay thế bởi văn bản nào, từ ngày nào? Dẫn link nguồn chính thức: Cơ sở dữ liệu quốc gia về văn bản pháp luật (vbpl.vn), Công báo, hoặc trang của cơ qua", "k": "prompt"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Prompt: So sánh nhà cung cấp", "u": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-3", "x": "Công ty mình khoảng [số] người, ở [thành phố], cần nhà cung cấp [dịch vụ]. Tìm trên mạng 3–5 nơi, lập bảng theo [giá công bố, điều kiện hợp đồng, hỗ trợ], mỗi ô kèm nguồn và ngày. Không có thông tin công khai thì ghi \"không công bố\", đừng ước đoán. Gợi ý thêm 5 câu nên hỏi từng nơi.", "k": "prompt"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Prompt: Hồ sơ nhanh về đối tác", "u": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-4", "x": "Chiều nay mình gặp [tên công ty], mã số thuế [___] nếu có, bàn về [nội dung]. Tìm trên mạng thông tin công khai: họ làm gì, quy mô, tin nổi bật 12 tháng gần đây, mỗi ý kèm link và ngày. Gọn nửa trang, thêm 5 câu nên hỏi. Thấy công ty trùng tên thì báo mình, đừng tự chọn.", "k": "prompt"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Prompt: Giao đề bài nghiên cứu sâu", "u": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-5", "x": "Mình cần báo cáo về [chủ đề] để [quyết định gì, trình ai]. Phạm vi: [khu vực, giai đoạn]. Ba câu mình quan tâm nhất: [___].\nCứ đọc kỹ, ưu tiên nguồn chính thức, hạn chế blog. Mọi con số kèm nguồn và ngày. Tách riêng điều nhiều nguồn xác nhận, điều chỉ một nguồn nói, chỗ các nguồn mâu thuẫn. Cuối cùn", "k": "prompt"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Prompt: Rà lại nguồn", "u": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-6", "x": "Rà lại nguồn bạn vừa dùng: nguồn nào chính thức, nguồn nào báo chí, nguồn nào blog hay trang tư nhân? Nguồn nào cũ hơn 12 tháng? Nguồn nào mâu thuẫn nhau, ở điểm nào? Ý nào chỉ dựa trên một nguồn?", "k": "prompt"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Prompt: Bản đồ văn bản một vấn đề", "u": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-7", "x": "Tìm các văn bản pháp luật đang áp dụng về [vấn đề]. Lập bảng: số hiệu, cơ quan ban hành, ngày hiệu lực, tình trạng hiệu lực, link chính thức. Dự thảo để bảng riêng. Không chắc thì ghi \"cần kiểm tra\".", "k": "prompt"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Prompt: Thay đổi mới về thuế, hoá đơn", "u": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-8", "x": "Tìm các thay đổi về [thuế GTGT / hoá đơn điện tử] có hiệu lực từ [kỳ] mà công ty [ngành] cần lưu ý. Mỗi thay đổi ghi nội dung, ngày hiệu lực, số hiệu và link văn bản gốc. Tin từ báo, blog thì ghi là nguồn thứ cấp.", "k": "prompt"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Prompt: Cập nhật nhanh về đối thủ", "u": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-9", "x": "Tìm thông tin công khai mới nhất về [2–3 đối thủ] mảng [sản phẩm]: sản phẩm mới, khuyến mãi đang chạy. Lập bảng kèm link và ngày. Cũ hơn 3 tháng thì đánh dấu \"có thể đã cũ\".", "k": "prompt"}, {"t": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "h": "Prompt: Tìm công bố giá, quy chuẩn", "u": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-10", "x": "Tìm công bố giá vật liệu xây dựng kỳ gần nhất của Sở Xây dựng [tỉnh, thành] cho [vật liệu], và quy chuẩn đang áp dụng cho [hạng mục]. Ghi kỳ, số hiệu, link chính thức. Không thấy thì nói không thấy, đừng lấy số từ trang rao bán.", "k": "prompt"}, {"t": "Từ điển AI cho dân văn phòng", "h": "Prompt: Giải thích một thuật ngữ AI", "u": "tu-dien.html#p-tu-dien-1", "x": "Giải thích giúp mình từ \"[thuật ngữ]\" như đang nói với một người làm [ngành của bạn] không rành kỹ thuật. Tối đa 3 câu, kèm 1 ví dụ gần với công việc văn phòng. Nếu từ này có nhiều nghĩa tuỳ công cụ, nói rõ giúp mình.", "k": "prompt"}];